WordHunterWoW_QuestEN[85780] = { title = "Right Where We Want Him", description = "Gallywix is down, but he ain't out. \n\nThe Gallagio is built like a fortress. If we want to keep him from threatening Undermine, or Azeroth, we gotta figure out how to get him outta there. Meet me and the other bosses back at the Incontinental Hotel.", objectives = "Return to the Incontinental Hotel and speak with Gazlowe.", completion = "We got the people of Undermine to thank for the opportunity to finally put Gallywix outta business for good.\n\nI ain't gonna waste it." }
WordHunterWoW_QuestEN[85797] = { title = "Knife Fight", description = "", objectives = "" }
WordHunterWoW_QuestEN[85804] = { title = "The Parent Trap", description = "I'm happy to help in any way that I can.\n\nTo find Alleria, you must fly far north from here. She's hunting a new Shadowguard lieutenant in the hope of extracting information from him.\n\nLast I heard, she was on the outskirts of a place called the Fracture of Laacuna.", objectives = "Locate Alleria Windrunner at the Fracture of Laacuna.", progress = "It is good to see both of you, especially my beautiful son.", completion = "My sister's vision must not come to pass!\n\n<Alleria seems frustrated.>\n\nI wish I could return, but that's simply not possible. There are things I can do here, however, and you two can help while we discuss the matter." }
WordHunterWoW_QuestEN[85805] = { title = "Renowned with the Cartels of Undermine", description = "Thanks for the hard work there, pal!\n\nWe've got some supplies prepped for you in the hotel. Come grab 'em from Smaks Topskimmer.", objectives = "Speak with Smaks Topskimmer in the Incontinental Hotel.", completion = "Here you go!" }
WordHunterWoW_QuestEN[85806] = { title = "Exalted with the Bilgewater Cartel", description = "You done good for the Bilgewater when they needed you. They won't forget that.\n\nTalk to Rocco Razzboom, he'll take care of ya.", objectives = "Speak with Rocco Razzboom at the Scrapshop.", completion = "Hey, this is for you." }
WordHunterWoW_QuestEN[85807] = { title = "Exalted with the Blackwater Cartel", description = "The Blackwater Cartel is sailing smooth thanks to you. \n\nBoatswain Hardee has readied yer cut o' the plunder... that is to say, a respectable reward for your work.", objectives = "Speak with Boatswain Hardee at the Port Authority.", completion = "Here's your cut, all above board." }
WordHunterWoW_QuestEN[85808] = { title = "Exalted with Darkfuse Solutions", description = "Helpin' the Darkfuse ain't real popular, so they want to say thanks.\n\nThey gotta do it quiet like, so find Stitch Lowdown down in the sewers near Hovel Hill.", objectives = "Speak with Sitch Lowdown in the sewers near Hovel Hill.", completion = "Here ya go, buddy. The help's been much appreciated." }
WordHunterWoW_QuestEN[85809] = { title = "Exalted with the Steamwheedle Cartel", description = "The Steamwheedle Cartel wants to thank you for all the work you have done. \n\nObserve all safety protocols and see Lab Assistant Laszly for a reward.", objectives = "Speak with Lab Assistant Laszly at Steamwheedle Laboratories.", completion = "We got somethin' for ya." }
WordHunterWoW_QuestEN[85810] = { title = "Exalted with Venture Co.", description = "Venture Co. is ready to pay dividends on all the work you've done for us.\n\nSpeak to Shredz the Scrapper for your reward.", objectives = "Speak with Shredz the Scrapper at Venture Plaza.", completion = "You done good, pal. This is yours." }
WordHunterWoW_QuestEN[85811] = { title = "Thrayir, Eyes of the Siren", description = "<The power of the storm has reformed Thrayir, Eyes of the Siren.  He awaits your acceptance.>", objectives = "Accept Thrayir, Eyes of the Siren.<The power of the storm has reformed Thrayir, Eyes of the Siren. He awaits your acceptance.>", completion = "<Thrayir, Eyes of the Siren is ready to be harnessed.>" }
