WordHunterWoW_QuestEN[85913] = { title = "Side Gig: Cleanup Detail", description = "We're looking for someone with a strong arm and stronger stomach to help deal with all the blood monsters popping up in the Ringing Deeps. The cleanup crews keep getting eaten and it's murder on our schedule.\n\nYou up for it?", objectives = "Kill blood monstrosities in the Writhing Fields.", completion = "Hey, not bad. Just try not to drip everywhere, okay?" }
WordHunterWoW_QuestEN[85914] = { title = "Side Gig: Coolant Matters", description = "Sounds like the old Black Blood pipes in the Ringing Deeps are thawing out, but we haven't figured out a solution for all the goo they're packed with just yet. A few more budgetary meetings, though, and we're on it.\n\nIn the meantime, we earmarked a little cash for some temp help. That's you.\n\nGet out there and refreeze those pipes.", objectives = "Ride Pamsy's Rocketboard in the Writhing Fields and freeze the pipeline.", progress = "Try not to freeze any important bits off. We're not offering medical.", completion = "Cool." }
