WordHunterWoW_QuestEN[85929] = { title = "Archivist Rubbleglint", description = "", objectives = "The Freysworn have always observed the lunar cycles and the celestial bodies in the sky. Perhaps, in time, we can adopt their beliefs and celebrate this holiday in the cycles to come.\n\nAs is your customs I bid you well, <name>, and offer you this token..." }
WordHunterWoW_QuestEN[85930] = { title = "Archivist Coppermoss", description = "", objectives = "As you pay homage to me, remember all the great things I have done for the earthen.\n\nI, Togdhar the Brave will accept your homage and offer in return a token. \n\nHow was that? Did you think I was Togdhar?" }
WordHunterWoW_QuestEN[85931] = { title = "Archivist Farolt", description = "", objectives = "To think there were other earthen who played a role in the events that led to this 'Lunar Festival' celebration intrigues me. I am eager to learn more.\n\nAs is customary I bid you well, outlander, and offer you this token..." }
WordHunterWoW_QuestEN[85932] = { title = "Archivist Silsigra", description = "", objectives = "After listening to the Kobolds tell stories of their past to their younglings...I'm starting to see the wisdom in this holiday after all.\n\n I bid you well, outlander, and offer you this token..." }
WordHunterWoW_QuestEN[85933] = { title = "Elder Knythall", description = "", objectives = "This reminds me of an old holiday we had in the empire. I barely remember it, but I do remember how my parents loved celebrating this time of year. Moments like these make me think of my kids... \n\nI wonder if they have forgotten about me. I know I haven't forgotten about them. \n\nI accept the homage you pay, and offer in return this token... May the Flame protect you." }
WordHunterWoW_QuestEN[85934] = { title = "Elder Swornvow", description = "", objectives = "This holiday vaguely reminds me of one from home. I'm sure if I did some digging I could find it. What are the chances they are related? Hmm, much to think of. \n\nMay the flame guide you. I bid you well, <name>, and offer you this token... As the custom goes." }
WordHunterWoW_QuestEN[85935] = { title = "Elder Ikk'zivan", description = "", objectives = "I carry the threads of history, overcrawler. It is a weighty burden, but a noble one. You honor those of your past by visiting them--we honor those of ours by ensuring they are never forgotten.\n\nHere, take this token to remember the lesson you have learned today." }
WordHunterWoW_QuestEN[85936] = { title = "Elder Ikk'xataz", description = "", objectives = "Our threads seem like a burden to some. Each one carries the weight of thousands of lifetimes of history. Some strands that date back to the very beginning of our time here. \n\nBut I am honored to carry it. Through me, every life lives on. \n\nHere, take this token to remember the lesson you have learned today." }
WordHunterWoW_QuestEN[85941] = { title = "Attitude Adjustment", description = "I'm not a violent gal by nature, but there are a lot of Darkfuse out there. They're already hassling the locals and they won't like you guys asking questions. \n\nYou wanna keep your friends safe? You wanna put the locals in better spirits? It'd probably be best if there were a whole lot less Darkfuse. If you catch my meaning.", objectives = "Kill 12 Darkfuse at Tailgate Park.", progress = "My meaning was, go kill a bunch of Darkfuse so they don't kill your friends. Can't a gal be subtle?", completion = "Nice work. The Bilgewater get to sleep a little easier, and maybe feel like they got a little payback for their old boss." }
WordHunterWoW_QuestEN[85944] = { title = "Side Gig: Blood Type", description = "Darkfuse was up to all sorts of questionable research out in the Ringing Deeps and, well, everywhere, really.\n\nAnyway, they had to write some of it down. Nab whatever notes you can find and bring them back to me.\n\nDon't look at me like that. It's not intellectual dishonesty, it's industrial espionage!", objectives = "Collect 8 Darkfuse Research Notes in the Writhing Fields.", progress = "Got the goods?", completion = "Not bad, temp. But don't go expecting a tip or anything." }
WordHunterWoW_QuestEN[85945] = { title = "Side Gig: Blood-B-Gone", description = "Do you have any idea how hard it is to get dried blood stains out of your laundry? Well, you might, I guess.\n\nSteamwheedle's finest are working on a new detergent specifically formulated to deal with this pressing issue!\n\nAnd while the blood fields in the Ringing Deeps might be bad for the environment, and you, they're the perfect place to field test our latest formulations.\n\nJust give the blood slimes out there a quick hose down and let us know what happens.", objectives = "Test Blood-B-Gone on 8 blood slimes in the Writhing Fields.", progress = "We've got a market to corner here.", completion = "Any side effects from exposure? You signed the waiver, if so!" }
WordHunterWoW_QuestEN[85946] = { title = "The Great Crab Breakout", description = "", objectives = "" }
WordHunterWoW_QuestEN[85947] = { title = "An Original Journey Through Time", description = "Old warriors keep spinning tales about how things were so much tougher around Azeroth back in their day.\n\nI bet they would say you're not tough enough to last 10 minutes in their world.\n\nThink you're tough enough to find out? How 'bout you show me.", objectives = "Complete 5 Timewalking dungeons.", progress = "You're not givin' up, are ya?", completion = "You did it, <name>! Way to show those old warriors that Azeroth is still in good hands!" }
WordHunterWoW_QuestEN[85948] = { title = "A Burning Journey Through Time", description = "The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "Complete 5 Timewalking dungeons.", completion = "Ah, <name>, you have returned. An otherworldly air hangs heavy about you." }
WordHunterWoW_QuestEN[85949] = { title = "A Frozen Journey Through Time", description = "The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "Complete 5 Timewalking dungeons.", completion = "Ah, <name>, you have returned. An chill air hangs heavy about you." }
WordHunterWoW_QuestEN[85950] = { title = "Valley of Honor", description = "", objectives = "" }
WordHunterWoW_QuestEN[85951] = { title = "Valley of Spirits", description = "", objectives = "" }
WordHunterWoW_QuestEN[85952] = { title = "Valley of Wisdom", description = "", objectives = "" }
WordHunterWoW_QuestEN[85953] = { title = "The Drag", description = "", objectives = "" }
WordHunterWoW_QuestEN[85960] = { title = "Side Gig: Lost in the Sauce", description = "Some of the workers forced by the Darkfuse to work the blood fields never made it home.\n\nWe've got reports that they might be lost in whatever the \"Unseeming\" is. Apparently it's got something to do with the big blood puddles?\n\nSounds like a job for someone more expendable--I mean experienced, than me.", objectives = "Rescue 8 Lost Goblins from the Unseeming in the Writhing Fields.", completion = "Not bad, though they seem a few bolts short of a toolbox, if you know what I mean.\n\nGonna have to dock you a few gold for that one. Damaged goods and all." }
WordHunterWoW_QuestEN[85961] = { title = "Moving the Pawns", description = "There is a small island to the northwest of here, called Overlook Zo'Shuul. My scouts have been searching for a way into Manaforge Omega, where we must stop the return of the All-Devouring.\n\nIf we are fortunate, the scouts have already found a safe pathway inside.", objectives = "Meet Locus-Walker at Overlook Zo'Shuul.", completion = "I hope my scouts have found a way to safely enter the manaforge." }
WordHunterWoW_QuestEN[85962] = { title = "Side Gig: Unseemly Reagents", description = "There's all sorts of weirdness going on in the Ringing Deeps thanks to all that Black Blood still lying around.\n\nAnd where there's madness and mutation, there's opportunity!\n\nGet out there and see what sort of horrific but potentially lucrative reagents you can scrape up.", objectives = "Collect 10 Unseemly Growths in the Writhing Fields.", progress = "Try not to go crazy until after delivery, ok?", completion = "I'm sure the boys in R&D will be able to do something with...whatever these are.\n\n...do you hear whispering?" }
WordHunterWoW_QuestEN[86151] = { title = "Faceless Mask of the Burned Bridge", description = "The displaced warrior is always on uneasy footing, especially one who is removed from her home world. The void makes this unsteadiness a reality where one step can lead into the abyss or drain you to your core.", objectives = "Return the Faceless Mask of the Burned Bridge to the altar within a Horrific Vision.", progress = "Place the Faceless Mask of the Burned Bridge on the altar.", completion = "The treacherous path of the Burned Bridge will be available to you if you wish to tread it." }
WordHunterWoW_QuestEN[86152] = { title = "Faceless Mask of the Daredevil", description = "The hunter never sought to lead yet sought a challenge in life at every turn. He directed his allies with a deft hand and never shied from diving in to the melee himself. The prowess he showed made him as well as my other minions much more deadly. Return this mask to the altar of the Daredevil to challenge your own resolve in battle as your foes attacks cut even more deep.", objectives = "Return the Faceless Mask of the Daredevil to the altar within a Horrific Vision.", progress = "Place the Faceless Mask of the Daredevil on the altar.", completion = "The path of the Daredevil is available to you if you dare." }
WordHunterWoW_QuestEN[86153] = { title = "Faceless Mask of the Dark Imagination", description = "These magi, twisting their magic to manipulate and conquer the world. Imagining greater power, they tread along the lines of the voids' domain. In these pursuits, these magi came to the realization that in the depths of one's imagination lie truly dark and terrible things.", objectives = "Return the Faceless Mask of the Dark Imagination to the altar within a Horrific Vision.", progress = "Place the Faceless Mask of the Dark Imagination on the altar.", completion = "The risks at the edges of your sanity will now manifest if you so choose to engage them." }
WordHunterWoW_QuestEN[86154] = { title = "Faceless Mask of the Pained", description = "Trading in secrets, trading in lies, operating on the fringes are all the Spymaster knows. His lost passions, lost loves are all gone, crushed under his own duty and loyalty to the crown. Nothing is left, nothing but the pain. Pain is an apt tutor and tool and one in which the void knows intimately. Return my mask if you dare to feel the many forms pain can take.", objectives = "Return the Faceless Mask of the Pained to the altar within a Horrific Vision.", progress = "Place the Faceless Mask of the Pained on the altar.", completion = "As my madness and torment is not enough, feel free to invite even more pain in the future." }
WordHunterWoW_QuestEN[86155] = { title = "Faceless Mask of the Long Night", description = "The endurance needed to make it this far is extraordinary and the feat of a long experienced adventurer. Yet, the longest night is nigh and with it our ultimate conquest. Those that fight the coming of eternal twilight know only futility, for in the Longest Night they will be on the edge of sanity forever.", objectives = "Return the Faceless Mask of the Long Night to the altar within a Horrific Vision.", progress = "Place the Faceless Mask of the Long Night on the altar.", completion = "Taking a step towards the Longest Night is already acknowledging the sanity you have lost. Do you risk the rest on such a fools errand?" }
WordHunterWoW_QuestEN[86156] = { title = "Getting Involved", description = "You. Do that again. Could be good stuff we ain't seen yet. \n\nGet those caves open an' see what's in there!", objectives = "Contribute 10 times to events on the Siren Isle Command Map and complete one event by slaying the target.", progress = "Did you check out the cave? No? Get goin' then!", completion = "Dat was pretty easy. We should do more!" }
WordHunterWoW_QuestEN[86174] = { title = "Special Assignment: Storm's a Brewin", description = "", objectives = "" }
WordHunterWoW_QuestEN[86177] = { title = "Side Gig: The Tides Provide", description = "You look like the type who ain't shy to get your hands dirty. Up for a little treasure hunting?\n\nWord has it that a ship exploded not far off the Kaja'Coast. Go to shore and see what the tide's brought in.\n\n\"Finders keepers\" is one of the foundational tenets of goblin society, after all.", objectives = "Collect 5 Shiny Treasures along the Kaja'Coast.", progress = "Gotta bring your own shovel. I never supply nothin', that's a liability waitin' to happen.", completion = "A fine haul!\n\nDon't worry, I'll get you a share of the loot." }
WordHunterWoW_QuestEN[86178] = { title = "Side Gig: Cleanin' the Coast", description = "It's time for the Venture Company to earn a lil' good faith.\n\nWe're lookin' to hire some efficient workers like yourself to clean up the Kaja'Coast.\n\nCould you help us kill some of the kaja'mentals that have gone... well, mental out there? We'll toss some competitive compensation your way.", objectives = "Kill 10 Agitated Kaja'mentals on the Kaja'Coast.", completion = "Thanks for the help, bud.\n\nEasy work, easy profits." }
WordHunterWoW_QuestEN[86179] = { title = "Side Gig: Lucky Break's Big Break", description = "You know the Lucky Break Mines over on the Kaja'Coast? Settin' those up was kind of a rush job. Darkfuse didn't exactly give Venture a whole lotta time to reinforce the place.\n\nLong story short, there's a good chance the mines might collapse if we don't fix 'em up. That wouldn't be good news for anyone, especially not my wallet.\n\nCould you head over and rig up some support beams in the mines? That should do the trick for now.", objectives = "Place 6 Support Beams in the Lucky Break Mines on the Kaja'Coast.", completion = "That should buy us some time.\n\nGood work, pal." }
WordHunterWoW_QuestEN[86180] = { title = "Side Gig: Infested Waters", description = "So, my workers were supposed to be loadin' up some kaja'mite over in Zuldazar, but apparently the transport got upended and a shark swallowed the whole crate.\n\nI tried submittin' an insurance claim, but they ain't buyin' it. So we got no choice but to get that kaja'mite back ourselves.\n\nDown for a little shark huntin'?", objectives = "Retrieve the Swallowed Kaja'mite from the Kaja' Carrying Razormaw on the Kaja'Coast.", progress = "You think the shark might end up bein' able to talk? I kinda want a talkin' shark.", completion = "Good stuff, <name>. That's a whole lot less paperwork I gotta deal with now.\n\n...You rinsed off that kaja'mite after you gutted the shark, right?" }
WordHunterWoW_QuestEN[86182] = { title = "Ghost Buster", description = "I have been working on the Oasis console and I believe I am ready for the next step. It will involve destruction, so naturally I thought of you.\n\nI need you to use a phase conduit to shift into the Untethered Space of K'aresh and retrieve the essence of the ghostly slatebacks. I will explain more when you return.", objectives = "Collect 10 Slateback Essence in the Untethered Space of K'aresh.", progress = "Well? Have you succeeded?", completion = "Excellent. \n\nNow, we raise the dead." }
WordHunterWoW_QuestEN[86183] = { title = "The Power of Gods", description = "Today, we create life. \n\nAssuming my calculations are correct--which they are--we can use the essence you gathered along with the data we have collected to create new slatebacks.", objectives = "Help Ve'nari use her machine to create life in the Oasis.", progress = "Has the experiment succeeded?", completion = "Well done, <name>. Certainly a first." }
WordHunterWoW_QuestEN[86184] = { title = "Diminishing Returns", description = "The machine has its uses, but the slatebacks must start breeding so they can sustain themselves. Thus far, they have shown no inclination to do so.\n\nTake this device and use it to collect the slatebacks for testing. Om'talad will review the data.", objectives = "Shrink and collect 10 Slateback Roamers.", progress = "Have you brought in the slatebacks as requested?", completion = "Thank you. The data we gather from this will be invaluable." }
WordHunterWoW_QuestEN[86185] = { title = "Running Free", description = "Been talkin' to Ve'nari and Om'talad--trying to help the slatebacks get together. \n\nApparently slatebacks used to display virility by engaging in races. \n\nChallenge the slateback alpha to a race. At worst, you'll both get some exercise. At best, it will increase the likelihood of a successful pairing.", objectives = "Race the Slateback Alpha.", progress = "How's the race going?", completion = "Ah! That was a good race, <name>!\n\nCross yer fingers, eh? Maybe this'll do the trick." }
WordHunterWoW_QuestEN[86186] = { title = "The Super Sniffer", description = "It appears the slatebacks are not secreting the correct pheromones, resulting in them not breeding. \n\nWe believe this is a side effect of the stasis. The technology was never tested for such an extreme length of time. Until now. \n\nHemet tells me there are creatures called niffen in Azeroth that have expertise in this research. Bring me one from Azj-Kahet. You can use my portal to quickly get there.", objectives = "Travel to Mmarl in Azj-Kahet in Khaz Algar and find a willing niffen to help in the Oasis.", progress = "I'm smellin' opportunity all over you!", completion = "Good hagglin'! Let's get this transaction underway!" }
WordHunterWoW_QuestEN[86187] = { title = "The Smallest Possible Effort", description = "You're a shrewd negotiator, {name}. That's good fun! I'll start packing. You go get some bug bits for me, okay?", objectives = "Collect 50 Bug Bits in Rak-ush and the nearby area.", progress = "How'd it go?", completion = "There we go! Just what I was lookin' for. Hope that wasn't too hard for ya!" }
WordHunterWoW_QuestEN[86188] = { title = "More-shrooms", description = "Poor Gharrli needs to be set up while I'm away. The mushrooms you get will help with that.\n\nGet eight of them for now. We'll worry about the last one later!", objectives = "Collect 8 Rak-ush Mushrooms from Rak-ush and the nearby area.", progress = "Got them mushrooms?", completion = "Great. Great!" }
WordHunterWoW_QuestEN[86189] = { title = "Fungal Invasion", description = "I'm sending you somewhere a lil scary, but I'm sure you can handle anything that comes your way!\n\nMind clearing up some of the creatures so it'll be easier for Gharrli to gets the ingredients in the future?", objectives = "Slay 10 monsters in Pillar-nest Vosh.", progress = "Did ya get 'em?", completion = "I get along fine with nerubians, but those things...\n\nThose things scare me. Glad they're gone. Phew!" }
WordHunterWoW_QuestEN[86190] = { title = "One Mushroom to Rule Them All", description = "We've been working on a new scent to delight the locals, but we have one more ingredient we need. \n\nIt's a rare mushroom from Pillar-nest Vosh. Get that, and Gharrli can finish the fragrance while I'm away!", objectives = "Collect a Voshsroom from Pillar-nest Vosh.", progress = "Did you get that mushroom?", completion = "Oooooh yes. That is it. That is the smell that will revolutionize everything! Great job, <name>!" }
WordHunterWoW_QuestEN[86191] = { title = "Smell Ya Later", description = "Well. That's everything, I think. I'm ready for adventure!", objectives = "Meet Rhubarn and Ve'nari in the Oasis on K'aresh.", progress = "This is a big sniff for me, <name>!", completion = "You have brought me a most... unusual friend, <name>. Odd, but charming." }
WordHunterWoW_QuestEN[86192] = { title = "On a Bed of Bones They Lie", description = "I was talking to Om'talad over there. Apparently, slatebacks used to gather bones for birthing nests, which is kinda funny on account of them being herbivores! \n\nNormally they get bones from dead animals, but we don't have any in the eco-domes. Can you gather some bones from creatures outside the Oasis for me? They'd appreciate it, and so would I!", objectives = "Collect 8 Creature Bones from around K'aresh and place them in a pile in the Oasis.", progress = "Have you built the nests as requested?", completion = "Thank you, <name>. I cannot imagine how this could possibly be comfortable, but of course I am not a slateback." }
WordHunterWoW_QuestEN[86193] = { title = "Life for Life", description = "We're too late! The ritual is self-sustaining. It'll draw in more power until it overloads the machine. Tazavesh, the eco-domes--nothing will be safe if the failure cascades. \n\nIf we remove the infusers, the energy should dissipate before it can cause any harm. It's too powerful though. It will tear you apart if you try to get close, and I'm not strong enough to do it alone...\n\nUnbind me. I'll wrap you in my energy. That should be enough to let you get close to the machine.", objectives = "Stop the machine.", completion = "Are you alright? I tried to protect you from the blast.\n\n<Om'taha flickers in and out of sight.>\n\nSorry. That took a lot. I just need a moment." }
WordHunterWoW_QuestEN[86194] = { title = "The Scent of Love", description = "I was out and about checking on these slatebacks of yours, and your broker friends are wrong!\n\nThe slatebacks are giving off the smell of love, but it's just not strong enough to overpower all this dry air on K'aresh. Not yet anyway! I whipped up a batch of pheromones that should fix them right up!\n\nTake this sprayer and douse the slatebacks. That'll get things started!", objectives = "Douse 12 Slateback Roamers in pheromones.", progress = "Have you got them smellin' better?", completion = "Give it a bit, <name>. Can't rush love!" }
WordHunterWoW_QuestEN[86195] = { title = "Slateback Soccer", description = "Oh my. I never thought I would see the day. A newly born slateback!\n\nI have been running standard non-invasive medical tests. However, I also need a test of its coordination. I have been noticing it chasing this ball around. Perhaps you could throw it and observe the results?", objectives = "Catch a ball 10 times while playing with your Slateback Cub.", progress = "Has the cub responded to the ball?", completion = "Vitals are perfect, and coordination is even better than I had hoped. Thank you for playin--er, testing the cub's coordination." }
WordHunterWoW_QuestEN[86196] = { title = "Give Me Fuel", description = "Thank you for coming, {name}.\n\nThere are many dangers we face when attempting to terraform K'aresh, not the least of which is attracting creatures that see the domes as convenient energy sources.\n\nEco-Dome: Springhost is plagued with them. I have a plan to remedy this, but I could use your help preparing.", objectives = "Gather Firebud Pollen for Om'vek.", progress = "Have you gathered enough pollen for me?", completion = "Perfect, <class>. With our equipment, we'll be able to unlock the power within this humble plant." }
WordHunterWoW_QuestEN[86200] = { title = "Give Me Fire", description = "Now we need to process this firebud pollen into fuel. And with this fuel, the downfall of these pests will be assured.", objectives = "Process the Firebud Pollen into fuel.", progress = "Just place the firebud pollen into the containers on the console, and we'll get it refined into something we can use.", completion = "Excellent. I hope you're ready to bring the wrath of the brokers down onto these troublesome creatures." }
WordHunterWoW_QuestEN[86201] = { title = "Watch Me Make These Bugs Expire", description = "Now that we've processed this firebud pollen, we can bring some flame to bear against our pests in Eco-Dome: Springhost.", objectives = "Use the flamethrower to force the glutted creepers off of the dome, then destroy them.", progress = "Have you cleansed the eco-dome with the flame I've provided?", completion = "The eco-dome shield integrity is returning to normal levels. I knew I could count on your race's predilection for fire, <race>." }
WordHunterWoW_QuestEN[86203] = { title = "Operation: Floodgate", description = "My sources report that Darkfuse forces have infiltrated the Waterworks down in the Ringing Deeps. They have seized the power generators there and are rerouting the electricity somewhere else.\n\nWe do not know their directive, but I am not keen to find out.\n\nDismantle their operation and I will see that you are adequately rewarded.", objectives = "Biergoth wants you to confront Geezle Gigazap within Operation: Floodgate.", progress = "Have you ended the operation?", completion = "The Councilward will be pleased to hear that the Waterworks are back in earthen hands.\n\nGood work, outlander." }
WordHunterWoW_QuestEN[86204] = { title = "Liberation of Undermine: The House Loses", description = "Gallywix has been a stain on Undermine since he forgot where he came from.\n\nGallywix's always been steppin' on the little guy--greed and always looking for the \"next best thing\" is just makin' him step even harder. Seeking power just for its own sake? Forget that! The power lies with the people.\n\nLet's bring Gallywix some swift justice, {name}.", objectives = "Defeat Chrome King Gallywix in the Liberation of Undermine.", completion = "I can't believe it..." }
WordHunterWoW_QuestEN[86261] = { title = "Homeward Bound to Safer Shores", description = "<Upon seeing you walk into camp this dirty, matted dog perks up. His tail wags when he sees the familiar face of the person who found his favorite toy.\n\nThe faded tag around its neck reads: \"The Duke.\"\n\nHe seems to have been here since the Kul Tirans disappeared and has somehow survived the isle's many perils.\n\n\"The Duke\" looks at you longingly and nuzzles your hand, seeking affection.>", objectives = "Pet the goodest boy.", progress = "<The dog looks at you with hope gleaming in its old eyes.>", completion = "<Marmaduke seems to want to follow you off of the island to new adventures. \n\nHe grips his favorite toy in his mouth, his tail wagging happily.\n\nHopefully, this is the start of a beautiful new friendship.>" }
WordHunterWoW_QuestEN[86271] = { title = "Sanity's Rest", description = "Looks like another one down the hatch, huh? \n\nI'm tellin' ya, these Black Blood dig sites are chewin' up workers faster than I can hire 'em! Every day, one of my guys goes down with the shakes, sproutin' nonsense about seein' tentacles in the dirt... \n\nTake 'em to see my guy, Stitchoaf, in the cave over there. He's brewin' up some kinda \"cure.\" \n\nSee if he can't help this poor guy out.", objectives = "Carry the Incapacitated Worker inside the cave in the Ringing Deeps.", progress = "I'm already short. I mean, short-handed!", completion = "That's the third one today. \n\nGettin' worse out there." }
WordHunterWoW_QuestEN[86272] = { title = "Counteracting the Black Blood", description = "Black Blood? Nasty stuff. Glad I got this mask here. Nobody should be workin' in that mess.\n\nIt gets inside ya, messes with ya head. Some folks get dizzy, seein' things that ain't there. Some even sproutin' strange scales. Makes me itch thinkin' about it.\n\nAn' there ain't no cure. Best we can do is ease the pain an' maybe help the symptoms a bit.\n\nI got a \"cure\" brewin'. It's just soup, but they don't know that. \n\nIt's almost \"done,\" but it could use some flavor.", objectives = "Help Stitchoaf ease the goblin's symptoms in the Ringing Deeps.", progress = "I got the pot simmerin'. All it needs is a few finishing touches.", completion = "Chicken soup is good for a lot of things. Dunno if the mouthwash'll help though.\n\nAt least they'll smell better?" }
WordHunterWoW_QuestEN[86273] = { title = "Visit to the Shop", description = "That's all we can do for now.\n\nBut if you really wanna help us fix all this, you ought to talk to our local engineer--uh, Tricksy... or maybe Trixxy. \n\nShe's got her workshop set up further down in the cave, and Benny's got her tinkerin' away day and night on some kind of... \"permanent solution.\" \n\nOdd, but she's sharp as a blade. If anyone's got a chance at makin' people safe down here, it's her.", objectives = "Find Trixxie Boltcrank's workshop further in the depths of Sanity's Rest in the Ringing Deeps.", completion = "Ey! Can't ya see I'm busy here? \n\nWhaddaya want?" }
WordHunterWoW_QuestEN[86274] = { title = "Automation Solution", description = "As you have probably figured out, Black Blood exposure is bad for your health. And that's a problem for our operation. \nWe can't keep replacin' our workers. It's expensive, and it ain't ethical.\n\nSo! What's the solution? Replacin' our workers with my fully-automated bots.\n\nThese beauties don't get affected by Black Blood exposure. They just dig and haul--precision, efficiency, an' no more sick workers!\n\nI just need more scrap to patch 'em up. You in?", objectives = "Collect metal scrap lying around the cave in the Ringing Deeps.", progress = "Time is... you know what it is.", completion = "Nice! This'll get 'em patched up and good to go!" }
WordHunterWoW_QuestEN[86275] = { title = "Bug Exterminator Needed", description = "Well, if ya really wanna help...\n\nWe're safe in this cave from the Black Blood--or we were until it was crawlin' with nasty bloodfeasters.\n\nThe ugly little creeps always had a taste for blood--but now they're gonzo for Black Blood! I got a hunch they're spreadin' Black Blood poisonin' when they bite us.\n\nI can't work like this. Each time I see one in a scrap pile, I wanna scream. They're gross, an' I don't wanna get bit an' start seein' things.\n\nStomp 'em flat so we can keep safe an' keep workin'!", objectives = "Kill Bloodfeasters inside the cave in the Ringing Deeps.", progress = "<Humming a catchy tune.>\n\nAhh!\n\nOh, I thought you were another bloodfeaster.", completion = "Bleh. Disgusting, but effective. Now I can get back to work!" }
WordHunterWoW_QuestEN[86276] = { title = "Out in the Fields", description = "If Trixxie has those bots ready, then all we gotta do is mark where they needa work. \n\nHead out, fire a flare, and deploy those tin cans--an' see if they actually, yanno, work.\n\nWatch for glitchy servos, smokin' coolant vents... You know the drill. \n\nIf they start doin' their work? Great. \n\nIf not, well... I might be callin' some workers back in to clean up.", objectives = "Deploy goblin bots in the Writhing Fields in the Ringing Deeps.", progress = "The longer it takes us to deploy those bots, the longer my workers gotta be in that Black Blood sludge.\n\nAnd the longer I have to pay 'em!", completion = "They worked? I mean, of course they did!" }
WordHunterWoW_QuestEN[86277] = { title = "\"Worm\" Food No More", description = "We've got the bots workin' the fields, but there are still flesh-an'-blood workers out there.\n\nThey need to be able to get back here safely, an' they can't do that with a giant, slobberin' \"worm\" doggin' their steps 'cause it's got a taste for goblin meat.\n\nSo, here's the job: I don't want that thing scared off, I want it gone. Go out there, track down that overgrown \"earthworm\", and make sure it dies. \n\nDon't hold back--I want guts everywhere. Payback for all the goblins it's had for lunch.", objectives = "Kill the Maddened Eyestalk in the Writhing Fields in the Ringing Deeps.", completion = "Whoa, I see you took my words to heart!\n\nRemember to hit the shower after you're done here, okay?" }
WordHunterWoW_QuestEN[86297] = { title = "Morale Reflects Leadership", description = "Undermine swallows everything that's good. Now it got Laslo. We need to find who's in charge now and figure out how to keep 'em safe. I think I know where to start askin'.", objectives = "Find the goblin in charge of the Bilgewater Cartel in Undermine.", progress = "This ain't no place for good goblins.", completion = "At least no single goblin is Gallywix's next target, for now. That will give us time to deal with the Black Blood. Then we can figure out how to get my people out of Gallywix's grasp." }
WordHunterWoW_QuestEN[86305] = { title = "Watch me Make these Bugs Expire", description = "", objectives = "" }
WordHunterWoW_QuestEN[86311] = { title = "Heaps of Trouble", description = "", objectives = "" }
