WordHunterWoW_QuestEN[86314] = { title = "Ooze on Aisle 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[86315] = { title = "Chaos in the Streets", description = "", objectives = "" }
WordHunterWoW_QuestEN[86317] = { title = "Black Blood by Sea", description = "", objectives = "" }
WordHunterWoW_QuestEN[86318] = { title = "Tailgater Troubles", description = "", objectives = "" }
WordHunterWoW_QuestEN[86319] = { title = "Eyes of the Sky", description = "", objectives = "" }
WordHunterWoW_QuestEN[86320] = { title = "Bully For You!", description = "", objectives = "" }
WordHunterWoW_QuestEN[86321] = { title = "Door to Door", description = "", objectives = "" }
WordHunterWoW_QuestEN[86327] = { title = "The Tempest Fields", description = "Those Wastelanders have that broker's ribbon. We must get it back or you will never be able to reach Dimensius.\n\nThey are deliciously bloodthirsty. I think we should lure them to our cause. We need an army for the coming battle, and they have the numbers for that.\n\nThe void glass lies between their camp and us. That might provide a means to manipulate--speak with the Wastelanders.", objectives = "Meet Xal'atath in the Tempest Fields.", completion = "The aura of Dimensius is tearing what's left of K'aresh apart. Soon he will draw in what remains of this little world.\n\nOur time to stop him grows shorter by the hour." }
WordHunterWoW_QuestEN[86332] = { title = "Distribution of Power", description = "My people need energy to live. We can harvest it from the pylons that were set out to collect it or hunt the energy scavengers that have siphoned off what is ours.\n\nLet's gather today's meager bounty of energy and then distribute it to my people. If we are to go to war together, it will help us both to know the character of your allies.", objectives = "Collect and distribute harvested energy in and around the Wastelander Camp.", progress = "In the wastes of Merciless K'aresh, survival is all-important. We take what we need to ensure our future.", completion = "Your help does not go unnoticed. My people will live another day, and hopefully many more, thanks to the energy that's in those crates." }
WordHunterWoW_QuestEN[86339] = { title = "Oasis Overdrive", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[86340] = { title = "Oasis Overdrive - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[86341] = { title = "Oasis Overdrive - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[86342] = { title = "Soaring over K'aresh", description = "We've been taking the k'arrocs out for flights outside of the Oasis. Perhaps you might be interested in riding one?", objectives = "Complete the \"Oasis Overdrive\" race.", completion = "Splendid. It was enjoyable to watch both the k'arroc and yourself flying around out there. \n\nYou are quite the accomplished rider, <name>." }
WordHunterWoW_QuestEN[86348] = { title = "Fox Bane", description = "You have done well with the slatebacks. Will you do as well with the thorntails?\n\nIf we are to improve their numbers, we will need some of their astral essence to produce new ones. Procure it for me.", objectives = "Collect 10 Thorntail Essences while Phase Diving in Untethered Space on K'aresh.", progress = "Do you have the essences?", completion = "You are reliable, as always." }
WordHunterWoW_QuestEN[86349] = { title = "Lapbug Essence Hunter", description = "Thorntails are known to hunt smaller creatures. If we are to increase their numbers, we should also increase the numbers of the lapbug population to compensate.\n\nGather some of their astral essence. You can use a phase conduit to get into Untethered Space.", objectives = "Collect 10 Lapbug Essence in Untethered Space on K'aresh.", progress = "How fare your efforts?", completion = "Excellent. I shall take it from here." }
WordHunterWoW_QuestEN[86350] = { title = "Eau de Foxy", description = "It's my favorite {race}! \n\nI've been sniffing around the Oasis and I've whipped up a batch of pheromones for those thorntails out there. Can you give them a good dose for me?\n\nLet Om'talad know when you're done--he was lookin' to do some testing too!", objectives = "Douse 8 Regal Thorntails in pheromones.", progress = "Did you apply the pheromones?", completion = "Ah, thank you for your assistance as always." }
WordHunterWoW_QuestEN[86351] = { title = "Strike a Pose", description = "We are running low on food for the thorntails. It is odd. They should be hunting for a larger portion of their food.\n\nCan you take some pictures of them for documentation purposes? Perhaps it will shed some light on the issue.", objectives = "Document 10 Regal Thorntails.", progress = "Have you taken the photos?", completion = "They are not hunting at all? This is unacceptable. We will need to find a solution posthaste." }
WordHunterWoW_QuestEN[86352] = { title = "Hunting for a Good Author", description = "I am growing concerned that we may be in danger of overbalancing the ecosystem. We require a consultant. \n\nHave you read \"The Green Hills of Stranglethorn?\" I enjoyed it a great deal. The author appears to have turned from hunter to conservationist. Do not ask how I acquired this information. \n\nHowever, these are precisely the two skills I need. Retrieve him. Last I heard, he was in the Azure Span on the Dragon Isles. Use the portal to travel there.", objectives = "Look for Hemet Nesingwary in the Azure Span on the Dragon Isles.", completion = "If ye need my help, I need yours first." }
WordHunterWoW_QuestEN[86353] = { title = "Protecting the Young", description = "These gnolls have kidnapped children from Iskaara. I was going to sneak in and rescue them, but I could use some help. \n\nLet's split up. Two sets of eyes are better than one. If you spot any kids, tell 'em to gather at this spot. Tell them Hemet sent you. They know me.", objectives = "Rescue 6 Tuskarr Children in the Brakenhide Brambles.", progress = "We have to rescue those children! Who knows what the gnolls will do to them?", completion = "Good job, <name>. \n\nHave to say, I was pretty glad when you showed up. Don't know if I'd have been able to manage it myself." }
WordHunterWoW_QuestEN[86354] = { title = "A Percussive Antidote", description = "These gnolls have been corrupting the land--growing too big and throwing off the ecosystem.\n\nWe need to stop them, and let this land recover from all that decay.", objectives = "Slay gnolls and their minions in and around the Brakenhide Hollow.", progress = "I don't relish the kills, but it has to be done.", completion = "We've cut out the corruption here. In time, the land'll recover." }
WordHunterWoW_QuestEN[86355] = { title = "Using the Whole Animal", description = "K'aresh, eh? Sounds a bit like Netherstorm.\n\nI've been staying with the tuskarr for a while an' learning what I can from 'em. I was supposed to gather meat for the evening meal. If you can do that, I can start packing.", objectives = "Collect 20 Bruffalon Meat nearby in the Azure Span.", progress = "Make sure you harvest the whole animal. It'll go faster.", completion = "This ought to be enough tae feed the whole village!" }
WordHunterWoW_QuestEN[86356] = { title = "Sustainable Harvesting", description = "I'd like to repay the tuskarr's kindness for hosting me. They have some repairs that need doing.\n\nCan ye gather some wood for them? They can handle the repairs themselves--they just need a bit of help gatherin' the materials.", objectives = "Collect 12 Chopped Wood nearby in the Azure Span.", progress = "Did ye get the wood?", completion = "That ought to be plenty for every project they've got!" }
WordHunterWoW_QuestEN[86357] = { title = "Time for Noms", description = "The local ottuks have a symbiotic relationship with the tuskarr, and it's feeding time.\n\nCan ye put out some of the meat ye gathered for them?", objectives = "Place a Pile of Meat for the local ottuks just outside Iskaara.", progress = "Have ye fed those ottuks yet?", completion = "Good work! Full bellies ought to keep 'em happy enough." }
WordHunterWoW_QuestEN[86358] = { title = "Any Old Excuse", description = "This'll be the hardest task for ye yet.\n\nThe ottuk pups have to get acclimatized to touch. I... I need ye to go pet them. \n\nHard work, but it has to be done.", objectives = "Pet 5 Ottuk Pups outside of Iskarra.", progress = "What do you think of the wee li'l pups?", completion = "I appreciate ye making such a big sacrifice, <name>. Your work here will never be forgotten." }
WordHunterWoW_QuestEN[86359] = { title = "Return to K'aresh", description = "Right then. I'm ready to go. How do we get there?", objectives = "Return to the Oasis on K'aresh.", completion = "I have prepared myself for this moment, and yet I find myself... nervous. You may go, <name>. The author and I have much to discuss." }
WordHunterWoW_QuestEN[86360] = { title = "Fantastic Ms. Fox", description = "The thorntails aren't hunting like they're supposed tae?\n\nVe'nari said that lapbugs aren't their normal prey. We'll need to teach the matriarch how to hunt them ourselves!", objectives = "Teach the Thorntail Matriarch to hunt Lapbug Skitterers 10 times.", progress = "Is she hunting properly?", completion = "If you told a younger me I'd be teaching animals how to hunt, I'd have laughed you away." }
WordHunterWoW_QuestEN[86361] = { title = "Are You Kitting Me?", description = "We need to ensure that the thorntail kits' reflexes are sharp so they are effective hunters when they grow up.\n\nPlease take this ball and have a kit chase it. For scientific purposes, of course.", objectives = "Catch a ball 10 times while playing with your Thorntail Kit.", progress = "Has a kit been sufficiently trained?", completion = "Excellent--play can be as useful as training, on some occasions." }
WordHunterWoW_QuestEN[86362] = { title = "What Does the Fox Dream?", description = "I'd like to get some medical data on how the thorntails are doing. Please gather some blood samples for me.\n\nUse these to tranquilize the creatures. There should be more than enough blood for sampling on the darts when you retrieve them.", objectives = "Collect 5 Blood Samples.", progress = "Have you gathered the samples we need?", completion = "Excellent! Exactly what I needed. Perhaps you would like a full time position here?" }
WordHunterWoW_QuestEN[86363] = { title = "The Better Part of Valorstones", description = "It's been many months since we arrived in Dornogal and there's still more to learn of Valorstones. It turns out they can be found beyond Azeroth! This discovery opens up entirely new avenues of research.\n\nWith new research comes a need for new supplies. Bring me some, and we'll help upgrade your gear to new heights.", objectives = "Collect 50 Valorstones while adventuring in Khaz Algar, Undermine, and K'aresh, then return to Cuzolth and upgrade a piece of Season 3 equipment.", progress = "There's no need to hurry. But if you wouldn't mind hurrying anyway...", completion = "My friend! I knew I could count on you. Please take these tokens for your effort." }
WordHunterWoW_QuestEN[86364] = { title = "Crests from the Ether", description = "Wonderful. Valorstones are capable of upgrading lower-level equipment on their own. \n\nThat being said, Valorstones can only do so much. More powerful equipment will also require Ethereal Crests to upgrade to their full potential. These crests are rewarded through many different activities. Ethereal Crests have four tiers, and more dangerous tasks reward you with higher-tier crests.\n\nBring me fifteen Weathered Ethereal Crests, and we can help you upgrade some gear further.", objectives = "Acquire 15 Weathered Ethereal Crests by defeating unique creatures, conquering raids, completing world activities, or by looting caches. Then return to Vaskarn in Dornogal.", progress = "If you're having a hard time finding Weathered Ethereal Crests, you can search for hidden treasures around Khaz Algar, Undermine, or K'aresh. There's no shortage of those treasures!", completion = "This is wonderful. I'm excited for you to grow in power! And to advance my research, of course. But yes, your power growth!" }
WordHunterWoW_QuestEN[86365] = { title = "Crest Transmutation", description = "My friend, these Crests are magnificent. It looks like they can be transmuted into different tiers!\n\nIf you find yourself no longer in need of a lower-tier Crest, then I can transmute them to be more powerful. I can also transmute Crests into a weaker tier.\n\nLet's practice the transmutation process. Here's a few Carved Ethereal Crests. Speak to me and I can transform them into Weathered Ethereal Crests for you.", objectives = "Bring 15 Carved Ethereal Crests to Vaskarn in Dornogal, then trade them for a Pouch of Weathered Ethereal Crests.", progress = "If you lose those Carved Ethereal Crests, you can find more from powerful creatures around K'aresh. I've heard there's quite a variety of them!", completion = "Remarkable!\n\nKeep in mind I can only transmute Crests into a higher tier when you have outgrown their usefulness, and it will be a costly process. Thank you for all of your help!" }
WordHunterWoW_QuestEN[86367] = { title = "Grub Stompin'", description = "", objectives = "" }
WordHunterWoW_QuestEN[86368] = { title = "[DNT] Repeatable - Camp 001", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[86369] = { title = "A Sparkling Fortune", description = "You came right on time, <class>.\n\n<Custodian Khubon shows you a fractured crystal.>\n\nThis is a fractured spark of fortunes. Using a reagent like this on your gear will make the difference between great and magnificent.\n\nHowever, it is somewhat useless as it is nothing but a fragment. If you chance upon another in your adventures, bring it to me. Once you show me another, I will let you have this one so you can combine them into a spark of fortunes.", objectives = "Find another Fractured Spark of Fortunes.", progress = "Were you able to find a fractured spark of fortunes? Is that a yes? No?", completion = "Excellent! Combine the two fractured sparks of fortunes to create a powerful spark of fortunes. You can always combine more using your own crafting efforts." }
WordHunterWoW_QuestEN[86372] = { title = "Wasting the Wastelanders", description = "", objectives = "" }
WordHunterWoW_QuestEN[86388] = { title = "Spark - Template", description = "", objectives = "" }
WordHunterWoW_QuestEN[86390] = { title = "Noggenfogger Nuisance", description = "", objectives = "" }
WordHunterWoW_QuestEN[86391] = { title = "Taking Back our Power", description = "", objectives = "" }
WordHunterWoW_QuestEN[86392] = { title = "Foxy Footwork", description = "Your efforts in teaching the matriarch to hunt have been too effective, it seems. Several broker guards have been attacked recently. \n\nSince you caused this issue, I need you to solve it. Best the thorntail matriarch in a fight. The rest of the thorntails will back down once their leader is humbled.", objectives = "Challenge and defeat the Thorntail Matriarch.", progress = "Have you made a suitable display of dominance?", completion = "I knew you would be effective in this situation. I did not know it would be such a pleasure to watch you accomplish your task." }
WordHunterWoW_QuestEN[86395] = { title = "Stealing the Stolen", description = "", objectives = "" }
WordHunterWoW_QuestEN[86396] = { title = "The Better Part of Valorstones", description = "Months into our stay in Dornogal and we're still learning about Valorstones! They seem to have limitless potential in empowering gear to its limits.\n\nBut I'm running low on research supplies. Could you bring me some? Cuzolth will be happy to help you upgrade some of your gear. He will. I'll make sure of it. <Vaskarn grins at Cuzolth.>", objectives = "Collect 50 Valorstones while adventuring in Khaz Algar, then return to Cuzolth and upgrade a piece of Season 2 equipment.", progress = "There's no need to hurry. But if you wouldn't mind hurrying anyway...", completion = "My friend! I knew I could count on you to bring me more Valorstones. Please take these tokens for your trouble." }
WordHunterWoW_QuestEN[86399] = { title = "Don't Undermine the Crests", description = "As you can see, upgrading your lower-level equipment is easy and only requires Valorstones.\n\nHowever, Valorstones can only do so much. You'll also need Undermine Crests to develop your equipment to its peak for your upcoming adventures.\n\nThese Crests are rewarded through different activities. Undermine Crests have four tiers, and more dangerous tasks reward you with higher-tier crests.\n\nBring me fifteen Weathered Undermine Crests, and we can help you upgrade some gear further.", objectives = "Acquire 15 Weathered Undermine Crests by defeating unique creatures, conquering raids, completing world activities, or by looting caches. Then return to Vaskarn in Dornogal.", progress = "If you're having a hard time finding Weathered Undermine Crests, you can search for hidden treasures around Khaz Algar or those underground areas, including Undermine. There's no shortage of those treasures!", completion = "This is wonderful. I'm excited for you to grow in power! And to advance my research, of course. But yes, your power growth!" }
WordHunterWoW_QuestEN[86401] = { title = "Crest Transmutation", description = "My friend, these Crests are magnificent. Did you know you could transmute them into different tier of Crest? I have the tools here to do it... hang on... I know they're here.\n\nAh, yes. If you need to transmute your Crests to a lower tier, that's easy. I can do that for you. If you want to transmute them to be more powerful, you'll need to outgrow the lower tier of crest so you have no use for them anymore. I can convert them for you then, but it's costly.", objectives = "Bring 15 Carved Undermine Crests to Vaskarn in Dornogal, then trade them for a Pouch of Weathered Undermine Crests.", progress = "If you lose those Carved Undermine Crests, you can find more from powerful creatures around Khaz Algar. I've heard there's quite a variety of them!", completion = "Remarkable, isn't it?\n\nI'm proud of how much I've learned about crests. Just two years ago, transmutation was a dream, and now it's almost my regular job. Well, a part of my regular job. Well, a part of my regular job when you need the help. Cuzolth and I really appreciate all the help you've given us." }
WordHunterWoW_QuestEN[86406] = { title = "[DNT] Camp Assignment", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[86408] = { title = "My Hole in the Wall", description = "Never thought when I was lookin' for security I'd get some kinda bona fide hero. I can see why rumors about you spread so quickly. You like helpin' people, don'tcha?\n\nLook I don't wanna get all sappy or nothin'. It's just... What you did for everyone... \n\n<Mama Keara shakes her head and regains her composure.>\n\nAnyways. A deal's a deal. Sign your name on the apartment log over there and you'll be an official Barrelbottom resident. I'd say you've definitely earned it.", objectives = "Inspect the Barrelbottom Apartment Log.", completion = "<With your name signed in the ledger, you gain full rights to the top floor of the Barrelbottom Apartments.>" }
WordHunterWoW_QuestEN[86409] = { title = "Stalking the Crags", description = "", objectives = "" }
WordHunterWoW_QuestEN[86410] = { title = "Slime Wranglin'", description = "", objectives = "" }
WordHunterWoW_QuestEN[86412] = { title = "Fancy Pants", description = "", objectives = "" }
WordHunterWoW_QuestEN[86414] = { title = "Magno-Scrapper 9000", description = "", objectives = "" }
WordHunterWoW_QuestEN[86417] = { title = "Ready Check", description = "We've done what we can here, {name}. Now we just have to hope it'll be enough.\n\nMaybe Gazlowe's got a plan. Maybe now we're ready to face down Gallywix. Let's formulate our next steps. I enjoy a bit of formulation from time to time.", objectives = "Check in with Grimla about what to do next.", completion = "I got a whole bunch of goblins who wanna have a word with management." }
WordHunterWoW_QuestEN[86418] = { title = "Fresh Towel?", description = "", objectives = "" }
WordHunterWoW_QuestEN[86428] = { title = "Voltstrike the Charged", description = "", objectives = "" }
WordHunterWoW_QuestEN[86429] = { title = "Phase Diving: The Bound Unbound", description = "", objectives = "" }
WordHunterWoW_QuestEN[86431] = { title = "Scrapchewer", description = "", objectives = "" }
WordHunterWoW_QuestEN[86447] = { title = "Devourer Attack: Eco-dome: Primus", description = "", objectives = "" }
WordHunterWoW_QuestEN[86448] = { title = "Piecing Things Together", description = "<Elise Starseeker should be able to piece these Bounty's Remnants back together.>", objectives = "Purchase a Delver's Bounty from Elise Starseeker in Dornogal." }
WordHunterWoW_QuestEN[86456] = { title = "An Elegy for a Silent World", description = "<The crystal you are holding vibrates faintly in your hand. The energy it emits feels like it is holding your hand, trying to reach out and never let go--like it wants you to hold it, to bring it to safety. You can hear a faint song in the back of your mind--a song of fear, confusion, and longing for life.\n\nMaybe Ve'nari would know more about it?>", objectives = "Bring the Dimmed Crystal to Ve'nari in the Oasis.", progress = "I am dealing with another crisis in my eco-domes, <name>. Make it quick or move aside.", completion = "<Ve'nari stops, as if distracted by a song.>\n\nWhere did you find this crystal? I can hear it, in my head, singing to me." }
WordHunterWoW_QuestEN[86457] = { title = "A Lullaby of Hope", description = "{name}, do you know what this is?\n\nIf I am right, this crystal is the essence of my world, K'aresh. I've spent much of my capital preserving some bit of K'aresh through the eco-dome project. But this...\n\nI do not wish to assume anything before verifying if it is true.\n\nPlace down the shard, and let's see what we can find.", objectives = "Place the Dimmed Crystal.", progress = "If this crystal is what I think it is, we have found a new hope of saving K'aresh.", completion = "I can't believe it! I...\n\n<Ve'nari's voice chokes.>\n\n<name>, what you have found is going to change the future of K'aresh.\n\nThe future of my people." }
WordHunterWoW_QuestEN[86458] = { title = "A Song for Our Future", description = "There is a site, Eco-Dome: Al'dani, which I have kept hidden. It is built on the remains of one of our most sacred places with a powerful connection to K'aresh. It is the site of our greatest triumph of the project. This is the place where we can take the Worldsoul's essence so it can survive.\n\nThis is also the eco-dome where Soul-Scribe and her Wastelanders are attacking.\n\nClear the way for me one last time, {name}. For K'aresh to survive, we need both the dome and Soul-Scribe intact.", objectives = "Defeat Soul-Scribe within Eco-Dome: Al'dani.", progress = "We must make Soul-Scribe see reason. We must prevent her oath to Salhadaar from dooming K'aresh.", completion = "What transpired here will echo for years to come. The change will not happen within a day, a week, or even months. But with hope rekindled, we will get there, and we will be united once again.\n\nYou have saved us all, champion." }
WordHunterWoW_QuestEN[86461] = { title = "Ancient Curiosity: Combat", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "Use and equip a Combat Curio to Brann Bronzebeard." }
WordHunterWoW_QuestEN[86462] = { title = "Ancient Curiosity: Utility", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "Use and equip a Utility Curio to Brann Bronzebeard." }
WordHunterWoW_QuestEN[86464] = { title = "Devourer Attack: The Atrium", description = "", objectives = "" }
WordHunterWoW_QuestEN[86465] = { title = "Devourer Attack: Tazavesh", description = "", objectives = "" }
WordHunterWoW_QuestEN[86469] = { title = "A Stromgarde Tour", description = "The very walls of Stromgarde have stories to tell, if only you have the patience to listen.", objectives = "Deal with 1 Marran Supporters in Stromgarde." }
WordHunterWoW_QuestEN[86470] = { title = "Fearin's Version", description = "I need someone to deliver these requests to people around the city. We've been shorthanded and I haven't gotten around to distributing this bunch.\n\nAs my newest deputy, this responsibility is now yours!\n\nMost of these are simple and straightforward. Requests for supplies and such for the Stromic army.\n\nJoseph is another matter. He's been inciting the populace with inflammatory rhetoric. He needs to stop or we will have to arrest him. We can't afford another riot breaking out right now.", objectives = "Deliver Brewston's requests to people in Stromgarde." }
WordHunterWoW_QuestEN[86476] = { title = "Worldsoul Memory: Early Cartel Wars", description = "", objectives = "" }
WordHunterWoW_QuestEN[86477] = { title = "Worldsoul Memory: Kaja'mite Contact", description = "", objectives = "" }
WordHunterWoW_QuestEN[86479] = { title = "LFGDungeons - 11.0 The War Within - Raid Finder - 1st", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[86480] = { title = "LFGDungeons - 11.0 The War Within - Raid Finder - Nth", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[86481] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[86482] = { title = "A Lifeline", description = "<The snapdragon barely moves as you approach. It is clearly weak and seems much smaller than it should be. \n\nPerhaps Zexel Fingersnap has something for sale that could help get it back up on its feet?>", objectives = "Talk to Zexel Fingersnap.", progress = "<The small snapdragon looks wearily at you with dull eyes.>", completion = "<The small snapdragon voraciously tears into the morsel. It seems to be energized by both the meat and the caffeinated Kaja'Cola the meat was soaked in.\n\nIt looks up at you with gratitude in its eyes. \n\nIt will remember you.>" }
WordHunterWoW_QuestEN[86483] = { title = "Snap To It", description = "<The snapdragon seems to recognize you as you approach, its ear fins wiggling with anticipation. \n\nNot only has it grown bigger overnight, but its scales have changed to a seaweed-green color similar to the Kaja'cola-braised meat you fed it.\n\nBetween it's talons lie morsels of meaty rations it has stolen from nearby invading forces. The snapdragon looks at you expectantly.\n\nPerhaps you can bring it more meaty rations by slaying the invading forces on the island.>", objectives = "Find 5 Meaty Rations from the invading forces: Pirates, Naga or Vrykul.", progress = "<The snapdragon paws the ground and then looks at you expectantly. Its eyes glitter with intelligence.>", completion = "<The snapdragon perks up as you approach and sniffs the air as if to check to see if you've brought it food. \n\nThe second it sees the rations in your hand it begins snapping it's jaws in anticipation of a tasty meal. \n\nWith a newly full belly the snapdragon runt lays down to rest but peers up at you, as if hoping you will return tomorrow.>" }
WordHunterWoW_QuestEN[86484] = { title = "Temper Like A Tempest", description = "<The snapdragon seems to recognize you as you approach, its ear fins wiggling with anticipation. \n\nNot only has it grown bigger overnight, but its scales have changed color from the meat you fed it yesterday.\n\nBetween it's talons lie the remains of a sea creature from the last Seafury Tempest. The snapdragon looks at you expectantly.\n\nPerhaps by venturing into the Seafury Tempest and slaying creatures there you can bring it more meat.>", objectives = "Speak to Suzie Boltwrench to enter the Seafury Tempest and slay creatures to obtain Storm-infused Mystery Meat.", progress = "<The snapdragon paws the ground, then looks at you expectantly. Its eyes glitter with intelligence and hunger.>", completion = "<Upon seeing the meat you have brought it, the snapdragon clicks its jaw hungrily. The second you set down the meat it tears into it veraciously finishing the meal in seconds.\n\nIt looks up at you with newfound respect in it's eyes; after all, you have slain mighty creatures to bring it this meal.>" }
WordHunterWoW_QuestEN[86485] = { title = "A Loyal Friend", description = "<The snapdragon seems to recognize you as you approach, its ear fins wiggling with anticipation.\n\nIts massive, lithe body unfurls as it stands before you as a fully grown adult. It stares you down, clacking it's massive jaw gently as if it's deciding something.\n\nIt seems to wait for you to make the first move.>", objectives = "Speak to the snapdragon.", progress = "<The snapdragon hisses and wiggles it's ear fins, looking impressed.>", completion = "<The snapdragon bows its head to you as a sign of respect. It seems to be grateful for all you have done for it.\n\nIt will now accept you as its rider.>" }
WordHunterWoW_QuestEN[86486] = { title = "Hungry, Hungry Snapdragon", description = "<The snapdragon seems to recognize you as you approach. Its ear fins wiggle with anticipation. \n\nIt is hungry again and looks at you expectantly. It seems to want meat and doesn't seem to care where it comes from.>", objectives = "Collect 8 Mystery Meat Snacks by killing creatures around the Siren Isle.", progress = "<The snapdragon stirs as you approach, its unnaturally-intelligent eyes scanning you. \n\nClearly it hopes you have brought it a meal.>", completion = "<The snapdragon barely waits for you to drop the rations before voraciously devouring them. Clearly it was hungry.\n\nOnce it finishes, it looks contented and drowsy. You realize it won't be this way for long. Perhaps you should try to feed it again tomorrow.>" }
WordHunterWoW_QuestEN[86491] = { title = "Dastardly Duos! It's on!", description = "Hello, fight fans. The world's meanest villains are teamed up and back for revenge! They have returned, this time as Dastardly Duos!\n\nMeet me in Dornogal, at the foot of Contender's Gate and sign up to face the Dastardly Duos. Beat down these bosses one more time. Relive the dream!\n\n-Vinnie Sweets", objectives = "Speak with Vinnie Sweets in Dornogal near Contender's Gate.", completion = "There you are. Now let's make some money!" }
WordHunterWoW_QuestEN[86493] = { title = "LFGDungeons - Timewalking \"Heroic\" Random - 1st", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[86494] = { title = "LFGDungeons - Timewalking \"Heroic\" Random - Nth", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[86495] = { title = "The Reshii Ribbon", description = "During the Devouring War, I witnessed the horrific results of the All-Devouring's presence. A mortal being cannot approach him at the manaforge. He is the entropy of the end, and you are just flesh.\n\nXal'atath knows rituals from across the Great Dark Beyond. With the power of the Reshii Ribbons, she was able to transform the K'areshi so they could withstand Dimensius.\n\nAlleria will not like this plan. You must convince her!", objectives = "Convince Alleria to let Xal'atath perform the ritual of transformation on you.", progress = "Every moment spent debating or arguing is a moment closer to Dimensius emerging.", completion = "She agreed?\n\nAlleria listens to you, my champion. You are indeed our savior." }
WordHunterWoW_QuestEN[86496] = { title = "An Ordered Design", description = "<Bargus holds up a tiny splinter of golden crystal.>\n\nMuch like the radiant remnants found by the Arathi within Hallowfall, the Siren Crystal appears to be effecting the surrounding geological matrix of the island.\n\nUnlike our goblin compatriots, I don't recommend harvesting the larger shards we've seen around the isle, lest we disturb the fragile caverns beneath us or offend the Arathi. \n\nBut these tiny splinters are worth investigating.\n\nBring me a sizable portion. For... experimental purposes.", objectives = "Collect 50 crystal-splintered rubble.\n\nThe crystal-splintered rubble can only be looted from creatures on the Siren Isle during the Seafury Tempest.", progress = "Have you found more splinters of the Siren Crystal? I think I may be able to create something useful with them.", completion = "<Bargus spreads the rubble onto his anvil and nods firmly.>\n\nI will begin research on this new material immediately! You have my gratitude, <name>.\n\nYou are welcome to help yourself to the newest sets of armaments I have recently forged. \n\nThey were slated for delivery to the Awakening Machine, but since they seem like the perfect size for you, you are welcome to sample my work." }
WordHunterWoW_QuestEN[86503] = { title = "Who are the Dastardly Duos?", description = "Great question! Here's how to find out: Talk to Xyggie Marou and sign up to fight the Dastardly Duos.\n\nAnd because you're new to this, let me give you a list of \"Dastardly\" tasks to do while you're in there!\n\nGood luck! Maybe I'll see you on the other side.", objectives = "Beat the Dastardly Duos while finishing Vinnie's \"Dastardly\" tasks, then speak with Vinnie Sweets.", progress = "Speak with Xyggie Marou, do my tasks, and beat those Dastardly Duos!", completion = "I saw your fight, good stuff. Here's your prize purse. Pleasure doing business.\n\nFeel free to sign up again. I'll remember to not bet against you next time." }
WordHunterWoW_QuestEN[86509] = { title = "Friend or Fiend", description = "Despite that spirited display, I'm inclined to help you. After all, what's a little violence between friends? \n\nAnd since we're friends, I'll let you in on a secret: shutting down the storm is only possible from inside the Nexus-Points. Of course you can't just walk in--you need the Mantle of Predation.\n\n<Decimus seems to savor the words.>\n\nDo I have your attention? Let's shake the dust off and discuss this somewhere... civilized. Meet me at my estate.", objectives = "Travel to the Howling Ridge.", completion = "Guests are a rare treat for a domanaar. Especially ones that come of their own accord." }
WordHunterWoW_QuestEN[86510] = { title = "Domus Penumbra", description = "It seems we all wish to stop the Voidstorm. Common ground--a rare thing here. I'll even tell you how to do it, and all I ask in return is for you to let me enjoy the show.\n\nBut you must be tired. Show yourself around, and help yourself to the amenities. Then we will continue our discussion.\n\nDon't take too long. There is much to see, and the storm rages on.", objectives = "Establish your base at the Howling Ridge.", completion = "Comfortable? So nice to see someone appreciate my hospitality.\n\nNow I suppose we must discuss business before your glowing friend has another tantrum." }
WordHunterWoW_QuestEN[86511] = { title = "Edge of the Abyss", description = "I don't trust Decimus any more than the rest of the beasts here. I do trust that they only serve themself. Seems having Xal'atath as a master isn't to their taste. We can turn one foe against another. Even Lothraxion would agree if he weren't so stubborn.\n\nIf this Mantle of Predation will let us stop the storm, then it's our best shot. A troop of ren'dorei have been scouting the Obscurion Citadel. We'll meet with them and see what they've learned.", objectives = "Meet the ren'dorei scouts near the Obscurion Citadel.", progress = "I've avoided this place until now. The howls and the stench are carried on the wind like a warning.", completion = "I don't like dividing our forces. Not when this much is at stake.\n\nLet's not rush in like Lothraxion. See what Decimus knows. I'd rather not hunt a domanaar unprepared." }
WordHunterWoW_QuestEN[86512] = { title = "The Harvest", description = "Two sigils--you'll need both to open Terminas's vault and claim the Mantle.\n\nThe first belongs to Torentia, petty ruler of this sad trench. Too ambitious for Terminas to bring her into his inner circle, too cowardly to strike out on her own. So here she cowers behind an unbreakable shield of Void.\n\nShe's terrified of losing her already meager holdings. What a pity. Slaughter your way through the trench. The potential emergence of a new apex predator is something she won't ignore.", objectives = "Slay foes to attract Torentia's attention.", progress = "Do you feel the hunger of this place? No wonder the Void came here.", completion = "Do you sense it? Every beast here either fears you or wants to kill you. Even their mistress cannot ignore you now." }
WordHunterWoW_QuestEN[86513] = { title = "Face the Tide", description = "I expected an army, but this is chaos--beasts pouring from the Void, gorging themselves, taking captives for sport.\n\nOur mission is to claim the Mantle, but we can't ignore this. Sooner or later, these forces will be loosed against Silvermoon. Any blows we strike now will save lives down there, {name}.\n\nStarve their forces, stem the flow of beasts from the Void, and free every captive they've abducted.", objectives = "Disrupt Obscurion Citadel forces.", progress = "Even if we fail--Light forfend--at least we'll have struck a blow.", completion = "This is what my mother has battled on her own for all these years? I won't let her shoulder that burden alone anymore." }
WordHunterWoW_QuestEN[86514] = { title = "Lady of the Pit", description = "For all their power, these domanaar still behave like beasts. That's good for us. Wolves try to avoid each other, but if one threatens another's territory, they'll fight to the death. \n\nBy now, I think you've more than proven that you're a threat. Torentia can't back down if you challenge her--it would go against her nature.\n\nSo take the fight to her, slay her, and claim her sigil.", objectives = "Challenge Torentia and claim her sigil to access the vault.", progress = "Have you claimed Torentia's sigil?", completion = "I've never known Lothraxion to be careless like this. Throwing lives away, charging in blind--doesn't he know he's not leading an army here? \n\nAt least you've done your part. Let's try to salvage the mission." }
WordHunterWoW_QuestEN[86515] = { title = "Hollow Hunger", description = "Alleria's judgement is clouded. She's spent too much time steeped in Void. I've prosecuted campaigns across the cosmos. Casualties are inevitable. I could not command if the loss of every soldier broke my will.\n\nWe have the information we need: the location of the sigil bearer. The fiends whisper of a domanaar named Severum. Slay him and take his sigil, then we can be rid of this place.", objectives = "Slay Severum and claim his sigil.", progress = "Would that we could put every voidspawn to the sword.", completion = "Well done. Soon we'll have the Mantle of Predation and no longer need Decimus.\n\nDo not mistake their usefulness for allegiance as Alleria has." }
WordHunterWoW_QuestEN[86516] = { title = "All Become Prey", description = "Lothraxion's acting like we have an army, but a single ultradon will tear through us if we're caught off guard. We need to be smarter.\n\nI've watched the beasts of this world: studied them, tracked them, killed them. They prey on weakness, and cull their own kind at the first sign of frailty. \n\nHarvest carrion essence from the carcasses around the citadel. Use it to mark ultradons. Other beasts will pounce, thinking they're wounded or dying. Let them tear each other apart, then clean up what's left.", objectives = "Slay Slavering Ultradons by marking them with Carrion Essence.", progress = "These creatures operate on base instinct. We can exploit that.", completion = "Good hunting. With the ultradons dead, we may just be able to get out of here alive." }
WordHunterWoW_QuestEN[86517] = { title = "Vanished in the Void", description = "\"Acceptable losses.\" I hope I never find it that easy to dismiss the deaths of friends and comrades. What use is the Light if it leaves us as callous as our enemies?\n\nSideras was nearly killed. Luckily, he escaped through a rift. Riftblade Maella led the others in a fighting retreat. Find her. Hopefully they stuck together.\n\nI can't leave Sideras--not until he's stable.", objectives = "Find the missing void elves.", progress = "Lothraxion should know better than this.", completion = "This isn't right. Hieron didn't come here to die. The Light should protect people, not lead them to their deaths.\n\n<Arator seems lost in thought.>\n\nThank you. I'll make sure to give his journal to the others." }
WordHunterWoW_QuestEN[86518] = { title = "The Mantle of Predation", description = "Let's move quickly. We need to steal the Mantle before Terminas returns and before Lothraxion does something rash. \n\nI understand this place grates on him, but he should know to trust my instincts. I thought we'd fought together long enough to earn that.\n\nLet's end this. Ready when you are.", objectives = "Steal the Mantle of Predation.", completion = "Are you alright? I must have missed something. Why did Decimus bother helping us at all? They could have betrayed us at any time. It doesn't make any sense..." }
WordHunterWoW_QuestEN[86519] = { title = "Abyssus, Abyssum", description = "I don't see Decimus. For all their glee at handing us over, I'd expect they'd want to watch the fight. What could be more important to a domanaar than enjoying a battle?\n\n<Alleria nocks another arrow.>\n\nAnswers can wait. Right now we need to survive.", objectives = "Conquer Terminas's arena.", completion = "Lothraxion's going to tear the Nexus-Points apart, even if it costs us Silvermoon!" }
WordHunterWoW_QuestEN[86520] = { title = "Hunt the Light", description = "There's no time. Lothraxion already has the lead. \n\nGet to Nexus-Point Xenas, {name}. We'll meet you there.", objectives = "Meet Alleria Windrunner at Nexus-Point Xenas.", completion = "He's already here. We have to stop him." }
WordHunterWoW_QuestEN[86521] = { title = "Nexus-Point Xenas: Eclipse", description = "If he destroys the Nexus-Point, everyone we're fighting for could perish. I'll try to talk him down, but if I can't, if I have to...\n\n<Alleria's face clouds.>\n\nNo hesitation. We end this, one way or another.", objectives = "Enter Nexus-Point Xenas and stop Lothraxion.", completion = "It's over. We can breathe, if only for a moment." }
WordHunterWoW_QuestEN[86522] = { title = "Daylight is Breaking", description = "Turalyon is busying himself with the troops. We'll need to let him know what they'll face here, tell him about Lothraxion...\n\n<Alleria shakes her head.>\n\nThank you, {name}. Even when my thoughts feel clouded, you never seem to waver. Go, give Lor'themar my report. Arator and I will brief Turalyon.", objectives = "Report to Lor'themar Theron in the Sanctum of Light in Silvermoon City.", completion = "This was an impossible mission. We won't forget the sacrifices that bought us a fighting chance.\n\nStill, I know not every victory feels worthy of celebration. When war forces us to choose between friendship and duty, there are many who would be unable to act.\n\nWe will not squander the opportunity you've given us. Now, our counter offensive begins." }
WordHunterWoW_QuestEN[86528] = { title = "A Cracked Holokey", description = "<A unique-looking ethereal device rests upon the cold ground. It bears a crack down the middle from damage in a scuffle.\n\nPerhaps Alleria will know what it is.>", objectives = "Bring the Cracked Holokey to Alleria deeper in the Ethereum Refinery.", completion = "I've seen one of these before. Ethereals use them to encrypt communications.\n\nExcellent find, <name>." }
WordHunterWoW_QuestEN[86530] = { title = "First, The Shells", description = "Ages ago, on a dismal world of swamp, I led the Army of the Light to a demon-infested manaforge obscured by vines and fog. My soldiers left that world in a haze of flame and smoke, the scent of burning mana and victory in the air. We will do now as we did then.\n\nWe'll begin by collecting the empty canisters they use to hold and transport fuel. The ethereals, and especially their automatons, will have them.", objectives = "Collect 5 Empty Manacells from mechs and ethereals at the Ethereum Refinery.", progress = "Just as before.", completion = "Good. The same make I remember.\n\nNow, the catalyst." }
WordHunterWoW_QuestEN[86531] = { title = "Work Disruption", description = "The Shadowguard may once have defied Xal'atath, but they're part of her army now. Whatever they're doing with the energies gathered here must be stopped.\n\nPut down their soldiers, harvesters, and machines. I'll do the same, and meet you deeper within.", objectives = "Slay Shadowguard and disrupt the Manaforge at the Ethereum Refinery.", completion = "They will try to rebuild, but we won't give them the chance." }
WordHunterWoW_QuestEN[86535] = { title = "Test Run", description = "Hey, you lookin' to make a few coins?\n\nWe made a deal with the earthen to build a teleporter up in Dornogal. We get all the tourism traffic we want, and they get their pick of the finest cracked, chipped, or otherwise unsellable gemstones Undermine's jewelers can offer.\n\nI just got this end of things workin', but I haven't tested it out yet. You wanna try? If you come out the other side, my coworker Kenzi will compensate ya.\n\nWe'll say this constitutes a verbal waiver, yeah?", objectives = "Use the teleporter to travel from Undermine to Dornogal.", progress = "Look at this teleporter. Ain't she gorgeous?", completion = "Woah! I thought Rustol was gonna send through a gerbil or a can of peaches or somethin' to test out the new teleporter, not an actual person.\n\nBut you're only sizzlin' a little bit! Fantastic.\n\nTell ya what. For doin' us a solid and havin' such little regard for your own personal safety, we'll let ya use the teleporters free of charge whenever ya want." }
WordHunterWoW_QuestEN[86536] = { title = "Reliable Enemies", description = "The ren'dorei scouts report a familiar enemy upon this world: ethereals. Wretched scavengers and bandits that plague every corner of the Great Dark Beyond. The Shadowguard are the worst of them. We'll handle them.\n\nThis... thing we've taken prisoner must know what they're doing here, and much else. Press the Void's secrets from it. See that it is convinced to share what it knows, or I will employ my own methods.", objectives = "Interrogate Decimus.", progress = "Lothraxion has a plan. I trust him.", completion = "If Xal'atath was mortal, then she is all the more monstrous for all that she has done. For becoming what she is now.\n\nOur long battle comes to an end on this world. I swear it." }
WordHunterWoW_QuestEN[86537] = { title = "Network Insecurity", description = "Judging by the design and the strength of this holokey's energy, it must be used to encrypt important communications.\n\nLet us try this lead. See if it's compatible with any of the consoles you find around the refinery. Given the damage it's taken, we'll have to piece together whatever scraps of information we can.", objectives = "Use the Holokey on consoles around the Ethereum Refinery.", progress = "What have you found?", completion = "Xal'atath.\n\nLet us see this final message." }
WordHunterWoW_QuestEN[86538] = { title = "Second, The Fuel", description = "Ethereals seek corners of the cosmos to drain of potent nether. Arcane, Void, fel--to them, it matters only the yield. And we have a rich vein to work with.\n\nNow, slay those who possess that energy: wild arcane elementals from their pipes, or their ethereal harvesters flush with energy. We have need of it.", objectives = "Collect 50 Arcane Remnants in the Ethereum Refinery.", progress = "Go. Collect the catalyst.", completion = "Potent. I can feel the energy--radiant. Glorious." }
WordHunterWoW_QuestEN[86539] = { title = "A Naaru!", description = "I refuse to let another naaru fall to darkness.\n\nBefore our departure, the scouts reported they had found a Nexus-Point connected to this forge. If the Void's forces possess a naaru, it might be where they're keeping it.\n\nI will prepare the manacells as we conduct the search. Come.", objectives = "Find Lothraxion at the overlook to Nexus-Point Mid'Ar.", completion = "A naaru, imprisoned. The Light shall give these monsters no mercy." }
WordHunterWoW_QuestEN[86540] = { title = "Third, Blow It Up", description = "The manacells have been prepared. Set them near the pylon and its supporting machinery. When it's done, I will command Alleria to ignite them from afar.\n\nBut we cannot proceed until the naaru has been brought to safety. Go now and I will make certain of her freedom.", objectives = "Place 5 Overcharged Manacells at Nexus-Point Mid'Ar.", progress = "What are you doing here? Place the manacells, now!", completion = "This is taking too long! Every wasted moment brings us closer to ruin!" }
WordHunterWoW_QuestEN[86541] = { title = "Just In Case...", description = "Perhaps Lothraxion will be able to bring that shield down on his own. Or perhaps he is a pompous blowhard.\n\nThe Devouring Host offers its trusted soldiers fragments of a relic that can override any ethereal device, including that shield. You'll need to carve quite a swath through their forces to recover enough shards.\n\nBut what do I know? I am merely unworthy voidspawn.", objectives = "Collect 8 Fragmented Keystones from Devouring Host soldiers at Nexus-Point Mid'Ar.", progress = "<Decimus glances sideways at you.>", completion = "A mortal, receptive to outside ideas. Truly exemplary. No need to thank me.\n\nThough, perhaps you'd want to free me of this bondage? I'm feeling a bit chafed by the Light about now.\n\nNo? Oh well." }
WordHunterWoW_QuestEN[86542] = { title = "Flicker in the Dark", description = "We're dawdling! There's no time to waste!\n\nGet that shield down, now! T'era's anguish tears at my soul!", objectives = "Free and rescue T'era.", completion = "Everything I could muster. It was simply... devoured." }
WordHunterWoW_QuestEN[86543] = { title = "Magisters' Terrace: Homecoming", description = "We know there's land inside the Voidstorm, through its massive portal. If we can reach it, we can take the fight to Xal'atath.\n\nI have found the key. It is a relic known as the Cynosure of Twilight. For ages, it has mystified us by revealing unreachable pathways to infinite unknowns. \n\nMy research tells me I can use it to open a path to the storm. \n\nThere's just one problem: it's in Magisters' Terrace. And I'm not exactly... in their good graces, at the moment.", objectives = "Meet Magister Umbric on the Isle of Quel'Danas, then complete the Magisters' Terrace dungeon.", completion = "That could have gone better. \n\nThen again, Rommath hasn't killed me, yet. It could have gone worse." }
WordHunterWoW_QuestEN[86544] = { title = "Post-Mortem", description = "We all bear a heavy burden in this place. I feel myself slipping towards hopelessness. But we haven't failed until we refuse to stand back up. I know my mother will collect herself. But the others need to know this fight isn't over. \n\nSpeak with Hieron. He and the other scouts should have information. We can start there.", objectives = "Check in with the inhabitants of Locus Point.", progress = "Mother... Hang in there.", completion = "What was that...?" }
WordHunterWoW_QuestEN[86545] = { title = "The Light's Brand", description = "No! {name}, we have to stop them! Lothraxion's boiling temper risks everything! That he chooses now of all times, when my mother is out of commission...\n\nThere's no time. We have to go!", objectives = "Intervene in the fight between Lothraxion and Decimus.", progress = "I should have realized earlier... Join me, <name>. Let us reveal the truth.", completion = "Decimus is a far more capable domanaar than they've been letting on." }
WordHunterWoW_QuestEN[86549] = { title = "No Fear of the Dark", description = "Against all odds, we made it. \n\nI can open a way into the storm, but it will be a tenuous connection. We can only get a small team through the portal. \n\nWe have no idea what awaits us on the other side. We must be prepared. \n\nI can use the Cynosure to bind us to Magisters' Terrace. If we need a quick escape, I can bring us back there. \n\nCome--help me calibrate this spell.", objectives = "Help Magister Umbric apply the anchor spell and open a portal to Voidstorm.", completion = "This... this power! I have never felt the Void like this. \n\nAll-consuming." }
WordHunterWoW_QuestEN[86555] = { title = "Undermine Benefactor", description = "", objectives = "Thanks for helping get Undermine back on track. Here's somethin' for your trouble." }
WordHunterWoW_QuestEN[86556] = { title = "A Shattered Journey Through Time", description = "The Destroyer's star shines upon the land with its piercing light as even the spirits retreat to the shadows. This star is unlike any other in the skies, laying bare the weaknesses of even the boldest heroes. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "Complete 5 Timewalking dungeons.", completion = "Ah, <name>, you have returned. An otherworldly air hangs heavy about you." }
WordHunterWoW_QuestEN[86557] = { title = "A Matter of Strife and Death", description = "Ha! A distant realm, crawling with vicious evil monsters? Just like old times.\n\nAlleria, Turalyon, and I faced a thousand years of war with demons in the far-flung realms. It is as simple a solution now as it was then. \n\nKill or be killed.", objectives = "Kill 12 monsters in The Ingress.", progress = "I will not deny, I still thrive in the rush of battle. So long as it is of righteous cause.", completion = "Vile beasts. Did you sense it?\n\nThey all reek of Void." }
WordHunterWoW_QuestEN[86558] = { title = "Save a Piece of Mind", description = "The Void here. It is like nothing else. Surely you can feel it, too? The overwhelming power...\n\nWe must do something to stabilize the area. I'm barely able to keep our escape route from imploding, and the rest of our scouts... I can only hope they can hold it together.\n\nThe ren'dorei know what to do. They will place Shadestar Loci to protect this area, but will need your help activating them.", objectives = "Activate 3 Shadestar Loci around The Ingress.", progress = "Be careful, <class>. Treachery threatens us from all sides.", completion = "The void elves risk corruption, and yet are most suited to understanding the world around us. We need their expertise, but cannot trust them.\n\nIt irks me, but I have already sent for more scouts." }
WordHunterWoW_QuestEN[86559] = { title = "The Far, Far Frontier", description = "We have secured this location. Some void elves can make this into a proper camp.\n\nThere must be some weakness we can exploit to stop the storm. We must bring my army here to mete out justice to Xal'atath's armies!\n\nJoin me and young Arator. Let us see what we can gather from this place across the horizon.", objectives = "Survey Voidstorm with Lothraxion and Arator.", completion = "The rest of the void elves have been dispersed to set up camps or scout.\n\nI am... conflicted over Alleria's presence. Her skills and experience are unspeakably valuable, and yet...\n\nThe Void in her is so strong... I worry. Keep an eye on her.\n\nThe Void can NEVER be trusted." }
WordHunterWoW_QuestEN[86560] = { title = "A Shrouded Journey Through Time", description = "The shrouded star flickers upon the land with its intermittent light ushering in an eerie mist upon the land. This star and the mists bring deep shadows to the land hiding its secrets and dangers. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "Complete 5 Timewalking dungeons.", progress = "I foresee that you will follow the shrouded star, and walk the paths it reveals.", completion = "Ah, <name>, you have returned. An misty air hangs heavy about you." }
WordHunterWoW_QuestEN[86561] = { title = "A Strange, Different World", description = "I don't know the purpose of these towers, only that they are called Nexus-Points and they thrum with Void power. We must get more information. \n\nThe domanaar use some kind of Void-infused metal on the beasts here to add them to armies of the Devouring Host. They call it shadowgrafting.\n\nIt empowers them, but also influences their minds.\n\n<Alleria smiles wryly.> \n\nWhat power doesn't? \n\nI have a plan for it. With you here, I can finally act on it.", objectives = "Collect 12 Shadowgraft Fragments in Nexus-Point Antius.", progress = "The metal on these creatures... it seems particularly conductive to magical energies. Interesting.", completion = "<Lothraxion scowls.>\n\nDespicable stuff. Alleria has explained her plan to me, but I'm not sure I agree." }
WordHunterWoW_QuestEN[86562] = { title = "Dancing with Death", description = "We may be a small strike team, but we are strong. We have you, after all. \n\nThere is no need to move with complete stealth. We must cut a path to the domanaar here. \n\nTake down the strongest enemies you can find. We will join you in the fray.", objectives = "Slay Voidgrasper, Vathan the Rebel, and Scytheryp the Slicer in Nexus-Point Antius.", completion = "There seems to be creatures here both bestial and magical. \n\nThe Void is drawn to violence. I have seen countless worlds drown in it. \n\nCould the savagery of the beasts here have brought the Void in naturally?" }
WordHunterWoW_QuestEN[86563] = { title = "A Savage Journey Through Time", description = "The brutal star shines upon the land, threatening to trample underfoot all who stand in its path. This star is many things: primal, fierce, and noble. While its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "Complete 5 Timewalking dungeons.", progress = "I foresee that you will follow the brutal star and walk the paths it reveals.", completion = "Ah, <name>, you have returned. An otherworldly air hangs heavy about you." }
WordHunterWoW_QuestEN[86564] = { title = "A Fel Journey Through Time", description = "A corrupting star shines upon the land, threatening all with burning oblivion. The star betrays those who seek the light, its red glow obscuring rather than revealing.\n\nWhile its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "Complete 5 Timewalking dungeons.", progress = "I foresee that you will follow the corrupting red star and walk the paths it reveals.", completion = "Ah, <name>, you have returned. An fel air hangs heavy about you." }
WordHunterWoW_QuestEN[86565] = { title = "No Prayer for the Wicked", description = "Alleria has a plan to use this shadowgrafting material to capture that domanaar for information. \n\nBut what good is information given by evil? I've fought countless demons and every one of them was a liar.\n\n<Lothraxion scowls.> \n\nLet us follow her plan, for now. Do what she asks with this metal, then slay the domanaar's pet beast. \n\nOnce we speak with this vile creature, I will decide how long it lives.", objectives = "Help modify the Shadowgraft Fragments, slay Sinewshredder in Nexus-Point Antius, and capture the leading domanaar.", completion = "You've done good work, <name>." }
WordHunterWoW_QuestEN[86575] = { title = "Rocket Roll", description = "That scrap was just what I needed. An' now without those bloodfeasters givin' me the heebie jeebies, I can get these bots officially rolled out.\n\nWhile I finish up here, why don't you go tell Benny the good news?\n\nI'm sure he'll wanna deploy 'em right away!", objectives = "Return to Benny Gooserocket outside the cave in the Ringing Deeps.", completion = "You helped Trixxie get those bots up an' runnin'?\n\nOutta sight, <name>!\n\nI don't gotta worry about staffing no more." }
WordHunterWoW_QuestEN[86584] = { title = "Overwhelm Them with Mandatory Time Off", description = "", objectives = "" }
WordHunterWoW_QuestEN[86587] = { title = "To Maldraxxus", description = "Rays once soared through the skies of K'aresh. While their void-touched descendants are in the skies outside the Oasis, we have no surviving specimens that have not been void-touched.\n\nHowever, I know of a location where we can procure a similar creature that should inhabit the same part of the ecosystem: Maldraxxus in the Shadowlands. Take my portal, and find the creatures for me.", objectives = "Travel to Maldraxxus in the Shadowlands to get some rays for Ve'nari.", progress = "Greetings.", completion = "Ve'nari sent you? How marvelous! I was just looking for some assistance." }
WordHunterWoW_QuestEN[86588] = { title = "Ritualistic Murder", description = "The local ritualists are causing problems for the necrorays. Specifically, plague problems.\n\nIf you kill them, it should lessen the issues for the necrorays.", objectives = "Slay 13 Morbid Ritualists.", completion = "What a good apprentice you are.\n\nVery good at following instructions!" }
WordHunterWoW_QuestEN[86589] = { title = "A Plague a Day Keeps the Doctor Away", description = "The ritualists have been testing a new plague out on our poor necrorays. This is abominable... That's my job!\n\nBring me some samples of deceased rays and I should be able to concoct a cure for the ones that haven't perished.", objectives = "Collect 6 Plague Samples from dead Pestilential Necrorays.", progress = "Do you have those samples for me?", completion = "Bah! There is no mastery in this. I've seen oozes spew out better plagues than this! Of course, I made those oozes." }
WordHunterWoW_QuestEN[86590] = { title = "I Don't Even Work Here", description = "It's good you are here, apprentice! I came to gather the essences from the local rancor. They are wonderful for adding just that little extra spice to a plague.\n\nBut now that you are here, I can have you gather them instead! What an excellent learning opportunity for you!", objectives = "Gather 15 Rancor Essences.", progress = "Well? Have you gathered the essences?", completion = "What an excellent apprentice you are!" }
WordHunterWoW_QuestEN[86591] = { title = "A Poor Imitation", description = "This is Vorax's work. He was once my apprentice, just like you!\n\nHe's trying to replicate my work? Flattering, but sloppy. I'll work on a solution for you, apprentice, while you work on a solution for him.", objectives = "Slay Grand Ritualist Vorax.", progress = "Is the deed done?", completion = "Oh bother. I should have asked you to get his remains. I could have used them." }
WordHunterWoW_QuestEN[86592] = { title = "Get Your Jabs", description = "If these rays are to travel, we should inoculate them first.\n\nWhat a good opportunity for you to learn about administering anti-plague, apprentice! It's not something that happens here very often.", objectives = "Inoculate 5 Calmed Necrorays.", progress = "Have you jabbed the necrorays?", completion = "I'm glad you were here, apprentice. I find wiping out all the plague in a creature quite unnerving. Feels very unhealthy." }
WordHunterWoW_QuestEN[86593] = { title = "To the Oasis", description = "I suppose you will be heading back now?\n\nIt has been a true joy to work with you, apprentice. I hope we will see each other soon. I'll have some new experiments for you to help me out with. Please do take care of the necrorays! I hope they enjoy their new home.", objectives = "Travel to the Oasis on K'aresh.", progress = "Well?", completion = "Well done. I have transferred the necrorays to the Atrium as per our quarantine procedures." }
WordHunterWoW_QuestEN[86594] = { title = "A Cultured Palette", description = "We're trying to figure out what these rays eat. \n\nI've gathered some options. Can ye put them out? I'll watch for responses.", objectives = "Place 3 Food Items.", progress = "Feeding time. Get to it!", completion = "Seems like they'll eat just about anything. Omnivores--that's a handy thing to have." }
WordHunterWoW_QuestEN[86595] = { title = "Custodial Duties", description = "Seems like these rays slough off some gunk as they move. It's congealin' and makin' a mess!\n\nVe'nari sent over this vacuum device to help out. Can you clean things up while yer out and about?", objectives = "Clean 18 Congealed Lumps in the Atrium.", completion = "That ooze is tough. Thanks for takin' care of it!" }
WordHunterWoW_QuestEN[86601] = { title = "Triple Twenty", description = "Tag the necrorays with these darts. It'll monitor their location and health. It also injects a pain killer so the necrorays don't even notice it.\n\nThese brokers have some incredible inventions!", objectives = "Tag 5 Curious Necrorays.", completion = "Good work tagging those necrorays. We'll be able tae keep a better eye on them this way." }
WordHunterWoW_QuestEN[86602] = { title = "Medical Checkup", description = "You said your friend de-plagued those necrorays, but we need to see if the other animals are picking up anything else from them.\n\nCan ye go and collect some samples so we can check for issues?", objectives = "Collect samples from animals in Eco-Dome: Primus.", progress = "Did ye get them all?", completion = "Hmm, these do look healthy.\n\nThat's a bit unexpected, but good!" }
WordHunterWoW_QuestEN[86603] = { title = "Ray-ket Ball", description = "It seems one of the necrorays you brought back was pregnant, so I have been dealing with a newborn all day. Thank you. \n\nPerhaps you would not mind testing out its reflexes for me?", objectives = "Catch a ball 10 times while playing with your Necroray Pup.", progress = "Have you finished playin--er, testing the pup's reflexes yet?", completion = "That data will do quite nicely, thank you." }
WordHunterWoW_QuestEN[86604] = { title = "Dubious Intent", description = "The ooze that Hemet had you collect may be of use to us. \n\nGo and collect the ooze directly from the necrorays. You can use this tranquilizer dart to bring them within range for collection.", objectives = "Collect 7 Necroray Gunk.", progress = "Have you gathered the ooze?", completion = "This should do quite nicely for several different projects around the Oasis. You have our thanks." }
WordHunterWoW_QuestEN[86605] = { title = "Booster Shots", description = "After some analysis of the samples you brought back, it appears the necrorays are suffering from a vitamin deficiency. \n\nVe'nari contacted Marileth, who prepared something... and then re-prepared it after she requested he remove the plague from it.\n\nPlease gather the necrorays so we can test the initial batches.", objectives = "Lasso 6 Tranquil Necrorays and bring them to the Hitching Post by Om'talad.", progress = "Have you gathered the necrorays?", completion = "Excellent work! We will administer the concoction and monitor for issues." }
WordHunterWoW_QuestEN[86606] = { title = "The Golden Ooze", description = "Our custodians have yet to do their daily cleanup of the necrorays' discharge. I have many buyers in Tazavesh lined up for this material. They need it urgently, so its collection falls to you.\n\nTake the vacuum device. Compensation will be provided.", objectives = "Clean 25 Congealed Lumps in the Oasis.", progress = "Have you succeeded at your task?", completion = "The Oasis will benefit greatly from your efforts. My thanks." }
WordHunterWoW_QuestEN[86607] = { title = "The Freedom of Ray-cing", description = "Those necrorays responded really well to those treatments you gave 'em! So well in fact that one of 'em is needin' to burn off some energy.\n\nWould ye be able to wear it out?", objectives = "Challenge the Zooming Necroray to a race and reach the finish line.", progress = "Have ye worn the thing out yet?", completion = "That was fast, <name>! Faster than I go, these days. I'll leave the speedin' along to you." }
WordHunterWoW_QuestEN[86609] = { title = "Void Breach", description = "", objectives = "" }
WordHunterWoW_QuestEN[86610] = { title = "Nor Void of Night", description = "", objectives = "" }
WordHunterWoW_QuestEN[86618] = { title = "License Not Required", description = "Alright. Before you go out and run somebody over let's make sure you know how to do it properly.\n\nWe'll introduce you to the car, the D.R.I.V.E. service we offer, and how to drive it in style.", objectives = "Learn how to drive the G-99 Breakneck.", progress = "Just put your foot on the pedal and the rest will come naturally.", completion = "Great job out there! Now these vehicles don't come with insurance so if you get into any trouble you're gonna have to solve it yourself." }
WordHunterWoW_QuestEN[86619] = { title = "Theater Troupe", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[86621] = { title = "The Wayward Magister", description = "Magister Umbric--he's second only to Mother in mastering the Void. If anyone can help us with that storm in the sky, he's the one who can make it happen... if he can forgive the others for not listening to him in the first place. \n\nAt least Lor'themar saw reason. There's no way we can take the fight to Xal'atath without Umbric.\n\nThe forces keeping the Voidstorm at bay will only hold out so long. Let's make haste.", objectives = "Accompany Arator to meet with Magister Umbric in Tranquillien.", progress = "What's that you have there?", completion = "<Umbric looks stricken.>\n\nThat is not the news I was expecting. No!" }
WordHunterWoW_QuestEN[86622] = { title = "Chance Meeting", description = "I've heard some odd rumors myself. Strange happenings to the south--but also to the east and west, and the north. Tranquillien is surrounded by enemies, it seems.\n\nSince you are so dead-set on your investigation, would you look into something for me?\n\nThere is an important report I need from one of my scouts. Check in with them, while I check over the rest of town.", objectives = "Meet with Lord Antenorian's scout near Tranquillien.", progress = "Let's get to the bottom of this.", completion = "Blast--it appears that cult has ears everywhere!" }
WordHunterWoW_QuestEN[86623] = { title = "Appeal to the Void", description = "Kasiea... whatever you've found, you've perished for it.\n\nI won't let her work be in vain. \n\nThere's something to be found here, {name}. There are a few locations listed. Let's travel to them and try some of these theorems. The formulae may be incomplete, but perhaps we can discover what she was looking for. \n\nIt had to have been important.", objectives = "Assist Umbric with testing Void theorems outside of Tranquillien.", completion = "I don't understand. What was she doing with all this information?" }
WordHunterWoW_QuestEN[86624] = { title = "Rational Explanation", description = "Something just doesn't feel right about all of this. Umbric can look into the notebook, but I suspect there's something more going on here. \n\nIt couldn't hurt to ask around Tranquillien and see if anyone's heard anything odd. I'll take the north side of town, and you take the south.\n\nAnd... use your discretion, my friend. We should avoid alarming anyone for now.", objectives = "Question the townsfolk of Tranquillien and take note of any clues.", progress = "How goes your investigation?", completion = "There's far more to Tranquillien than meets the eye, it seems." }
WordHunterWoW_QuestEN[86625] = { title = "The Clue in the Inn", description = "Call me paranoid, you'd be correct, but I have been chased out of enough towns that I have a system.\n\nI establish a safehouse. Somewhere easily defensible, with enough materials that I can finish any delicate tasks and prepare for departure. That is the situation we find ourselves in-- we will retreat to the top floor of the inn and assess our options from there.\n\nI had shared the location with Caliea, when she was still studying with me... hopefully it serves us better than it did her.", objectives = "Retreat to Umbric's safehouse on the top floor of the inn.Call me paranoid, you'd be correct, but I have been chased out of enough towns that I have a system.\n\nI establish a safehouse. Somewhere easily defensible, with enough materials that I can finish any delicate tasks and prepare for departure. That is the situation we find ourselves in-- we will retreat to the top floor of the inn and assess our options from there.\n\nI had shared the location with Caliea, when she was still studying with me... hopefully it serves us better than it did her.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[86626] = { title = "The Ransacked Lab", description = "My notes, my research... I never should have left it alone.\n\nI was just beginning to understand the Voidstorm! Everything I'd learned, torn from my hands by cultists... Were they watching the entire time? Waiting for me to turn my back?\n\nI cannot let this stop me. They can't have destroyed everything. Perhaps there's enough here to salvage.", objectives = "Scour Umbric's ransacked lab for any salvageable research.", completion = "The Twilight's Blade--Antenorian, what have you done!" }
WordHunterWoW_QuestEN[86632] = { title = "The Battle for Tranquillien", description = "The Twilight's Blade? Attacking in broad daylight now that their cover's blown... we'll prove what a mistake that was.\n\nSlay the traitors and the creatures they've summoned. Destroy their effigies and their supplies. \n\nMake this retreat costly, {name}.", objectives = "Free Tranquillien from the grip of the Twilight's Blade.", progress = "Let's hope there's enough left here to rebuild.", completion = "I fear this is far from over..." }
WordHunterWoW_QuestEN[86633] = { title = "Comprehend the Void", description = "Kasiea's notes may be lost forever, but we must try and improvise. I have one final ritual to try.\n\nIf this doesn't work, then the answers lay in Deatholme, the Twilight's Blade's heart. But first...", objectives = "Meet Umbric at the ritual site in Windrunner Village. There, collect 4 Void Shards and return them to the Void nexus.", progress = "I can't hold this indefinitely--a little speed would be appreciated!", completion = "No! No... I was so close.\n\n<Umbric collects himself--a paradigm of focus.>\n\nDeatholme it is, then. The base of the Twilight's Blade." }
WordHunterWoW_QuestEN[86634] = { title = "The Past Keeps Watch", description = "I don't trust the quiet here. Let's shore up the defenses. Did you see those slumped-over arcane golems around the village?\n\nThey may not look like much now, but a quick tune up will have them on their feet soon enough. They're good for standing guard, and also for ferreting out any hidden snakes in the weeds.\n\nLet's get to work. The sooner the golems are running, the better I'll feel about this town's safety.", objectives = "Activate 6 Decrepit Ranger Constructs on the borders of Windrunner Village.", progress = "It's odd being here. This place is... well, I suppose it's technically my namesake.", completion = "The Twilight's Blade were already skulking around the perimeter... We were right to come here quickly." }
WordHunterWoW_QuestEN[86635] = { title = "To Deatholme", description = "That coward Antenorian has doomed us all. I had hoped it wouldn't come to this, but...\n\nWe need the rest of Kasiea's research--the missing pages that were stolen from her corpse. But the cult has retreated south, to the ruins of Deatholme.\n\nFitting that such traitors would sequester themselves in such a vile place. But we must root them out.", objectives = "Meet with Magister Umbric in the Ruins of Deatholme.", progress = "Watch your back. The ruins of Deatholme are still dangerous.", completion = "I am loath to find myself here again... but it is the only way." }
WordHunterWoW_QuestEN[86636] = { title = "Void Walk With Me", description = "I did not expect this place to be so heavily guarded. This is far more complicated than one charismatic leader and a group of wayward pilgrims. Still... if we take out Antenorian, it should weaken them considerably. A cult is nothing without its leader.\n\nValeera tracked the governor to that cavern. He's gone in. We'll make sure he never comes out.", objectives = "Complete the Deatholme Delve.", progress = "Let's be done with this. The Twilight's Blade must fall.", completion = "Kasiea's notes! At long last! I must go!" }
WordHunterWoW_QuestEN[86637] = { title = "Anything but Reprieve", description = "This is dire. The Twilight's Blade is much larger--much more powerful--than any of us could have guessed.\n\nI'm relieved Umbric is on the case, but we need to let Silvermoon know what's happened here.", objectives = "Contact Silvermoon.", completion = "I was not expecting reinforcements so soon! Is your business with Magister Umbric complete, then?\n\nLet's get moving." }
WordHunterWoW_QuestEN[86638] = { title = "Choking Tendrils", description = "I haven't the expertise of Orweyna in these matters. But if the Lightbloom moved this quickly, I assume the rutaani are accelerating the spread here just as they were in Fairbreeze.\n\nThe town is beyond saving, but we can at least try to contain the Lightbloom within its walls.", objectives = "Cull the Lightbloom in Suncrown Village.", progress = "Fairbreeze was nothing compared to this. What... happened here?", completion = "We've cut back what we can. I only hope it's enough." }
WordHunterWoW_QuestEN[86639] = { title = "What's Left", description = "You see what we have to contend with here. Runestone Shan'dor is helping stop the spread further north, but if this Lightbloom surges again, I don't know if we can halt it.\n\nI've heard cries for help from survivors still trapped within. We have to find them, and direct them to safety!", objectives = "Find and aid survivors in Suncrown Village.", progress = "By the Light... this is so much worse than I would have ever imagined.", completion = "Some live... I am grateful, as are they." }
WordHunterWoW_QuestEN[86640] = { title = "Premonition", description = "I came as quickly as I could. This is... devastating.\n\nI have called in our Magisters to reinforce this runestone. They will keep an eye on the Lightbloom spread.\n\nI suspect Halduron Brightwing and the Farstriders have uncovered more than the villagers know. I can rely on him for anything. We shall rendezvous with him at the encampment to the north, and soon have some answers.", objectives = "Regroup with Lor'themar Theron at Scintilas Outpost.", completion = "<Lor'themar falls still, eyes on the shore ahead.>" }
WordHunterWoW_QuestEN[86641] = { title = "Old Scars", description = "Of course the Amani would use this moment to encroach, the cowards. We are beset on all sides!\n\nThis land belongs to the sin'dorei, and I will not see it taken by anyone. Not by raging plants, not by a cult, not by the Void, and never by the Amani!\n\nWhatever they are doing over there, it must be stopped. Do whatever you can to disrupt them and send them scurrying back to Zul'Aman where they belong.", objectives = "Disrupt the Amani lumber operation in Tor'Watha.", completion = "Whatever their reasons, the Amani will regret this trespass." }
WordHunterWoW_QuestEN[86642] = { title = "A Foe Unseen", description = "I know Lor'themar is angry, but... this is strange, {name}. They didn't attack Suncrown--the Lightbloom did. What are the Amani doing over there?\n\nThere has to be some kind of explanation for this. It doesn't look like an invasion. Let's see what we can find out.", objectives = "Find information about what the trolls are doing in Tor'Watha.", completion = "What have you found?" }
WordHunterWoW_QuestEN[86643] = { title = "Following the Root", description = "Lor'themar has a right to defend this land, but I don't think he's seeing clearly. The presence of Amani is too inciting.\n\nThis doesn't add up. The trolls are going out of their way to craft Lightbloom weapons--to fight what? It isn't us. They didn't attack Suncrown. They could have, and they didn't.\n\nWe need to find the truth. Let's head south. That hideout I discovered must have some answers.", objectives = "Meet Arator at Watha'nan Crypts in Eversong.", progress = "There must be a reasonable answer for all of this.", completion = "The Twilight's Blade are terrorizing Zul'Aman as well? This is no coincidence!" }
WordHunterWoW_QuestEN[86644] = { title = "Gods Before Us", description = "I suppose I shouldn't have expected a greeting with open arms, but I did not expect to be trapped in here.\n\nThe Amani are clever. They must have made a way to escape. We have only to find it. Let's look around.", objectives = "Explore Watha'nan Crypts and pursue Zul'jan.", progress = "There's a way out of here--I know it.", completion = "You made that look easy." }
WordHunterWoW_QuestEN[86645] = { title = "Hidden Quest [DNT]", description = "", objectives = "" }
WordHunterWoW_QuestEN[86646] = { title = "An Impasse", description = "How deep does this crypt go?\n\nWe need to find Zul'jan and explain to him that we fight a common enemy. Surely he'll see reason!\n\nCome on. They can't have gotten much farther in this maze.", objectives = "Pursue Vanatha and Zul'jan deeper into Watha'nan Crypts.", completion = "This is senseless. We have to stop it!" }
WordHunterWoW_QuestEN[86647] = { title = "Beat of Blood", description = "None of this is necessary. We need to make them see reason!\n\nMy father will know what to do. I know he'll see reason, once I explain what has happened here. There is no need for bloodshed! It's simple: if the Amani are set against the Twilight's Blade, we fight on the same side.", objectives = "Meet Arator at the Amani Pass.", completion = "I must put a stop to this." }
WordHunterWoW_QuestEN[86648] = { title = "Light Guide Us", description = "Our findings at Tor'Watha were correct. By the time Turalyon and I arrived here with troops, the Amani had already begun to take the pass. They seek to establish another path to acquire the lightwood from our land.\n\nThe Amani have chosen war, as they always do. This, at least, is a threat I know how to handle.\n\nArator is but a boy. He cannot grasp the magnitude of history between the sin'dorei and Amani--and I don't expect him to.\n\nWill you stand by the blood elves, and all that is right?", objectives = "Resolve the battle at the Amani Pass by helping the blood elves secure it, or try to dissuade the blood elves from fighting.", completion = "There he is--the one who leads this little incursion." }
WordHunterWoW_QuestEN[86649] = { title = "Past Redemption", description = "These monsters deserve nothing more than swift retribution. For Silvermoon. For the sin'dorei.\n\n<Turalyon's eyes blaze with Light.>\n\nFor Alleria. This will be finished!", objectives = "Finish the battle against the Amani at the Amani Pass.", completion = "I did not expect... this. \n\n<Lor'themar glances at Turalyon.>\n\nPerhaps we overstepped our bounds." }
WordHunterWoW_QuestEN[86650] = { title = "Fractured", description = "Lady Liadrin will remain here. The rest of us shall return to Silvermoon and debrief.\n\n<Lor'themar looks at the devastated Turalyon.>\n\nWe still have many battles ahead, it seems.", objectives = "Return to Silvermoon City.", progress = "There is much to do.", completion = "Would that I could join you, but there is much still to do here in Silvermoon. \n\nYou have your objectives. Keep in touch.\n\nAs for Arator... I hope you find him soon. Anu belore dela'na, <name>." }
WordHunterWoW_QuestEN[86652] = { title = "Left in the Shadows", description = "De loa have not spoken to us in many years... not since I was a young child.\n\nAnd dey have shown no sign of wanting to help us now.\n\nNo. It is up to us alone. We must find a way to rally de other tribes and fight de Twilight's Blade as one.\n\nI will speak to de tribal representatives and help de refugees where I can--dey are our priority.\n\nCome, you might learn somethin' about de Amani.", objectives = "Join Zul'jarra and Liadrin as they check on Atal'Aman refugees.", progress = "Ancestors willing, we will find our opportunity to strike back soon.", completion = "Hash'ey? Has uncle lost his sense?\n\nIt is a tale for children. Maybe if this were de old days, generations ago, before de elves arrived...\n\nBut if de last chance we got is to try to speak to the loa, then I will try." }
WordHunterWoW_QuestEN[86653] = { title = "The Path of the Amani", description = "Kinduru is my uncle, and I trust him... But dis \"path of de hash'ey\"...\n\nThings are not what dey were decades ago. The loa are gone--they not gonna hear us.\n\n<Zul'jarra lets out a low growl only you and Liadrin hear.>\n\nNo. We're running out of options. If dis is de time for old myths and dreams, so be it.\n\nWe meet at the foot of the mountains, Akil'zon's Reach, where de old hash'ey shrines are.", objectives = "Meet Zul'jarra outside Akil'zon's Reach.", completion = "Dis path is thick with gnarldin.\n\n<Zul'jarra smiles broadly.>\n\nI hope dey try to stop us. I can sharpen my blade on dey bones." }
WordHunterWoW_QuestEN[86654] = { title = "Gnarldin Bashing", description = "Zul'jarra regards the gnarldin as a fierce, nomadic people that normally keep to themselves. It is clear by their clothing and weapons that they have a primitive but unique culture.\n\nIf the circumstances were different, I would advocate for diplomacy.\n\nBut they are between us and our mission.\n\nThey cannot block our path or continue to damage the shrines or the nests of the eagles that roost here. We will eliminate only those that are in our way. The Amani can choose what to do with them later.", objectives = "Slay 12 gnarldin in Akil'zon's Reach.", progress = "The gnarldin seem ready to fight us. Let's give them what they want, shall we?", completion = "Good. Hopefully that clears the path to the shrines and the temple enough for our purposes." }
WordHunterWoW_QuestEN[86655] = { title = "De Ancient Path", description = "My uncle, de loa speaker, spoke of de hash'ey when I was a child. But when de loa remained silent so many years...\n\nI do not think he would admit it, but he lost a little faith too.\n\nI remember some of his lessons.\n\nA chieftain must light de shrines on de way to de temple. De hash'ura must as well. Why? I do not remember.\n\nBut if it is de only way to get de loa's favor? Come. Let us get dis out of de way.", objectives = "Light the 4 Hash'ey Shrines in Akil'zon's Reach.", progress = "I hope we are doing dis right.", completion = "De shrines are lit.\n\nNow what do we do?" }
WordHunterWoW_QuestEN[86656] = { title = "Brutal Feast", description = "<Zul'jarra's brow furrows and her lip curls as she looks toward the temple.>\n\nWhen we lit de last shrine, some of de eagles returned to de temple. It could be a sign.\n\n<Zul'jarra scoffs.>\n\nOr de eagles are movin' in after de gnarldin started movin' out.\n\nWhen we get to the temple, all we gonna find is silence. Just like always.\n\nBut we still gonna try. We should go now and present an offerin'.", objectives = "Reach the Temple of Akil'zon and seek Akil'zon's attention.", completion = "That voice...\n\nYou heard it too, <name>?" }
WordHunterWoW_QuestEN[86657] = { title = "Shadebasin Watch", description = "<Zul'jarra smiles slightly as Akil'zon's blessing buffets her.>\n\nKinduru's stories were real. We have de blessin' of Akil'zon, and de path of the hash'ey stretches out before us.\n\nWe must follow Akil'zon's advice and seek out Halazzi next. As Akil'zon is de loa of de rulin' tribe--de Amani--and my family, Halazzi is de loa of the Witherbark and their leaders.\n\nIf their loa speakers are gone, then maybe Kul'amara will know how to approach him.", objectives = "Speak with Kul'amara the Fierce at Shadebasin Watch.", progress = "I thought de Witherbark were strong enough to handle de Vilebranch on their own. I should have come here before now.", completion = "De Vilebranch have caused my people sufferin' for too long.\n\n<Zul'jarra glares in fury at the nearby Vilebranch village of Maisara.>\n\nIt's been a long time coming, but now's de time to deal with them." }
WordHunterWoW_QuestEN[86658] = { title = "The Crypt in the Mist", description = "<Zul'jarra growls through her gritted tusks.>\n\nNow it's not as surprisin' dat Malacrass's tribe, de Vilebranch, fell to the lure of hex magic.\n\nBut dat is their choice and a path dey chose long ago--a path away from us.\n\nI won't let dem live long enough to regret it.\n\nWhat de Vilebranch have done to de Witherbark has gone too long without an Amani response. De mist is not in our way.\n\nWe can use it to our advantage.\n\nWe will take a life for all de lives dey took. And make sure dey stay dead.", objectives = "Slay 8 Vilebranch trolls and Ritualist Zongha in Numazon Crypt.", progress = "Finding Halazzi can wait. The Vilebranch are preyin' on my people. It's about time some predators hunted dem.", completion = "<Zul'jarra spits on the ground.>\n\nDisgusting. Dey deserve to be brought back and killed a hundred times.\n\nI hope whatever loa awaits dem in de afterlife swallows dem whole and grinds dem with its back teeth." }
WordHunterWoW_QuestEN[86659] = { title = "Breaching the Mist", description = "The Vilebranch seemed to be just as confused by the mist as the Witherbark.\n\nWhatever has caused de mist, dealin' with de Vilebranch changed nothing.\n\nAnd now we must find de hash'ey shrines in de dark.\n\n<Zul'jarra moves her hand in front of her face, testing her range of visibility, and frowns.>\n\nWe must light de shrines. Try not to get separated.\n\nDis will try my patience. But I'm sure if we use our heads, we will find de path.", objectives = "Light the Hash'ey Shrines around the Temple of Halazzi.", completion = "Findin' Halazzi and de hash'ey shrines has taught me patience. And forced me to think through my obstacles, instead of cuttin' my way through dem.\n\nI wish Zul'jan were here. He would be proud of me for gainin' some brains. Heh." }
WordHunterWoW_QuestEN[86660] = { title = "Rescue from the Shadows", description = "Kul'amara has told me dat a shadowy mist has fallen over Numazon. She believes de Vilebranch are behind it, usin' their magic to hide de crimes dey commit against de Witherbark.\n\nShe believes dey are hidin' in de Numazon crypts. De hash'ey shrines are near there as well.\n\nWe must find our way to Numazon and rescue de Witherbark captives. If we find de hash'ey shrines along de way, so be it.\n\nIf Halazzi will not stand with us, den maybe de Witherbark will.", objectives = "Rescue 8 Witherbark captives in Numazon.", progress = "Keep on de lookout for more Witherbark captives!", completion = "So that's why the Vilebranch wanted de Witherbark--to please de Twilight's Blade by givin' dem more soldiers.\n\nUndead soldiers. Obedient soldiers.\n\nAnd we have already lost too many." }
WordHunterWoW_QuestEN[86661] = { title = "Coals of a Dead Loa", description = "By helpin' de Witherbark, we helped ourselves--and passed Halazzi's trial.\n\nThere is a lesson in that.\n\nNow dat Halazzi has returned, we should go back and let Vun'zarah know. I hope dis will improve de relationship between our tribes.\n\nAnd maybe he knows where we can find out how to resurrect Jan'alai.", objectives = "Travel to Witherbark Bluffs and speak with Vun'zarah, leader of the Witherbark Tribe.", progress = "We have come dis far. We must try to resurrect de dead loa.", completion = "\"Eccentric loa speaker.\"\n\nHeh. That sounds familiar. I guess dey are all like dat." }
WordHunterWoW_QuestEN[86663] = { title = "Embers to a Flame", description = "The loa speaker talks of fire in de heart--in all hearts.\n\nJan'alai is de loa of birth, death, and rebirth. Maybe de loa speaker is askin' for sacrifice.\n\n<Zul'jarra smiles deviously.>\n\nHey, Liadrin. How much fire you think is in an elf's heart, eh?\n\n<Liadrin gives her a sour look.>\n\nHeh.\n\nWhatever de loa speaker wants, it is either part of resurrectin' de loa or part of de trial. Let's see what he has do say.", objectives = "Slay Amazards to empower the Ember of Jan'alai.", progress = "This loa speaker's holding onto his faith a bit like Kinduru. But Kinduru knows how to speak clearly what he means. Usually.", completion = "<Zul'jarra watches the flames dance in the coals. A small smile creeps up on her face. She balls her fists and flexes her arms.>\n\nI think dis trial is starting now.\n\nWhatever it throws at me... I'll be ready!" }
WordHunterWoW_QuestEN[86664] = { title = "Seer or Sear", description = "Dis old, crazy loa speaker is too busy dancin' to tell us what to do next.\n\nBut I think I know.\n\nWe could not light de shrines on de way to de temple. But now dat Jan'alai's presence is here...\n\nMaybe now we can.\n\nI will take de ember to de hash'ey shrines. Den maybe de trial will start.\n\nI jumped from de top of de temple of Akil'zon. I found my way through de mists of Halazzi.\n\nI am ready for Jan'alai's fire.\n\nWe can only hope dey will receive us after what my grandfather has done.", objectives = "Assist Zul'jarra in lighting Hash'ey Shrines of Jan'alai.", progress = "No stoppin' de trial now. We must do what needs to be done.", completion = "<Zul'jarra brushes some ash off her shoulder.>\n\nJan'alai's flame... it has taken de doubts from my heart and given dem form.\n\nI... was not prepared for dat.\n\nWhat else do they have in store?" }
WordHunterWoW_QuestEN[86665] = { title = "Face in the Fire", description = "First my grandfather, then my brother.\n\nJan'alai knew my shame at my grandfather's rage. And de rage I feel when Zul'jan disrespects me. I know I put fuel on his fire by respondin' de way I do. \n\nMaybe dat needs to change. I have left my doubt of de loa behind me. I can leave those thoughts behind too, and continue de path of de hash'ey.\n\nStoke de coal, {name}. I am ready for de final trial, whatever it may be.", objectives = "Slay the last Fire Manifestation in the Temple of Jan'alai.", progress = "Let's get dis over with.", completion = "Fittin' that de last test be facin' my own doubt. About my leadership and my choices.\n\nIt felt good. As if de doubt melted away.\n\nAnd I gotta say... I never seen flames so fit and handsome.\n\n<Zul'jarra, despite it all, laughs heartily and claps you on the shoulder.>" }
WordHunterWoW_QuestEN[86666] = { title = "In the Shadow of Rebirth", description = "Jan'alai's trial has made me realize...\n\nI need to make things right between me and my brother.\n\nHe acts out at me, but it's because I put him down. I do not think about how hard it must be to be my brother.\n\nWe should also check on how our preparations are goin' and if my troops are gettin' de food and rest dey need.\n\nNalorakk's not gonna go anywhere. He can wait a few hours.", objectives = "Meet Zul'jarra in Amani'Zar Village.", completion = "So many dead..." }
WordHunterWoW_QuestEN[86681] = { title = "Den of Nalorakk: A Taste of Vengeance", description = "Zul'jan has taken de troops without my orders--again!\n\nAnd de number of casualties... for what? For wood?\n\nI want to take his tusks and...\n\n<Zul'jarra growls but seems to center herself.>\n\nKinduru will need help with de soldiers' death rites. Help him prepare de herb mixture and pour it onto de fires.\n\nMy brother and I need to... talk.", objectives = "Assist Elder Kinduru with the death rites.", progress = "There are so few of us left. What was my brother thinking?", completion = "I love my brother. We are as de day is to de night. But even so, as children we were close.\n\nZul'jan is smart but he doesn't understand. A victory means nothin' if there is no one left to celebrate it.\n\nHe is supposed to be my right hand, not a pain in de neck.\n\nI hope I have not left Zul'jan without guidance too long to turn him around." }
WordHunterWoW_QuestEN[86682] = { title = "Den of Nalorakk: Waking de Bear", description = "We must set aside what Zul'jan has done and focus on de final hash'ey trial: facin' Nalorakk, de Loa of War.\n\nDe Revantusk were once beloved of Nalorakk. Legend has it dat his loa speaker was so devoted, she followed him into his temple and his den with de most faithful of de Revantusk's warriors.\n\nBut now de temple is sealed. We cannot speak to de loa speaker, but maybe Lilaju knows how to get Nalorakk's attention.\n\nShe keeps watch for de Twilight's Blade at Torntusk Overlook with her guards.", objectives = "Travel to Torntusk Overlook and speak with Lilaju, the Revantusk leader.", progress = "Lilaju is de only person who can help us now.", completion = "I do not pity Lilaju--I was around her age when I took my place as leader of de Amani.\n\nI am proud of her. She is stickin' up for herself and her tribe.\n\nShe gave us what we needed. And I will not go back on my promise of helping her." }
WordHunterWoW_QuestEN[86683] = { title = "Hash'ey Away", description = "We've done it, {name}. De loa are at our side once again.\n\nAm I hash'ey? I do not know. But I do know I would not have gotten dis far without my hash'ura.\n\nCome. We will return to Amani'Zar and tell Kinduru and Zul'jan de good news.", objectives = "Meet Zul'jarra at Amani'Zar Village.", completion = "Now dis will be a fight!" }
WordHunterWoW_QuestEN[86684] = { title = "The Blade's Edge", description = "With de other tribes and de loa's help, we can take de fight to de Twilight's Blade and take dem down.\n\nBlood for blood!", objectives = "Meet Zul'jarra and Liadrin at Broken Throne to fight the Twilight's Blade.", completion = "<Zul'jarra's piercing eyes survey the battlefield. She mutters under her breath what you can only imagine is troll profanities. You hear her say \"Jan\" among them.>\n\nDe battlefield is full of bodies. De bodies of my people. But there are more still in de fight!\n\nThere is time to turn de tide!" }
WordHunterWoW_QuestEN[86685] = { title = "Chip and Shatter", description = "<Zul'jarra shakes her head back and forth and jumps in place, shaking out her muscles.\n\nShe stops and turns to you, grinning broadly.>\n\nHeh. Do you feel it, my hash'ura?\n\nDe electricity in de air? De smell of blood and fire?\n\nMy soul is leapin' to join de fight.\n\nYou ready to chop de enemy down, bathe in dey blood, and make dem pay for what dey done?\n\nMe too.", objectives = "Slay the Twilight's Blade at Broken Throne.", completion = "That was good.\n\nBut I still thirst for more." }
WordHunterWoW_QuestEN[86686] = { title = "Light Indiscriminate", description = "Though the dead litter this field, I still see plenty of Amani clinging to life.\n\nHelp me heal the injured. We'll ensure their reputation for survival continues on after this day.", objectives = "Heal 10 Injured Amani Warriors.", progress = "Every warrior healed is another sword at our side!", completion = "I look forward to Lor'themar's expression when I report back.\n\n<A slight smile creeps across Liadrin's blood-spotted jaw.>\n\nIt's bound to be worth more than my inevitable reprimanding." }
WordHunterWoW_QuestEN[86687] = { title = "Conduit Crisis", description = "With de loa at our side, we can finally break de Twilight's Blade and return to Amani'Zar with Mor'duun's head.\n\nDe loa are already attackin' de main source of Mor'duun's power: summoned spheres of pure void energy.\n\nGo to de loa and offer your assistance. When de orbs are destroyed, we can move forward and strike at Mor'duun!", objectives = "Destroy the 12 Void Conduits hindering Nalorakk, Akil'zon, Halazzi, and Jan'alai in Broken Throne.", progress = "Don't be afraid. If you assist dem, de loa will grant you their strength.", completion = "The sight of de loa fightin' by their side has filled our warriors with hope.\n\nDey remember dat dey are Amani!" }
WordHunterWoW_QuestEN[86692] = { title = "Blade Shattered", description = "It ends here. De path of the hash'ey, my path, has led me here.\n\nLet dis fight bring a new age for my people.\n\nCome. It is time.", objectives = "Slay Mor'duun, High Inquisitor of the Twilight's Blade.", completion = "<Zul'jarra snorts and spits out a viscous wad of blood, broken tooth included.>\n\nIt is done." }
WordHunterWoW_QuestEN[86693] = { title = "De Legend of de Hash'ey", description = "Mor'duun is slain.\n\nDe Twilight's Blade will continue to plague our lands, but of dem only Mor'duun's \"fodder\" is left. Dey will be easy prey for us.\n\nAnd now I will say somethin' my uncle would be proud of. Let us follow de teachin' of Nalorakk, de Loa of War.\n\nDe battle is over. It is time to rest--I can tell by your eyes both my hash'ura need it too.\n\nLet us leave dis place. We can speak again back in Amani'Zar.", objectives = "Speak with Zul'jarra in Amani'Zar Village.", completion = "It did not occur to me dat what we would be celebratin' would be... me.\n\nThere has been no hash'ey among de Amani since before de elf and human war thousands of years ago.\n\nIt is a great honor, but one I am not sure I have yet earned.\n\nI will strive to live up to it." }
WordHunterWoW_QuestEN[86696] = { title = "Shadow Re-Disruption", description = "", objectives = "" }
WordHunterWoW_QuestEN[86697] = { title = "The Cleanup Crew", description = "Even if we got bots out there an' not workers, there are still gonna be monsters out there gettin' in their hair, er, wirin'.\n\nGet out there an' thin out the wildlife. That'll keep our bots from gettin' damaged and voidin' whatever warranty they got left.\n\nThe longer they can stay out there, the longer we can stay right here!", objectives = "Kill enemies in the Writhing Fields in the Ringing Deeps.", progress = "Got any good news, kid?", completion = "That's what I'm talkin' about!\n\nNow those bots'll be able to work without bein' hassled by all them nasty Black Blood monsters out there." }
WordHunterWoW_QuestEN[86698] = { title = "Work It", description = "The Trial of Style gives us the opportunity to look good. {class}.\n\nThe camera makes sure we keep looking good. \n\nSo focus on me and my camera, follow my directions and I'll make sure you look fantastic!", objectives = "Focus on the photographer and follow their directions.", progress = "Focus on me and follow my directions. \n\nI'll make sure you look great.", completion = "The camera doesn't lie, <name>. \n\nYou are one stylish <class>." }
