WordHunterWoW_QuestEN[86706] = { title = "Seeking Knowledge of the Past", description = "Greetings, {race}. I must seek your aid. Soridormi and our kin have journeyed to Khaz Algar to help in this fight against the Void's new master.\n\nWe think that we can provide insight and valuable information about past attacks by the Void. \n\nSeek her out near the southern edge of the Coreway.", objectives = "Seek out Soridormi near the Coreway in Dornogol on the Isle of Dorn.", completion = "You are just in time as always! Let us speak of what brings me here." }
WordHunterWoW_QuestEN[86707] = { title = "The Shadowguard Resurgence", description = "", objectives = "" }
WordHunterWoW_QuestEN[86708] = { title = "The Gates of Zul'Aman", description = "After the Amani surrender, we demanded Zul'jan relinquish our lightwood and return to their lands. Even so, Zul'jan still lingers at the gates of Zul'Aman with his troops.\n\nLady Liadrin and her Blood Knights hold the pass, and Liadrin is trying to remedy the situation with diplomacy, but she reports that aggression may begin anew.\n\nShe requests your assistance in this precarious matter.", objectives = "Meet Lady Liadrin at the Amani Pass.", completion = "Our ceasefire is strained, but holding. For now." }
WordHunterWoW_QuestEN[86709] = { title = "Mana Falling from the Skies", description = "", objectives = "" }
WordHunterWoW_QuestEN[86710] = { title = "The Line Must Be Drawn Here", description = "I had hoped that Zul'jan would leave the lightwood and return swiftly to his lands after our confrontation with him.\n\nBut dealing with the Amani has never been a simple matter.\n\nDiplomacy is the only way to avoid more bloodshed, but Zul'jan is finished listening to me.\n\nPerhaps he will listen to you?", objectives = "Speak to Zul'jan and diffuse the situation.", progress = "An outsider's view may help him see reason.", completion = "I find myself relieved to discover Zul'jan is not the leader of the Amani.\n\nBut this \"Zul'jarra\" might be worse.\n\nNo matter. We must get on the other side of that gate and assess the Twilight's Blade's threat to Eversong." }
WordHunterWoW_QuestEN[86711] = { title = "Amani Clarion Call", description = "If you want to survive here in Atal'Aman, find and beat de city's battle drums. Dat will rally our remainin' soldiers forward to join de fight.\n\nIt will also bring all de tribes of Zul'Aman--de Witherbark, de Revantusk, and de Shadowpine--to our aid and tell our civilians to retreat to de Altar of Malacrass if we need to evacuate.\n\nUse de drums to spread de word. Find me at de Altar of Malacrass when you are done.", objectives = "Sound the Amani War Drums in Atal'Aman.", completion = "Many Amani found their way here, but we have more to aid.\n\nAnd even more enemies to kill." }
WordHunterWoW_QuestEN[86712] = { title = "The Amani Stand Strong", description = "Zul'jarra doesn't think de lightwood is worth de risks I am taking. We will prove her wrong.\n\nI have seen too many warriors discouraged because their weapons don't work against de Twilight's Blade.\n\nDon't just tell them to retreat. Give them de lightwood weapons.\n\nNothing stirs Amani blood like an effective axe in their hands. Let dem fight their way back to de Altar of Malacrass.", objectives = "Give 8 Lightwood Weapons to Demoralized Defenders.", completion = "De troops we armed have killed a great many Twilight's Blade.\n\nSome survived and made their way here.\n\nWe lost a few, but I think de sacrifice was worth it." }
WordHunterWoW_QuestEN[86715] = { title = "Rituals Cut Short", description = "In our reconnaissance flight around the city, Zul'jarra and I got a look at the Twilight's offensive. They're summoning more Twilight's Blade directly into Atal'Aman.\n\nWe can counter them by disrupting their dark summoning rituals. That will stop the flow of their cultists into the city and give the Amani time to strategize.\n\nKill the ritualists, and any trollbreakers already portaled into the area.", objectives = "Destroy 6 Twilight Ritualists and 6 Twilight Trollbreakers in Firewing Terrace.", progress = "We cannot allow the Twilight's Blade to bring even more troops into Atal'Aman.", completion = "That should slow them down--at least for the moment." }
WordHunterWoW_QuestEN[86716] = { title = "Armed by Light", description = "You might be good at killing, {class}, but so are we Amani.\n\nAnd even more de better our weapons!\n\nI took an army into Eversong to reclaim de lightwood forests for de Amani. It was against my sister's orders, yes, but lightwood gives us an advantage.\n\nTake back de weapons being stolen by de Twilight's Blade, and I'll show you why it was worth de effort.", objectives = "Recover 8 stolen Lightwood Weapons.", progress = "These weapons are the difference between my people living or dying.", completion = "Good.\n\nNow we have teeth to bite back with." }
WordHunterWoW_QuestEN[86717] = { title = "Show Us Your Worth", description = "De Twilight's Blade's general, Mor'duun, has got us by de throat. We're not winnin', and we are too few.\n\nWe've got to evacuate before there's no one left--and hope de other tribes meet us at Amani'Zar.\n\nIn de meantime, I'm glad to use you while we rally de people of Zul'Aman. \n\nDe civilians' lives are my priority. Go to Swiftclaw Terrace and evacuate de people there.\n\nTear through de Twilight's Blade as you go. Find your way to Zul'jan when you're done.", objectives = "Rescue Amani civilians and destroy the Twilight's Blade presence at Swiftclaw Terrace in Atal'Aman.", progress = "Separate their limbs from their bodies. Tear down their banners and shelters too!", completion = "You cleared de way, but Mor'duun continues to keep us scrambling and off-balance.\n\nWe're gonna need as many lightwood weapons as we can get to end this." }
WordHunterWoW_QuestEN[86718] = { title = "Twilight Bled", description = "Mor'duun may be de leader of de Twilight's Blade in Zul'Aman, but dat ogre can't be everywhere. De elf found his military commander--a hulkin' pile of armor and flesh named Benvis Bladesplatter.\n\nHe's paradin' 'round like he's already won just because dey seized Firewing Terrace.\n\nMake him pay for his arrogance.", objectives = "Kill Benvis Bladesplatter at Firewing Terrace.", progress = "Have you ended him yet?", completion = "The next to fall will be Mor'duun." }
WordHunterWoW_QuestEN[86719] = { title = "Important Amani", description = "De drums have sounded. But de elders have not come.\n\nWe cannot lose them. They are our link to our culture--our sages and our best minds.\n\nTorundo helped devise de lightwood weapons. And Doru is our provisioner. We will need both if de battle goes on.\n\nGo find Doru in de market and Torundo in de tribute hall.\n\nDe last one is de old loa speaker--our uncle, Kinduru. He may need... special persuasion to leave. I will go to Talonstrike Terrace to speak to him. Meet me there after you find de others.", objectives = "Find the Amani Elders: Torundo the Grizzled, Doru, and Kinduru.", progress = "Do whatever is necessary to get Kinduru to leave.\n\nHe's our uncle. We can't leave him here.", completion = "Eagles... loa... we don't have time to dwell on de spirits of the past." }
WordHunterWoW_QuestEN[86720] = { title = "Break the Blade", description = "Zul'jan's ballista is ready. And it had better work after what he has done.\n\nWe lost de army we needed to defend de city, but we can fend off Mor'duun long enough to let our people escape.\n\nHelp my brother man de ballista. Focus on de shadow warders and de pylon. Liadrin and I will distract Mor'duun.\n\nI will kill him if I can, but even then we can't stay here. There's too much void energy. And too much destruction. Atal'Aman is truly lost.", objectives = "Use the Lightwood Ballista to destroy the Empowering Shadows and the Scrying Focus to bring down Mord'uun's barrier.", completion = "<Zul'jarra seethes with rage.>\n\nMor'duun is playin' with us. He coulda stayed and destroyed de city outright.\n\nIf chaos is de Twilight's Blade's plan, we need to prepare." }
WordHunterWoW_QuestEN[86721] = { title = "Everything We Worked For", description = "My blood is boiling! While waiting for Kinduru, de Twilight's Blade was destroying what little stores of lightwood we had left at Ragemaw Terrace!\n\nBut if we act quickly, we can save enough to arm de lightwood ballista--and take a shot at Mor'duun.\n\nAnd without de ballista, we cannot claim victory!", objectives = "Extinguish fires on the Lightwood Piles at Ragemaw Terrace.", progress = "Don't let de lightwood burn!", completion = "We lost so much of it...\n\nWe could have blacked out de sky with ballista bolts!\n\nBut dis still may be enough. It will have to be!" }
WordHunterWoW_QuestEN[86722] = { title = "Heart of the Amani", description = "You and your elf friend amuse me. And you've more than proved yourself in battle.\n\nOur people are headin' to Amani'Zar. We hope dat de other tribes rallied there instead of Atal'Aman. Their representatives will give us council, and then we will mount an attack on de Twilight's Blade.\n\nIf you still wish to fight with de Amani, meet me on de northwest side of de village. Zul'jan will have gone ahead to speak of his deeds--and yours--but do not enter de village without me. Amani kill strangers on sight.", objectives = "Meet Zul'jarra at the entrance to Amani'Zar Village.", completion = "Tokobo'ne na Amani'Zar, <name>. Welcome to Amani'Zar.\n\nBecause you are my guests, my people will not harm you... unless I say so.\n\nDon't give me a reason, yeah?" }
WordHunterWoW_QuestEN[86723] = { title = "Isolation", description = "We will speak to Torundo, my war advisor. And if de representatives of de tribes are here, we will have a council meetin' in de Zari Lodge.\n\nTogether, we must agree on a way to defeat de Twilight's Blade.\n\nExplore de village if you want. But keep your weapons where dey can be seen. You are here by my invitation and my word is law, but I can only run so fast if one of my people thinks you looked at dem in de wrong way.\n\n<Zul'jarra smiles a tusky grin as if proud of her people's short fuse.>", objectives = "Meet Zul'jarra and Liadrin to assess the situation with the other troll tribes.", progress = "I need de advise of my advisor, Torundo. And we must see why de other tribes did not heed de drums.\n\nDey may think I am desperate to ask for your help. But dey also would dare not challenge me.", completion = "There is... much you do not know about us and de loa." }
WordHunterWoW_QuestEN[86728] = { title = "Operation: Floodgate: Disposing of the Garbage", description = "Hey, pal. I've heard murmurs of a real piece of work trying to siphon off energy at the Waterworks in the Ringing Deeps.\n\nStealing from our stone friends ain't good for business, and it certainly ain't something we're willing to let continue.\n\nI know you've made a name for yourself for disposing of the trash, and bad business folks are certainly as trashy as they come.\n\nDo me a favor, will ya? Weapons are optional, but attitude is required... if you catch my drift.", objectives = "Defeat Geezle Gigazap in Operation: Floodgate.", progress = "Yo, you take care of that \"thing\" for me?", completion = "Thanks pal. The cartels will remember what you did for them." }
WordHunterWoW_QuestEN[86731] = { title = "An Original Path Through Time", description = "Ever since your city fell out of the sky, I have learned more of this world's history and the challenges that heroes like yourself have faced. \n\nLearning from the past is how we ensure our future. Walk through time to the humble beginnings, defeat those threats once more, and bring those lessons forward.", objectives = "Complete 5 Timewalking dungeons.", completion = "What lessons do you bring from your journeys through time?" }
WordHunterWoW_QuestEN[86733] = { title = "Silvermoon Negotiations", description = "It would be an understatement to say things between Silvermoon and the Alliance are often tense and uneasy. I thank you for setting aside any prejudices you might have had and lending your strength to the defense of Silvermoon and the Sunwell.\n\nWe have Xal'atath's forces held for now, but this is far from over.\n\nI would include you in our next steps. Meet me at the Sanctum of Light.", objectives = "Journey to Silvermoon City.", completion = "I'm glad you've arrived. Let's begin." }
WordHunterWoW_QuestEN[86734] = { title = "Diplomacy", description = "We shall all weigh in on the situation.\n\n<Lor'themar glances at Umbric and Rommath.>\n\nAs you can see, there are many tensions at play.\n\nPlease give us a moment to discuss.", objectives = "Listen to the discussion.", progress = "We have much to discuss.", completion = "There are those that will disagree with my decision. But I will not have us lose our home. If we must host temporary guests, so be it." }
WordHunterWoW_QuestEN[86735] = { title = "Paved in Ash", description = "Now that the matter is settled, you should acquaint yourself with Silvermoon. There are a few key civilians I'd like informed about your presence here--you should check in with them.\n\nShow them my signet ring--they'll know you've my permission to be here. But please take care where you go, and stay in the outer city to avoid any issues.", objectives = "Show Lor'themar's Signet around the city.", progress = "Have you spoken to everyone yet?", completion = "Remember, you are a guest here. Your aid is appreciated, but our rules must be followed while you are within these walls." }
WordHunterWoW_QuestEN[86736] = { title = "Paved in Ash", description = "I've more to review with Turalyon, but in the meantime, the rest of the city should be informed that we will have some temporary guests in the outer perimeter. I'd like you to check in with a few key civilians and deliver the news.\n\nWhile you're out there, take the chance to familiarize yourself with Silvermoon. We've made impressive strides rebuilding it since you've last visited.", objectives = "Check in with civilians around the city.", progress = "Have you met with everyone?", completion = "While the Alliance and the Vanguard may become an additional stress for some, their presence is to be tolerated... for now." }
WordHunterWoW_QuestEN[86737] = { title = "Fair Breeze, Light Bloom", description = "In recent years, small pockets of wild growth we call \"Lightbloom\" have blossomed throughout Eversong. A curiosity for our local botanists, for the most part.\n\nHowever, the Magistrix in Fairbreeze is asking for help with the local Lightbloom. Every capable hand I have is focused on holding back the Voidstorm--but if the Magistrix cannot handle the matter herself, it requires swift attention.\n\nI'd like you to see to the issue. Magister Rommath can provide you with an arcane projector to keep in touch.", objectives = "Journey to Fairbreeze Village.", completion = "Thank goodness--everything is completely out of control!" }
WordHunterWoW_QuestEN[86738] = { title = "Sharpmaw", description = "These beasts roaming the village are nuisances, but we have a bigger problem.\n\nThere's a feral lynx prowling nearby that we call Sharpmaw. She used to keep her distance from the village, but the current situation has made her more bold. We've plenty of little ones around here, and more than once the guards have caught that beast eyeing them like they were a snack waiting to be snatched. \n\nStop her before she starts attacking my people in earnest!", objectives = "Slay Sharpmaw.", completion = "A what? Giant plants? Yet another problem... at least that beast is gone for good. Thank you." }
WordHunterWoW_QuestEN[86739] = { title = "Fairbreeze Favors", description = "This is the oddest situation I've ever been in--our village is being overrun!\n\nI like to keep things neat and tidy around here, but these animals... they've come in from the wilds like they own the town. They're attacking our sweet pets, overturning our belongings, and causing havoc. No sooner have I solved one problem than another is rearing its head. I'm only one elf--I can't stop all of this on my own!\n\nLend a hand, won't you? This... elf... troll... person hasn't lifted a finger.", objectives = "Help restore order in Fairbreeze Village.", completion = "Thank you so much. Maybe now I can get this village back to some semblance of order!" }
WordHunterWoW_QuestEN[86740] = { title = "Displaced Denizens", description = "The wildlife here seems to have been upset by something. Perhaps this is why the world's song bade me here: to discover why and correct it.\n\nStudy the displaced wildlife. Bring me your findings. If there is anything unusual, I wish to know of it. I will speak with the Magistrix. Perhaps together we can uncover this mystery.", objectives = "Study 3 disturbances caused by displaced wildlife and 3 unusual plants in Fairbreeze Village.", progress = "Perhaps we can solve this problem together.", completion = "This Lightbloom--it seems to be the cause of every trouble here." }
WordHunterWoW_QuestEN[86741] = { title = "Lightbloom Looming", description = "The wildlife seems to have been displaced from the south. It is there we will surely find answers.\n\nCome--I will use my magic to illuminate the path and we will follow the trail.", objectives = "Follow the trail of the displaced wildlife.", completion = "These creatures all come from here. This Lightbloom... this is where the song of the world was leading me." }
WordHunterWoW_QuestEN[86742] = { title = "Curious Cultivation", description = "This place is unlike anything I have seen before. The plant growth is unique.\n\n{name}, let us examine the Lightbloom more closely. Perhaps we can uncover the secrets of this place together.", objectives = "Examine 3 Lightbloom Plant Growths in Lightbloom Ath'Ran.", progress = "This makes no sense.", completion = "The rutaani are not like this! Not where I am from, at least. There is something affecting them. This behavior is not normal." }
WordHunterWoW_QuestEN[86743] = { title = "Trimming the Lightbloom", description = "The creatures of this Lightbloom see us as the intruders. They threaten the surrounding wildlife and inhabitants who are naturally here.\n\nWe should reduce their numbers and end this threat.", objectives = "Kill Lightbloom creatures in Lightbloom Ath'ran.", completion = "This will bring some peace to the region for now, at least." }
WordHunterWoW_QuestEN[86744] = { title = "Seeking Truth", description = "I will channel on this strange seed we have collected, and see if I can discover what has happened here.\n\nThis may upset the rutaani. Make sure I am not interrupted. This is why I was called here--I know now. But I must discover what needs to be done.", objectives = "Defend Orweyna.", progress = "Ah... perhaps we have some answers.", completion = "The rutaani are trying to spread the growth of the Lightbloom as far and wide as possible. But why?" }
WordHunterWoW_QuestEN[86745] = { title = "Silvermoon Must Know", description = "This growth--Lor'themar needs to know about this. I worry what will happen should it get out of control. \n\nAnd the Light's influence... my father should know, too.", objectives = "Contact Silvermoon.", progress = "We must contact Silvermoon to give them an update.", completion = "I hate to leave this as it stands... but Silvermoon should have enough information now to keep the Lightbloom at bay, while we wait for Orweyna's investigation.\n\nUntil then... we cannot address matters at the Sunwell without Umbric." }
WordHunterWoW_QuestEN[86769] = { title = "Last Bastion of the Light", description = "Your arrival has reignited hope.\n\nWe have pushed Xal'atath's forces away from the Sunwell, yet they still infest the Isle of Quel'Danas, and appear to be massing for another attack as they prey upon the sin'dorei.\n\nWe must join up with the Vanguard of Light.", objectives = "Follow Lady Liadrin to Parhelion Plaza.", completion = "We must use this miraculous event to turn the tide against chaos. We must not falter." }
WordHunterWoW_QuestEN[86770] = { title = "Champions of Quel'Danas", description = "Lor'themar has formed a rally point at Sunstrider Rise, while the civilians there are evacuated to Silvermoon, but the forces of the Vanguard of Light are scattered throughout the battlefield.\n\nWe need to fight as one to defeat this host. Together, we can defeat Xal'atath and save the Sunwell.", objectives = "Rally Faerin Lothar, Lothraxion, and Alonsus Faol at Light's Spire.", progress = "You have gathered help?", completion = "Thank you, <name>. With this force, we can protect the survivors and escort them to the boats." }
WordHunterWoW_QuestEN[86775] = { title = "Urge to Surge", description = "Occasionally we get more jobs than we can handle. You know what that means-- big money. Help out during some Surge Pricing and we'll see to it that you're thanked for your help.", objectives = "Complete a Surge Pricing event at least once.", progress = "Keep an ear out for when we call for help. Usually it happens within the hour.", completion = "Wow. We were swamped. Thanks for the help!" }
WordHunterWoW_QuestEN[86780] = { title = "Where Heroes Hold", description = "We have stopped the Devouring Host's initial attack. This battle will not be won if we go on the defensive, not even to safeguard the innocents of Quel'Danas.\n\nFocus on culling the Voidfront. Without their invading force, the Devouring Host cannot maintain a foothold!\n\nWe will rally at Sunstrider Rise when ready.", objectives = "Hinder the Voidfront forces along the walls of Parhelion Plaza.", progress = "Have you thwarted the enemy?", completion = "Excellent work, <name>. Their numbers dwindle as ours grow. The Light truly has brought hope to this battlefield." }
WordHunterWoW_QuestEN[86781] = { title = "Face the Past", description = "<Umbric scans the Eversong map with grave intent.>\n\nTranquillien was marked, as are a number of other locations. \n\n<Umbric stops, voice tightening.>\n\nWindrunner Village. It's marked.\n\nThe Twilight's Blade retreated to their base in Deatholme, but my home may be in peril. We must make sure my people in Windrunner Village are safe before pursuing them.", objectives = "Regroup in Windrunner Village.", completion = "It seems all is well here... for now." }
WordHunterWoW_QuestEN[86782] = { title = "Atrium Hospital", description = "The necrorays have been installed in the Atrium, and Hemet is seeing to them.\n\nHe has requested your presence.", objectives = "Meet Hemet Nesingwary in the Atrium.", completion = "Glad ye could come.\n\nLet's get started, eh?" }
WordHunterWoW_QuestEN[86783] = { title = "Rays of Sunshine", description = "Right then. Let's get these rays into Eco-Dome: Primus to the north!", objectives = "Meet Hemet Nesingwary in Eco-Dome: Primus.", completion = "Ready for round two?" }
WordHunterWoW_QuestEN[86786] = { title = "The Void Hunter", description = "The Void espouses all truths, {name}. And in none of them do I defeat Ramon'ta without some help.\n\nAnd here you are.\n\nMy quarry is a cosmic worm known as Ramon'ta the Insatiable. It started out small enough, but with each void entity it feasts upon, it grows, and its power grows along with it.\n\nIf we can defeat it, I can claim its power. Will you help me?", objectives = "Help Leona defeat the empowered cosmic worm and claim its power.", progress = "Wrap this up quickly, <class>. I have more important matters to attend to.", completion = "You've been helpful so far. And in return, I'll allow you to take part in making history on this discarded, broken corpse of a planet." }
WordHunterWoW_QuestEN[86800] = { title = "Swipe 'Em", description = "", objectives = "" }
WordHunterWoW_QuestEN[86801] = { title = "Faceless Mask of Multitudes", description = "By our multitudes will the world drown and feed the hunger of our gods. Only by bathing in the blood of our foes may one rise to the exaltation of our masters and unleash their never ending multitudes for themself.", objectives = "Return the Faceless Mask of Multitudes to the altar within a Horrific Vision.", progress = "Place the Faceless Mask of Multitudes on the altar.", completion = "Satiated in the blood of multitudes now and forever. For our ranks will be endless and consume the world." }
WordHunterWoW_QuestEN[86805] = { title = "The Hour of Need", description = "Turalyon is thinking like a battlefield captain and not like a leader! My people, the sin'dorei, have suffered much in these past few wars. How many must die in the name of his victory?\n\nPlease, {name}. Rescue any citizens you can and help guide them safely to the boats at the Silver Landing.\n\nEvery life saved is a victory for the blood elves.", objectives = "Rescue $10oa citizens, then head to the Silver Landing.", progress = "The ships still have space for more! Rescue as many as you can.", completion = "The citizens have boarded the ships. They will soon reach the safety of Silvermoon." }
WordHunterWoW_QuestEN[86806] = { title = "Luminous Wings", description = "No! Xal'atath's Host has opened portals above the strait. Void creatures spill out and descend upon the refugee's ships. We have to safeguard the civilians!\n\nThose dragonhawks have been empowered by the Light. They should give you enough power to defeat the Void beasts and rescue the fleeing civilians.", objectives = "Take flight on the Empowered Dragonhawk, destroy 16 Devouring Host, and rescue 3 civilians in need.", progress = "The ships full of sin'dorei refugees are still in danger.", completion = "The ships have crossed the strait and the refugees have made it safely to Silvermoon. Thank you, <name>. You have done my people a great service." }
WordHunterWoW_QuestEN[86807] = { title = "The Gate", description = "The High Exarch commanded us to assemble with his Vanguard of Light and attack the Devouring Host. I do not regret my delay of that order, but he will have noticed my absence.\n\nWe should make haste and assemble with the others.", objectives = "Assemble with the Vanguard of Light.", progress = "We shouldn't delay any longer.", completion = "Champion, I am glad to hear so many of the sin'dorei survived. Even though this was contrary to my orders to the Vanguard, you are not under my command. You acquitted yourself well. Arator did not." }
WordHunterWoW_QuestEN[86808] = { title = "The Riddled Speaker", description = "Chief Vun'zarah knew little of Jan'alai, but he did know about their loa speaker.\n\nIf dey are still at de temple, then there is hope we can resurrect de loa.\n\n<Zul'jarra's hand tightens on her axe.>\n\nMakin' Akil'zon flee, woundin' Halazzi, sendin' Nalorakk into a rage, and killin' Jan'alai...\n\nMy grandfather and Malacrass have so much to pay for.", objectives = "Meet Zul'jarra and Liadrin at the Temple of Jan'alai.", completion = "\"Purify yaself, and it will rise.\"\n\nI shoulda brought Zul'jan. He was always good with riddles." }
WordHunterWoW_QuestEN[86809] = { title = "Test of Conviction", description = "We got her attention. But now what?\n\nI know there is a trial. But Akil'zon is not givin' any hints on what it is.\n\nThink. Think. What did Kinduru teach me as a child? She is de loa of victory. But also of oaths and conviction.\n\nIf only we had made it to de top when I was a child, and I hadn't fallen...", objectives = "Prove yourself to Akil'zon with Zul'jarra.", completion = "<Zul'jarra's eyes are closed. She seems lost in thought.>\n\nDey were here all along. It was my grandfather's fault dey would not answer.\n\n<She nods her head and sighs.>\n\nMy grandfather broke dis. It is up to me to fix it. It is de only way to save my people." }
WordHunterWoW_QuestEN[86810] = { title = "Harvesting the Void", description = "To effectively counteract the void anomalies present here, we must obtain viable samples of the anomalies.\n\nSearch the area for containment vessels that hold developing anomalies, as well as the Unstable Oozelings created from the contamination.\n\nUse the collection device to make this process easier. Only living Oozelings will provide viable samples.", objectives = "Collect 20 Anomaly Samples.", progress = "Have you collected the necessary samples?", completion = "I'm quite certain these samples will not be enough, but it is a good start!  Check back later I may have some more tasks." }
WordHunterWoW_QuestEN[86811] = { title = "Ethereal Eradication", description = "{name}! I have a mission for you. There is a contingent of Shadowguard ethereals to the northeast.\n\nThey appear to be looting the buildings, but that could change in a moment. The Vanguard cannot afford to be flanked as we advance. Take out their leader and decimate their forces while we engage the Host.", objectives = "Eliminate Norkonahl the Looter and 12 Shadowguard intruders.", progress = "Have you completed the mission?", completion = "Excellent work, <name>. I knew I could count on you." }
WordHunterWoW_QuestEN[86820] = { title = "Manaforge Omega: Dimensius Looms", description = "This is it, {name}. We must defeat this Void Lord... no matter what it takes.", objectives = "Defeat Dimensius in the Manaforge Omega raid." }
WordHunterWoW_QuestEN[86821] = { title = "Phase Diving: Unmoored and Unwell", description = "", objectives = "" }
WordHunterWoW_QuestEN[86822] = { title = "One Final Relic", description = "{name}, I've asked the Sons of Lothar to meet us in the Burning Steppes near Blackrock Mountain. There's one more item we must recover there.\n\nWe can depart as soon as you are ready.", objectives = "Travel to the Burning Steppes and meet with the Sons of Lothar.", progress = "Good trip?", completion = "It seems we have more to do here than just finding a relic.\n\nThis area is overrun with a group that calls themselves the \"Dark Horde,\" and we are going to put a stop to their activities." }
WordHunterWoW_QuestEN[86823] = { title = "The Dark Horde", description = "I once served under Blackhand, long ago. His son Rend was a sniveling fool: a coward who bolstered himself in that Spire after Doomhammer was defeated. He made deals with dragons, called himself Warchief, and proclaimed his Dark Horde the \"true\" Horde. Pah!\n\nThis Dark Horde embraces the ideals of a past long gone. Rend died years ago, but there are still orcs and ogres here who cling to the rotting husk that remains.\n\nIf they haven't seen the truth by now, there is little hope for them but death.", objectives = "Kill 12 soldiers of the Dark Horde.", completion = "Perhaps, in the face of the death of their comrades, others will see sense as I did. At least those you killed won't dishonor themselves any longer." }
WordHunterWoW_QuestEN[86824] = { title = "None Left Standing", description = "The one thing worse than seeing this Dark Horde here is their banners.\n\nIt showcases their pride in this accursed mountain as a place of greatness--as a place for their horde to rise. In reality, this banner is little more than a defiled perversion of the ancestral Blackrock sigil.\n\nBurn down every one you find.", objectives = "Burn 6 Dark Horde Banners.", progress = "Got those banners dealt with, <name>?", completion = "I hope that this might demoralize some of these soldiers out of their misguided devotion to a failed cause.\n\nRegardless, I am glad those banners are not flying any longer." }
WordHunterWoW_QuestEN[86825] = { title = "Faithful Servant, Faithless Cause", description = "One of their lieutenants, Mar'kag, appears to be the one barking orders. His father, High Overlord Omokk, followed under Rend Blackhand's banner. Cruel, vicious... no surprise that his son follows in his footsteps.\n\nTaking Mar'kag down will spread chaos among the cowardly remnants of this Dark Horde and perhaps help them realize they are not as strong as they think.\n\nFaol also has us here to look for relic fragments. If Mar'kag has anything of note, bring it back.", objectives = "Defeat Mar'kag.", progress = "Did you put a stop to Mar'kag, <name>?", completion = "As we defeat their leaders, the Dark Horde presence throughout the Burning Steppes will continue to splinter.\n\nMar'kag was the first to fall. This was a good first step." }
WordHunterWoW_QuestEN[86826] = { title = "Nagosh the Scarred", description = "The Dark Horde may strut around inside the mountain, but an orc called Nagosh is the one rulin' this roost.\n\nHe barks orders, then charges straight into a fight. Rock-heads in command like that one are what gets everyone on all sides killed. \n\nI'd bet anything that numbskull claimed Faol's shiny relic. Keep an eye out. He may jump ye in the middle of a fight.", objectives = "Defeat Nagosh the Scarred.", progress = "Did ye put a stop to Nagosh?", completion = "Did ye get Faol's relic?\n\nI hope that old priest knows what he's doing." }
WordHunterWoW_QuestEN[86827] = { title = "Due Recognition", description = "Blackrock Mountain is where most of the Dark Horde has holed up. All their unit commanders adorn themselves with badges, struttin' around like they won the Second War. Shameful! But it gives me an idea.\n\nDefeat them and take their badges. Can't have new leaders that way--these blowhards like the pomp of command. Who wants the stress of leadership with no fancy badge to wear?\n\nHead on in there with Arator and keep 'em busy. Sky'reen an' I will support ye from the air.", objectives = "Retrieve Stone Guard Badges from the Dark Horde in Blackrock Mountain.", progress = "Did ye get their badges, <name>?", completion = "That gave 'em a kick in the pants! \n\nSee if any of 'em volunteer to lead their warbands now, after that humiliation!" }
WordHunterWoW_QuestEN[86828] = { title = "Not Just a Troll's Bane", description = "As much as I'd love to keep harassing these Dark Horde grunts, we've found the relic piece that Faol wanted us to. We best be getting on.\n\nDanath went looking for the last piece of the relic. You go find him, and I'll tell the mad bishop that his plan is nearly complete. Find me at Lothar's Statue when yer done.", objectives = "Find Danath Trollbane.", completion = "<name>, Arator--good to see you. I believe I have a solution to our problem." }
WordHunterWoW_QuestEN[86829] = { title = "A Landmark Moment", description = "With their leader defeated and that third relic fragment found, we should regroup with the others back at Lothar's Statue, {name}.\n\nI'll meet you there.", objectives = "Meet the Sons of Lothar at Lothar's Statue.", completion = "These fragments you've been recovering might be the most important relics of our journey, <name>." }
WordHunterWoW_QuestEN[86830] = { title = "A True Horde of Dark Horde", description = "The remaining Dark Horde forces are gathered here, {name}. Many of them look to be untrained and new to the cause.\n\nDrive away the forces gathered here, and perhaps we can hope to see some peace in this region--for the first time in decades.", objectives = "Defeat 12 Dark Horde troops and 3 Dark Horde Sergeants.", completion = "You killed many of them, but I watched even more run away. \n\nLet's hope they never return." }
WordHunterWoW_QuestEN[86831] = { title = "Warriors Without a Warlord", description = "Despite our work in the area, the Dark Horde continues to battle. Their leader is there, in Blackrock Stronghold, likely bolstering their spirits. \n\nTake them out. Once we do, I suspect this Dark Horde will come to nothing, with much less bloodshed.\n\nAnd Faol thinks there may be a fragment of the relic he's looking for in there. Recover that as well!", objectives = "Enter Blackrock Stronghold and take out the leader of the Dark Horde.", progress = "Have you taken them out?", completion = "Excellent, <name>! I believe this will save many lives across the region. With no warlord to rally them, the Dark Horde should fall apart." }
WordHunterWoW_QuestEN[86832] = { title = "A Worthy Forge", description = "Thank you for all your help, {name}. It's strange to hold what remains of my father's shield and know that, prior to that day, he was such a defender of others.\n\nI feel I've only seen his aggressive side. I realize he means well, but I don't think...\n\nThat is not the path for me.\n\nRegardless, let's return to Silvermoon and get these fragments we've gathered to a worthy forge.", objectives = "Return to Silvermoon.", completion = "We certainly did some good in the Burning Steppes, <name>, and recovered the fragments of Turalyon's shield.\n\nArator seems excited to see it reforged." }
WordHunterWoW_QuestEN[86833] = { title = "A Bulwark Remade", description = "{name}, it is time to see what we can do with these fragments of Turalyon's shield.\n\nWhile it did break, it was exceptionally powerful in its day, and it could be a great help to Turalyon against the Void.\n\nPerhaps a moment of healing and letting go, as well.", objectives = "Help Arator reforge his father's shield.", progress = "Thank you for helping me with this, <name>.", completion = "<name>, that did not go as I hoped, to say the least.\n\nI'd hoped he would be able to see... to accept that he could still change.\n\nBut it doesn't look like he's open to that--at least, not now." }
WordHunterWoW_QuestEN[86834] = { title = "Voidborn Banishing", description = "The Devouring Host are composed of horrors from the depths of the Void, but they are still an army, with soldiers and leaders. Amongst that sea of void walkers, I notice there are singular creatures.\n\nWhether commander or mascot to the Host, removing them from the battlefield will help to break their lines.", objectives = "Slay Latrunculon, Blightclaw, and The Wasting.", completion = "Going behind our lines was reckless! Was this Arator's idea? He has been so headstrong lately.\n\nSorry, <name>. I shouldn't air this family business. I will admit that your actions have aided the Vanguard of Light in this battle." }
WordHunterWoW_QuestEN[86835] = { title = "Regroup!", description = "We've stabilized most of the city and saved as many as we could, but our job isn't over.\n\nLocus-Walker must still be out there looking for the enemy commander. We've already searched over most of the city, so he must be in the one place we've not yet looked.\n\nCome, {name}. Meet me at Myza's Oasis.", objectives = "Locate Locus-Walker within Tazavesh.", completion = "I found our quarry, but unfortunately not before they broke into this shelter." }
WordHunterWoW_QuestEN[86836] = { title = "The Hunter Awaits", description = "I have warned Orweyna of the dangers and madness that lay within the Rift of Aln, but she believes it is her only path forward. I envy her faith.\n\nSomeone can help show her the way: the Shul'ka. The Hunters of Shadows. They have sacrificed everything to protect the haranir from the effects of the rift.\n\nI will let one know that you need help. You will find him in the Vale of Mists.", objectives = "Find Orweyna and the Shul'ka in the Vale of Mists.", completion = "I have given up my connection to the goddess to protect my people from the dangers of the Rift of Aln. I do not believe anyone should ever go there without knowing what you risk. Haranir will succumb and die without protection." }
WordHunterWoW_QuestEN[86837] = { title = "Meet at the Sunwell", description = "I have been tasked with bolstering the Vanguard of Light that empower the Sunwell. I need your help, though not just for that simple task.\n\nOur mutual friend, Arator, is... stuck. Stuck in his grief and anger over that tragic conflict between him and his father.\n\nI'm just an old priest that's been raised from the dead, but I've found that a quest is just the thing to set a young paladin back on the right path.\n\nWould you help?", objectives = "Ask Arator to meet Faol at the Sunwell.", completion = "Nnnghhh... It is so painfully bright here, don't you think? \n\nAhh, you were able to convince him. Thank you." }
WordHunterWoW_QuestEN[86838] = { title = "Renewal for the Weary", description = "The Vanguard of Light are maintaining a difficult ritual at the Sunwell. It requires focus, discipline, and is quite exhausting.\n\nTake my staff. I've had it since I was Archbishop in Stormwind. It is meaningful to me and my faith. The Light responds to meaning and intention. It should renew the Vanguard's spirits so they can maintain the ritual a while longer.\n\nI can't approach any closer to the Sunwell, so you will have to do this for me.", objectives = "Restore the Light to 10 weary channelers.", completion = "I had hoped that seeing the rest of the Vanguard focused on the Sunwell, it would give him a goal that was bigger than his pain and lead him away from his anger. Instead, he belittles my solution.\n\nThank you, <name>, for doing it in his stead. It was necessary to keep the Voidstorm at bay." }
WordHunterWoW_QuestEN[86839] = { title = "Relics of Light's Hope", description = "The holy power in my staff has been spent. Forty years of fervent prayers drained away in a few minutes. It was for a good cause, and my staff will recover in time.\n\nThere are other relics, like my staff, that were important to paladins and priests. Light's Hope Chapel has many such relics stored there.\n\nArator trained there as well. Perhaps the solution to his pain could also be found within.", objectives = "Meet Lord Maxwell Tyrosus at Light's Hope Chapel.", completion = "Welcome to Light's Hope, <name>. \n\nMost of the paladins that defended these grounds were called by the Light. I've had to reach out to the Ebon Blade for support, or the Scourge would have overrun this holy place." }
WordHunterWoW_QuestEN[86840] = { title = "Flickering Hope", description = "Normally, {name}, paladins from Light's Hope hold back the Scourge in the immediate area around the chapel, but they've all been called to fight the Void.\n\nAs a result, Scourge forces have greatly increased their numbers around the chapel. We've managed to hold the line so far, but only with the help of Darion and the Ebon Blade.\n\nGive us some room to breathe--defeat as many of them as you can.", objectives = "Kill Scourge forces around Light's Hope Chapel.", progress = "We can't hold back the undead forever, <name>.", completion = "Thank you, <name>. You've thinned their ranks enough that we'll be able to maintain the defenses, with the help we have from our... allies.\n\nNow, Faol has told me about your need for relics." }
WordHunterWoW_QuestEN[86841] = { title = "Relics of Paladins Past", description = "Alonsus tells me you're looking for relics of holy power, to sustain those performing the ritual holding the Void at bay.\n\nNow that you've beaten back the Scourge, you and Arator are certainly welcome to enter the Sanctum of Light and use what we have for the cause.", objectives = "Gather 5 relics from the Sanctum of Light.", progress = "Countless great heroes are interred under the chapel, <name>. \n\nHopefully their relics can be of aid to those at the Sunwell.", completion = "I trust you found what you needed, <name>?" }
WordHunterWoW_QuestEN[86842] = { title = "Scarlet Power", description = "These artifacts will help sustain the Vanguard, but they are not enough. I know of a place nearby that would have the rest we need, but... given Arator's state of mind, I'm hesitant to go there.\n\nHmph... No sense in avoiding it. We must all face up to the fact that the Scarlet Crusade calls upon the power of the Light, and has for decades.", objectives = "Meet Alonsus Faol at Scarlet Monastery.", progress = "When it comes to reclaiming relics of the Light from the Scarlet Crusade, there's no better time than now, <name>.", completion = "Here we are. Let's deal with these Scarlets." }
WordHunterWoW_QuestEN[86843] = { title = "Light Miswielded", description = "The Scarlet Crusade has been wielding the Light for its evil purposes for decades, {name}. I'm disappointed to see how many forces they still have here.\n\nStill, the Light responds to them, just as it does to us.\n\nWe're here to get their relics to help the Sunwell, but while we're here, let's cleanse this place of their dark influence.", objectives = "Defeat Scarlet Crusade members.", progress = "Have you dealt with the Scarlet threat, <name>?", completion = "Excellent work.\n\nPerhaps one day, the Scarlet Monastery can be a place that truly serves the Light, but for now our time is limited and our focus must remain on the Sunwell." }
WordHunterWoW_QuestEN[86844] = { title = "Light Repurposed", description = "Leaders of the Crusade have channeled the Light through their weapons every day for years. \n\nWhile their goals and actions are reprehensible to us, their weapons are no less useful than my own staff, especially in such a time of need.\n\nAs you go through the Scarlet Halls, whenever you find a leader, defeat them and bring back their weapon. We will put it to a righteous use: to aid the Sunwell.", objectives = "Recover Meyer's Rod of Castigation, Aelyse's Gleaming Falchion, and Benthar's Scarlet Spire.", progress = "What artifacts have you found here, <name>?", completion = "These weapons of the Light shall serve a much greater purpose from this day forward.\n\nI hope that may be true as well for Aelyse--the Scarlet champion Arator showed mercy to.\n\nI told her to begin by surrendering herself to Calia Menethil at the Sunwell." }
WordHunterWoW_QuestEN[86845] = { title = "The Sunwalker Path", description = "I think I have failed Arator. In my attempt to steady him after the incident with his father, I may have shattered his faith with uncomfortable truths of the Light.\n\nI would like to consult with the wisest person I know, Sunwalker Dezco. I did not see him with the Vanguard. Tyrosus told me he may be in Hammerfall providing aid to the displaced.", objectives = "Meet with Sunwalker Dezco in Hammerfall.", completion = "An'she has guided you to us, <name>. Care to join us in our work?" }
WordHunterWoW_QuestEN[86846] = { title = "Resupplying Our Suppliers", description = "{name}, the people of Hammerfall were attacked not so long ago by saboteurs from a group called the Red Dawn.\n\nI am working to help them recover and rebuild from the attack with my fellow Sunwalkers: Malu and Nadura.\n\nOne thing they have been doing is gathering supplies needed by Hammerfall's crafters from various sources.\n\nIf you could deliver these supplies, it would be a great help.", objectives = "Aid the people of Hammerfall in their recovery.", progress = "Have you distributed the supplies, <name>?", completion = "Excellent! This will help the people of Hammerfall help themselves." }
WordHunterWoW_QuestEN[86848] = { title = "Light's Arsenal", description = "The armory here stores legendary weapons and artifacts, blessed with the power of the Light due to their proximity to the Sunwell.\n\nWhile we are pinned down by the Host, the ethereals are looting these treasures.\n\n{name}, secure these holy artifacts. They are our best weapons against the Void. Use them to cut down these invaders if you have the need.", objectives = "Collect 7 Legendary Weapons.", progress = "Have you secured our artifacts?", completion = "Were they just here to loot us? Or did they have some reason to seek out weapons of the Light? \n\nI'll save that speculation for later. The Vanguard can use these weapons now. With them, we will push this Devouring Host off Quel'Danas!" }
WordHunterWoW_QuestEN[86849] = { title = "Wrath Unleashed", description = "{name}, the time has come! We push these fiends to Sun's Reach Harbor! We drive them back into their accursed void portal and drive them from these sacred shores!\n\nFor the Light! For Azeroth!", objectives = "Join the charge of the Vanguard of Light.", progress = "Don't stop until we drive them from these shores!", completion = "By the Light! We cannot win this battle. Our only hope lies in the Sunwell!" }
WordHunterWoW_QuestEN[86850] = { title = "Broken Sun", description = "We need to fall back! This is not a battle that we can win. Not like this.\n\nBut there is still hope! The Sunwell. It brought the Vanguard of Light here to defend it. It brought you, {name}. Fall back to the Sunwell chamber and defend it for as long as we can.\n\nI have faith the Light did not intend for us to lose this day.", objectives = "Meet Liadrin at the entrance to the Sunwell.", completion = "Thank the Light. Everyone from the Vanguard that survived is in the Sunwell chamber. Now that you are here, we can begin." }
WordHunterWoW_QuestEN[86851] = { title = "The Foundation of Aln", description = "The presence of the goddess reverberates through everything in the Rift of Aln. The voice is too powerful for haranir to resist. In mere minutes, one of our flock would be lost forever.\n\nThere are, however, ways to protect oneself for a short time. Kill the rejects that crawl up from the rift and gather the Alndust from which they are created. I can show Orweyna how to craft a short-term solution for entering the rift.", objectives = "Collect 6 alndust from Rift creatures in the Vale of Mists.", progress = "I will let your young companion know what to do with the Alndust.", completion = "My hands tingle where the Alndust touches. A curious feeling... not unwelcome.\n\nThe honored Shul'ka told me how to manipulate the Alndust to protect haranir in the rift. It seemed difficult, but with its magic swelling in me, I feel that it should be doable." }
WordHunterWoW_QuestEN[86852] = { title = "Light's Last Stand", description = "Our attempts to fight Xal'atath's Devouring Host have failed. Our only hope is to call upon the Light once more and trust that there was a reason it brought this Vanguard together. \n\n{name}, you and Arator need to protect the Sunwell from the Devouring Host. With so few of us left, we cannot spare any more defenders.\n\nOur faith in the Light will save us.", objectives = "Defend the Sunwell from the attacking forces.", completion = "May the Light bless and protect you, <name>. Your defense of the Sunwell chamber made this miracle possible.\n\nWe have not beaten Xal'atath, but we have forestalled the invasion of her Devouring Host. We now have the time to catch our breath and discover what we must do to defeat her." }
WordHunterWoW_QuestEN[86853] = { title = "Sparks of War: Undermine", description = "Investigate the Undermine! Reports are coming in about a growing conflict in the area, go and check it out.", objectives = "Collect 100 Sparks of War in Undermine, while in War Mode.", progress = "Go off and complete your investigation.", completion = "YOU SURVIVED? And with all your limbs no less. Well done." }
WordHunterWoW_QuestEN[86855] = { title = "Consequences of Our Duty", description = "You must see with your own eyes the effects that the Rift of Aln can have on any haranir. Even those who stand guard over the border are oft affected by its call.\n\nTake this. I use it as an emergency salve to help those who are stricken of the dangers of Aln. Patrol these lands and give aid to those who need it. Perhaps then you will understand the gravity of what you seek to do.", objectives = "Heal 5 Wounded Guardians in the Vale of Mists.", progress = "I did not know that these castoffs from the rift could affect us so much...", completion = "It is sobering to see the effects of the rift on my peoples. But Amarakk's interference has given me unintended hope.\n\nI must go into the rift to search for Hagar's answer, and with the Shul'ka's help, I may even survive this ordeal." }
WordHunterWoW_QuestEN[86856] = { title = "Dampening the Call", description = "Amarakk told me how to prepare Alndust to create the salve. In small doses, Alndust can strengthen the mind against madness and terror. It offers clarity and peace, but only if expertly employed.\n\nI could use your help to set an anchor to this place, {name}. The ritual is delicate, and failure could be disastrous.", objectives = "Help Orweyna create the Alndust Filter at the Vale of Mists.", progress = "The process sounded simple enough--well within my abilities. But I appreciate your presence here to ground me.", completion = "I cannot hear the voice of the goddess.\n\nI hate it.\n\nHow does Amarakk live like this?" }
WordHunterWoW_QuestEN[86857] = { title = "Descent into the Rift", description = "With this, I will be able to venture down into the Rift of Aln. I will not have long, so we should not dawdle.\n\nLet us find Amarakk and gain his help.", objectives = "Find the Wards of the Shul'ka in the Rift of Aln to find Amarakk.", completion = "That manifestation is one of the purest forms of Aln madness that resides here. My ward will distract it only for so long. We must move quickly." }
WordHunterWoW_QuestEN[86858] = { title = "The Madness Roots Deep", description = "I found you while I was in the middle of one of my duties. Someone has spent too long within the rift and has fallen prey to the call of the goddess. I must rescue him and send him back to where he belongs.\n\nHelp me with this task, and I will help you.", objectives = "Defeat On'hiea in the Rift of Aln.", progress = "We can save him!", completion = "Another soul saved.\n\nThis is why I do this, <name>. All my sacrifices, shutting myself from the voice of the goddess, is worth it for each soul I rescue from the grasp of the rift." }
WordHunterWoW_QuestEN[86859] = { title = "Grinding Out a Solution", description = "I have been pondering what Hagar could have meant from the moment Orweyna mentioned an answer to your problems. There are no mystical fountains--no weapons. Everything in the rift is created from the same source: Alndust, the distillation of the influence of the goddess. If we hunt a large manifestation, you will have the power of creation in its purest form.\n\nWe cannot defeat it without help. Search the rift and look for fungi large enough to cultivate. I can use them to give us an edge.", objectives = "Find 5 Alngrown Fungus in the Rift of Aln.", progress = "Any advantage that we can have against the manifestation will give us a better chance to survive.", completion = "We might have a chance with this. I'll be able to coat my weapons with this and craft a powerful poison." }
WordHunterWoW_QuestEN[86860] = { title = "Before They Grow", description = "Within every creature that roams the Rift of Aln thrums a gathering of the foundation of the goddess's influence. This Alndust yearns to merge with others of its ilk. Part of my duties as the Shul'ka is to make sure to keep the number of large manifestations low so they do not overwhelm the Den.\n\nIt is easiest to do that while they are small.\n\nTake this spear. You may use it to shatter the smaller creatures down to... trivial sizes.", objectives = "Use Amarakk's Influence to defeat Aln Mites and creatures in the Rift of Aln.", completion = "Well done." }
WordHunterWoW_QuestEN[86861] = { title = "Herding Manifestations", description = "We are preparing to fight a giant manifestation. Let me emphasize this again. We must fight just one.\n\nIf we fight two at a time, we would have no chance of survival. Place these wards around the rift to draw the others away. They will not last long... but we will need every advantage we can gain.", objectives = "Place 3 Wards around the Rift of Aln.", progress = "These wars are a creation of my own making. They attack the larger creatures toward them by mimicking their reaction to food.", completion = "That must be enough." }
WordHunterWoW_QuestEN[86862] = { title = "The Greater They Aln", description = "We have one chance at this only.\n\nI pray we have prepared enough.", objectives = "Defeat the Aln Manifestation and gather its components in the Rift of Aln.", progress = "The power of the Rift of Aln is beyond mortal comprehension. What we are doing is simply borrowing some of it for a brief moment.", completion = "I thought I would never see this with my own eyes... and yet here we are.\n\nMake this worth it." }
WordHunterWoW_QuestEN[86864] = { title = "Watch the Den", description = "Finally, we have a moment to breathe. This is where we feel closest to the goddess--we are below the Cradle where she used to rest.\n\nThe elders will not allow us to use any of the Alndust they have gathered over the centuries. They see only what the goddess asked of us before, not what her world needs now.\n\nAlndust is rare, but there are ways to get it. Ask around. I will check... elsewhere.", objectives = "Speak to the Innkeeper, Renown Quartermaster, and the Flight Master at the Den.", progress = "I hope that you will be able to rest here. You must know how to navigate this place.", completion = "In the end, we must figure this out for ourselves." }
WordHunterWoW_QuestEN[86865] = { title = "In Search of the Problem", description = "We did what Hagar asked us to do. The next step will be to test this on something--or someone--afflicted with the Lightbloom.\n\nIt may be difficult to find the Lightbloom in enough quantities in Harandar, but I believe we will find what we need at Har'alnor. I will meet you there!", objectives = "Meet Orweyna at Har'alnor.", completion = "We have left our homes. We will return." }
WordHunterWoW_QuestEN[86866] = { title = "Can We Heal This?", description = "The rutaani have escaped their nearby villages to Har'alnor. The guards have told me that some of them have been afflicted with the Lightbloom, yet have not succumbed to its effects.\n\nThis may be our best opportunity to test the Alndust's powers. Time is of the essence!", objectives = "Use the Greater Alndust on the Afflicted Rutaani at Har'alnor.", progress = "This is it, <name>. The moment of truth. Do we have an answer for the problems on Azeroth?", completion = "The Alndust may not be able to recover someone who has fully fallen to the Lightbloom, but it should be able to inoculate those from further corruption. That must be enough." }
WordHunterWoW_QuestEN[86867] = { title = "Into the Lightbloom", description = "We've gathered the haranir we have available and distributed the Alndust. We have everything we need, but they need to be able to safely enter the area. Scouts have told us that the creatures spreading the Lightbloom are protected by a shield. We must stop them. We will also need to thin their numbers.\n\nGet on the petalwing, {name}, and let's clear the way.", objectives = "Ride on the Petalwing, destroy the shields protecting 4 Lightbloom Spreaders, and defeat Lightbloom creatures in the Blinding Bloom.", progress = "We ride together!", completion = "Now we can begin." }
WordHunterWoW_QuestEN[86868] = { title = "Goodwill Tour", description = "The situation here is far worse than I imagined.\n\nThe Twilight's Blade and their leader, Mor'duun, have completely overrun this city.\n\nWe will use this opportunity to show the Amani how efficient we are at eliminating forces of the Void. Perhaps that will help convince them to stall hostilities between our people... at least until the current threat has passed.", objectives = "Kill 10 Invading Shadows while traveling deeper into the city of Atal'Aman.", completion = "Zul'jarra has noticed your prowess in battle.\n\nGood.\n\nLet us continue demonstrating our usefulness. If they push us out of their lands now, we'll have no way to keep an eye on the Twilight's Blade until they're flooding through the gates into Eversong." }
WordHunterWoW_QuestEN[86869] = { title = "Phase Diving: Shan'dorah Saboteurs", description = "", objectives = "" }
WordHunterWoW_QuestEN[86872] = { title = "Phase Diving: Experimental Extermination", description = "", objectives = "" }
WordHunterWoW_QuestEN[86874] = { title = "Culling the Light", description = "", objectives = "" }
WordHunterWoW_QuestEN[86877] = { title = "Righteous Pruning", description = "This is a threat that could destroy all of Harandar if left unchecked. That's why we will pull this out at the root.\n\nThe ruutani who did not have the time to escape this place must be fully corrupted by now. Unfortunate, but it makes our plan of attack simple. Their leaders must be spreading the Lightbloom. We must strike them down.", objectives = "Kill 4 Lightblinded Sap Weavers in the Blinding Bloom.", progress = "If these leaders are allowed to thrive, they will gather more forces to the Lightbloom. We can't allow that to happen.", completion = "I wish we could save everyone, but...\n\nA gruesome but necessary task." }
WordHunterWoW_QuestEN[86880] = { title = "Our Beloved, Returned", description = "The haranir had a presence by the roots of Shaladrassil, as a sign of goodwill with the cultures that live within our home. When the guards retreated, they left some of our treasured mementos and artifacts.\n\nSince the spread of the Lightbloom has been greater than I ever expected, I do not know when we'll be able to come back. Let's find those artifacts in the Blinding Bloom and bring them home.", objectives = "Recover 6 Haranir Artifacts in the Blinding Bloom.", progress = "It would be good to bring some of these items back in our hands.", completion = "These artifacts pale in importance to the lives of those involved here... but it is good to have them back." }
WordHunterWoW_QuestEN[86881] = { title = "At the Root", description = "The growths that help them spread the Lightbloom so quickly should be vulnerable after your attack from the air, but we still need to destroy them. Return to the Blinding Bloom and uproot the spreaders before they can recover from our attack.", objectives = "Destroy the Lightbloom Spreaders in the Blinding Bloom.", progress = "We need to stop the spread of the Lightbloom, lest it take over all of Harandar.", completion = "I pray this will help us all." }
WordHunterWoW_QuestEN[86882] = { title = "Alndust in Right Hands", description = "We can now go to the roots of Shaladrassil and stop the Lightbloom spreading even further into Harandar.\n\nWe have enough Alndust to inoculate any haranir who are willing to risk their lives to follow us into battle. Find them, {name}, and give them the Alndust.", objectives = "Give Alndust to 5 haranir around Har'alnor and the Blinding Bloom.", progress = "I know that my people are ready to step up to the challenge.", completion = "This is so much more than what the Rootwarden said. How has the Lightbloom spread so much, and so quickly?" }
WordHunterWoW_QuestEN[86883] = { title = "The Frenzied March", description = "Halduron's news is dire. If the Lightbloom is frenzying on the surface, then the danger has grown far more quickly than we were prepared to reckon with.\n\nWe must make for Eversong at once. I will stand against any threat to Aln'hara's creation, be it here or in the world above... and I will do it alone, if I must.", objectives = "Return to Eversong Forest.", completion = "To think that while we toiled below, the Lightbloom would spread so aggressively in Eversong.\n\nDamn it all! Every victory we win reveals rising danger." }
WordHunterWoW_QuestEN[86884] = { title = "Cull and Burn", description = "Simply culling these creatures is not sufficient. If their bodies are left unattended, the Light will seep from their remains and spread through the soil to the surrounding foliage.\n\nWe must take more drastic measures. Gather the bones of the creatures you slay. If we burn them, perhaps we can prevent their further spread through the roots of this forest.", objectives = "Collect 10 Corrupted Bones from Lightbloom-Infested wildlife.", progress = "Do not delay. The longer we wait to cull this growth, the more of this forest the sin'dorei will lose.", completion = "It is a shame to see something born of Harandar wreaking such havoc on a place like this. These roots may not cradle Aln'hara, but they grow toward her all the same." }
WordHunterWoW_QuestEN[86885] = { title = "Stem the Tides", description = "When the Farstriders first discovered the Lightbloom, we thought it to be merely an aesthetic change--a small quirk of the Sunwell's influence. Would that we knew then what we know now.\n\nThese Light-frenzied rootways must lead all the way back to Harandar. If we don't close them, it won't matter how many of these damned things I bring down. Close the rootways and we might have a fighting chance.", objectives = "Burn 5 Lightfrenzy Portalways.", progress = "What are you waiting for? Every moment that passes, more of those things filter through. Our odds are scant enough as it is.", completion = "Damn it all. For every rootway you torch, two more crop up elsewhere. It's like they're self-perpetuating, spreading in the span of moments.\n\nI don't think we can solve this with arrows and magic, even with Orweyna's help. We don't have enough Alndust, nor enough haranir to prevent the spread of this frenzy." }
WordHunterWoW_QuestEN[86887] = { title = "Expeditious Retreat", description = "I have a way to stop the Lightbloom from spreading further through the forest, but it isn't exactly a delicate touch. Normally, I'd never dream of resorting to a controlled burn in such a healthy portion of Eversong... but the frenzy is spreading too quickly, and we are running out of options.\n\nI've sounded the retreat to my Farstriders, but some of them haven't responded. I need you to find any rangers in particularly sticky situations, and lend your aid in securing their escape.", objectives = "Rescue 3 Beleaguered Farstriders.", progress = "We're short on time, <name>. I can't execute my plan if we have Farstriders still in the field.", completion = "Most of the Farstriders have retreated to our position. Those that remain are prepared to slip away once the ritual begins.\n\nWe're out of time. It's now or never." }
WordHunterWoW_QuestEN[86890] = { title = "Tell the People What You Have Seen", description = "We may have stemmed the malignant growth, but we have so many more questions than answers. How did this happen? How did this grow so much? How did Ruia not understand the extent of the calamity?\n\n{name}, we must return to the Cradle immediately. The elders must know what happened today.", objectives = "Return to the Den to speak to the Elders.", progress = "I only pray that they are more receptive to the truth this time around.", completion = "Azeroth needs our help. I will not stand idly by while she is overwhelmed.\n\nI know you will not, either." }
WordHunterWoW_QuestEN[86891] = { title = "A Last Resort", description = "With our ground forces pulled back, our position will be overwhelmed in a matter of minutes. It's time to execute our gambit.\n\nRommath and the Magisters have provided us a mana gem that can be used to overload Lash'ra's runestones. Take it, and infuse the stones with the mana contained therein. That will set the stage for the Magisters' ritual: to detonate the runestones and burn the entirety of Lash'ra to the ground.\n\nWe just have to hope the Lightbloom cannot survive in an inferno.", objectives = "Overload 3 Phoenixfire Runestones.", completion = "We've done all we can.\n\nNow all that's left is to defend the Magisters, and hope that this is enough to stop the frenzy from spreading any farther." }
WordHunterWoW_QuestEN[86892] = { title = "Survive", description = "Our retreat to safer ground has not gone unnoticed. The rutaani mark us at every turn, and now they mean to cross the river.\n\nWe have to buy Rommath and the Magisters as much time as we can. If we fail here, the whole of Eversong could be lost.\n\nStand tall. Do not falter. And do your best not to die.", objectives = "Survive the Lightbloom onslaught.", progress = "We do not know when the frenzy will push past the lakeshore and encroach upon our position. Better to have Rommath start the ritual sooner rather than later.", completion = "I... I cannot believe it. My kin on the surface, standing shoulder to shoulder with surface-dwellers, and wielding the magics of Aln...\n\n<Orweyna sets her jaw and flashes you a smile.>\n\nBut we do not have time for sentiment. We must bring Ruia to justice, and end this frenzy." }
WordHunterWoW_QuestEN[86894] = { title = "The Gift of Aln'hara", description = "Ruia has always been a zealous advocate, but this behavior is beyond the pale. The Lightbloom must be affecting him, driving him to these dangerous lengths.\n\nBut we do not have to be like him. This forest need not fall to the bloom like Shaladrassil's roots did.\n\nThe Hara'ti brought enough Alndust to bolster our allies against corruption, and prevent the frenzy from spreading further. Together, you and I shall spread Aln'hara's gift across the forest. This frenzy shall advance no further.", objectives = "Use the Alndust to combat the Lightbloom frenzy in Lightbloom Lash'ra.", completion = "The haranir are always mighty. But with the goddess's gift shining upon us, we are unstoppable." }
WordHunterWoW_QuestEN[86896] = { title = "Light Finds a Way", description = "I am an expert in the fauna of Eversong, and I can say with certainty that the vast majority of the wildlife here tend to be of fairly average size.\n\nBut these Light-frenzied saptors are decidedly, unequivocally not. One bite from those thorny jaws could claim the lives of half a dozen Farstriders, if they are caught unawares.\n\nMy rangers have their quivers full culling the chaff alongside the haranir. See to it that those towering tyrannosaptors don't catch them unawares.", objectives = "Slay 3 Lightfrenzy Tyrannosaptors in Lightbloom Lash'ra.", completion = "Between you and our new haranir allies, my rangers have plenty of ferocious examples to follow. I'll have to consider teaching some of your techniques at the Retreat." }
WordHunterWoW_QuestEN[86897] = { title = "Quelling the Frenzy", description = "The day is nearly won. The sin'dorei cull every new sprout that blooms, and the Hara'ti ward the surrounding wilds against the frenzy's influence. All that yet remains is to remove this lightbound serpent's misguided head.\n\nRootwarden Ruia has opposed our every action and shouted down our every word. But he is still a Rootwarden, and one with the power of a frenzying Lightbloom host at his beck and call.\n\nHe is strong. But he does not walk with Aln'hara.\n\nIt is time to end this.", objectives = "Confront Lightwarden Ruia.", completion = "It is over. Though the Lightbloom may never fully recede, its mastermind has been driven back into the rootway. With the frenzy quelled, and the surrounding forests warded against its advance, we can rest assured that Eversong will not suffer the Lightbloom's spread any longer.\n\nWe've done it. We've won!" }
WordHunterWoW_QuestEN[86898] = { title = "Rise of the Haranir", description = "It is done. The frenzy is routed, the Rootwarden has fled, and the sin'dorei have reclaimed control of their forests.\n\nI can scarcely believe it, but... we succeeded, {name}. By Aln'hara's grace, we found a path forward.\n\nNow Halduron's people invite us to their den. I am not fond of your surface-cities, but...\n\nYou have aided me so many times, my friend. It is time that the Hara'ti reached out hands of our own.", objectives = "Meet Orweyna and Halduron in the Gardens of Remembrance in Silvermoon City.", completion = "For the first time in generations, the haranir walk upon the surface of Aln'hara's creation. Time will tell how her creation receives us in turn.\n\nThe fighting is far from over. The Void claws at your gates and threatens your people. But know this, my friend: from this day forward, any threat that encroaches upon Aln'hara's bounty will have the Hara'ti to contend with, be it here or deep below the earth." }
WordHunterWoW_QuestEN[86899] = { title = "The Root Cause", description = "The rutaani who attacked Silvermoon come from my homeland, Harandar. This Lightbloom infection is new, however.\n\nThe time has come for me to return to my people. I will face their judgement, and explain my actions.\n\nIf the Lightbloom has spread, I must warn my people of the danger. If you're willing to join me, I will take you and your insistent friend through the rootways to Harandar.\n\nLet me know when you are ready to go.", objectives = "Take the portal and meet Orweyna in Harandar.", completion = "You made it. For a moment I wasn't sure you would. Don't worry--that nauseous feeling will pass.\n\nWe stand in the deep roots of Amirdrassil. My home lies beyond.\n\nLet us see what welcome awaits." }
WordHunterWoW_QuestEN[86900] = { title = "To Har'athir", description = "All of the world's roots grow toward our homeland. The ones above you are mighty, but new--born of a fledgling World Tree you call Amirdrassil.\n\nAs far as World Trees go, it is a strange one. But its nature matters less than its reach. Any roots that seek to protect our world from harm are worth protecting.\n\nLet us follow the road down to Har'athir and check in with the Rootwarden. We will ask if he's noticed signs of Lightbloom yet.", objectives = "Follow Orweyna into Harandar.", completion = "Outsiders are not permitted in Harandar. Orweyna has broken our most sacred of laws.\n\nYou are not welcome here, stranger." }
WordHunterWoW_QuestEN[86901] = { title = "The Rift and the Den", description = "As I suspected, the elders are quite upset with my actions. Now that I have seen the children and Ku'paal to safety, I am ready to face the Council.\n\nI will do what I can to make them see that the Lightbloom is a threat, and to enable your ability to move freely through Harandar.\n\nPetalvane will carry you safely to the Den. Let us make haste.", objectives = "Ride Petalvane to the Den.", completion = "Tread carefully, <name>. The haranir are formidable and on edge over our arrival.\n\nThe Council has convened and is ready to hear Orweyna's words. Hopefully she will be able to convince them that the Lightbloom is a threat and that their help is needed." }
WordHunterWoW_QuestEN[86902] = { title = "Relinquishing Relics", description = "My staff bought us time in the effort to hold back the Void, but these relics will be a more powerful aid. Let us hope it will be enough.\n\nQuickly, deliver these relics to our friends.", objectives = "Distribute relics to Taelia, Valunei, Salandria, and Mehlar.", progress = "Did you get those relics out to everyone, <name>?", completion = "With those relics, they should be able to sustain the ritual for much longer.\n\nAnd we can attend to other matters." }
WordHunterWoW_QuestEN[86903] = { title = "The Arcantina", description = "{name}, there's a place that we used during the Second War, when we missed our homes an' needed to remember Azeroth. Somethin' of a retreat an' a sanctuary for those who've seen too much fighting--too much pain.\n\nOver time, we've brought friends and allies there. In recent years, members o' the Horde have been invited as well. We call it the Arcantina.\n\nI believe Arator, and you, would benefit from some respite there. Use this key to make a portal.", objectives = "Visit the Arcantina.", progress = "This really is quite the place, isn't it, <name>?", completion = "This has been a journey, <name>.\n\nI've learned a lot from Alonsus, and the Sons of Lothar...\n\nAnd perhaps most of all, what kind of paladin my father used to be, and what sort I'll be from now on." }
WordHunterWoW_QuestEN[86905] = { title = "No More Sick Days", description = "When we started clearin' out this forest we expected some trouble from the local wildlife but we never expected to be set upon by diseased animals! My work crew keeps gettin' sick and takin' time off to recover. Obviously this is messin' with our bottom line, so perhaps you could clear out some of the creatures so we can start work again?\n\nWhen you're done see my assistant for payment.", objectives = "Clear out 8 diseased creatures." }
WordHunterWoW_QuestEN[86907] = { title = "The Den of Echoes", description = "Greetings, stranger. I am Elder Hagar. You have been granted permission to stay, as long as you pass through the trials of the Den of Echoes. \n\nAln'hara will determine your fate, and you will learn about our people and customs.\n\nLet us meet at the caves.", objectives = "Meet Hagar at the Den of Echoes.", completion = "Welcome to the Den of Echoes. Within the caves beyond, you will find ancient paintings which tell the story of the haranir.\n\nPerhaps you will learn something, if you survive. May Aln'hara be on your side." }
WordHunterWoW_QuestEN[86909] = { title = "Unrestful Spirits", description = "", objectives = "" }
WordHunterWoW_QuestEN[86910] = { title = "Koozat's Trample", description = "Koozat is usually very docile. This isn't like him at all. Please, find out what happened.", objectives = "Follow Orweyna.", progress = "Koozat is not usually a violent creature.", completion = "Koozat is the least of our troubles right now. The Lightbloom has arrived. Har'mara is under attack!" }
WordHunterWoW_QuestEN[86911] = { title = "Echoes and Memories", description = "The history of the haranir has been recorded for tens of thousands of years in the caves within. The memories of our people are painted on the stone, that we might never forget where we came from and what our purpose is.\n\nYou are the first outsiders to ever witness the Den of Echoes. When you touch the paintings, our ancestors will share our stories and struggles.\n\nZur'ashar Kassameh awaits you within. He will guide you and Halduron on your journeys. I wish you luck.", objectives = "Complete the first vision of the Den of Echoes.", progress = "Our people have been here for tens of thousands of years, but it was not always so. Once, we lived on the surface as you do.", completion = "You have made it through the first of the trials, but the real test is yet to come." }
WordHunterWoW_QuestEN[86912] = { title = "Down the Rootways", description = "You have gained a glimpse into our history. There is one trial yet remaining.\n\nIf you survive, the goddess's blessing will be upon you, and the Council will not be able to deny your presence here.\n\nDescend now into the earth and follow in our ancestors' footsteps.", objectives = "Complete the Gulf of Memories delve and obtain the Fragment of Revelation from its treasure room.", progress = "You have survived the Gulf of Memories. Welcome to Har'mara, friend.", completion = "You awaken. Good. Now that you have seen our past, I have brought you to my home, to see my hope for the future.\n\nHere in Har'mara, we live in harmony with two of the local peoples: the rutaani, and the fungarians. It is my dream that this partnership will spread to the rest of Harandar.\n\nYou should get to know them as well, and see the peace that we have created together." }
WordHunterWoW_QuestEN[86913] = { title = "A Hut in Har'mara", description = "The others have gathered downstairs. Come. Orweyna is eager to see that you are in one piece.", objectives = "Meet Orweyna in Har'mara.", completion = "Welcome to Har'mara. I am glad to see you well and whole after the trials.\n\nThis village is the home of Hagar and many others who call Harandar their home." }
WordHunterWoW_QuestEN[86914] = { title = "Tending to Har'mara", description = "Har'mara has long been a refuge for those who have removed themselves from the conflicts that often arise between the rutaani and the fungarians. \n\nHere, they learn how to live with one another. They work, play, and live together--balanced.\n\nYou have learned much about the past of the haranir, including our deepest shame. Now you will see our current work: harmony.", objectives = "Complete tasks in Har'mara.", progress = "It is the natural state of the fungarians and the rutaani to spread themselves out. At times, this can lead to overgrowth and the crowding out of other species.\n\nMaintaining that balance is important, and is the duty the haranir fulfill as stewards of Harandar.", completion = "Sometimes harmony and friendship are helped by small acts of service.\n\nI hope that the rutaani and fungarians here have come to see you as an ally." }
WordHunterWoW_QuestEN[86915] = { title = "Side with a Cartel", description = "", objectives = "" }
WordHunterWoW_QuestEN[86917] = { title = "Ship Right", description = "", objectives = "" }
WordHunterWoW_QuestEN[86918] = { title = "Reclaimed Scrap", description = "", objectives = "" }
WordHunterWoW_QuestEN[86919] = { title = "Side Gig", description = "", objectives = "" }
WordHunterWoW_QuestEN[86920] = { title = "War Mode Violence", description = "", objectives = "" }
WordHunterWoW_QuestEN[86921] = { title = "This is a repro test", description = "Some sickly looking wolves have descended upon the neighborhood and are wrecking havoc with property values! \n\nWe'll never attract new residents at this rate! Could you please get rid of them?", objectives = "Some sickly looking wolves have descended upon the neighborhood and are wrecking havoc with property values! \n\nWe'll never attract new residents at this rate! Could you please get rid of them?" }
WordHunterWoW_QuestEN[86923] = { title = "Go Fish", description = "", objectives = "" }
WordHunterWoW_QuestEN[86924] = { title = "Gotta Catch at Least a Few", description = "", objectives = "" }
WordHunterWoW_QuestEN[86929] = { title = "The Council Assembles", description = "Guards collected Orweyna and took her to get ready to meet the Council. When you are ready, we should attend the gathering.", objectives = "Attend the Council meeting.", completion = "To stay among us, it must be proven that the goddess has indeed called you to her aid. \n\nYou will undergo trials at the Den of Echoes, a holy place for our people." }
WordHunterWoW_QuestEN[86930] = { title = "To Sow the Seed", description = "Eonka's seed from Rift of Aln is the clue we were looking for. The inhabitants and plants there seem immune to the Lightbloom!\n\nWe must investigate the rift for ourselves. Let us return to the Den and plan our next moves.", objectives = "Return to the Den.", completion = "We return to where we started, but this time you have been blessed by the goddess and we have evidence that the spread of the Lightbloom may be stalled!\n\nThe way forward is not yet clear, but I feel that we are closer." }
WordHunterWoW_QuestEN[86934] = { title = "Trash to Profit", description = "Ey! I heard you've been cleanin' up some of the trash around Undermine. Good on ya.\n\nAny interest in takin' that more literally?\n\nIt's a dirty job, but lots of gold to be made if you're good at it. If that sounds up your alley, go talk to the boss man Carlo back at Undermine Sanitation.\n\nTell him I sent ya so I get my recruitment bonus!", objectives = "Talk to Carlo Greasegrind at Undermine Sanitation.", completion = "Renzi's really been rackin' up the recruits lately. You're gonna have some competition!" }
WordHunterWoW_QuestEN[86935] = { title = "On-the-Job Training", description = "If you're lookin' for work, S.C.R.A.P. is always hirin'. That's short for \"Salvage, Cleanup, and Recl-Amation Patrol.\"\n\nWe go around Undermine shovelin' up trash and pickin' out the good bits. Valuables get brought back here, cleaned up, and resold to whoever's buyin'.\n\nFind somethin' useful and my man Angelo will trade you for it. Go check out what he's got in stock, then find me out in the field and I'll show you the ropes.\n\nBut I mean, it's trash shovelin', not rocket surgery.", objectives = "Check out Angelo Rustbin's wares inside Undermine Sanitation, then complete a S.C.R.A.P. job in Undermine.", progress = "You might wanna invest in some eye protection. Or at least some really thick gloves. Maybe nose plugs.", completion = "Ah, I love the smell of profit at an ambiguous time of day.\n\nIf you wanna make some more moolah, find me out in the field again. We're gonna do real good work together." }
WordHunterWoW_QuestEN[86936] = { title = "Warped Wood", description = "Our shredders were cuttin' down trees in this area to make room for new homes when they suddenly uprooted and started causin' all kinds of havoc! As if all these diseased animals weren't bad enough, those trees seem hell bent on preventing us from completing this job.  \n\nIf you could clear out a few it would really help speed up our construction efforts.", objectives = "Kill 3 Rotting Treants" }
WordHunterWoW_QuestEN[86937] = { title = "Healthy Home Certified", description = "We think we've found the source for all this disease nonsense and wouldn't ya believe it -- a blasted satyr. I hate these guys, always showin' up in places I want to harvest for precious resources.  Do us a favor and get rid of him?\n\nAs always, see my assistant for payment.", objectives = "Kill the Xarn Felhoof" }
WordHunterWoW_QuestEN[86938] = { title = "Void Perforations", description = "", objectives = "" }
WordHunterWoW_QuestEN[86939] = { title = "Twilight's Wedge", description = "", objectives = "" }
WordHunterWoW_QuestEN[86941] = { title = "Elemental Infusion", description = "", objectives = "" }
WordHunterWoW_QuestEN[86942] = { title = "Culling the Spread", description = "Powdercap said that the visiting travelers were the first to show signs of the Lightbloom infection--right after you questioned them!\n\nSadly, it seems Koozat has also fallen to the sickness. Take out the merchants and see to Koozat as well. He's far too dangerous a creature to be trampling around here.", objectives = "Slay the visiting rutaani merchants and Koozat.", progress = "I raised Koozat since he was small enough to fit in my hands. The Lightbloom does not discriminate who it infects.", completion = "It is done, then. I grieve that this was necessary, but the corruption needed to be pruned before it could spread further." }
WordHunterWoW_QuestEN[86943] = { title = "Drilling Down", description = "", objectives = "Defeat the Precision Powerdrill in a Pet Battle." }
WordHunterWoW_QuestEN[86944] = { title = "Seeds of the Rift", description = "The situation is stabilizing, but let's make sure we're in the clear. I will see how Hagar is faring.\n\nCheck on Eonka again and be sure that she's not showing any signs of Lightbloom. She is on an upper level in Hagar's Hut.", objectives = "Check on Eonka.", progress = "Let us hope Eonka is unchanged.", completion = "Eonka and her seeds are not affected by the Lightbloom. Incredible! Could there be something about the rift that keeps the Lightbloom in check?" }
WordHunterWoW_QuestEN[86945] = { title = "Shadowed Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[86946] = { title = "Unwrapped and Unraveled", description = "Seeing you two on the battlefield was beautiful. It really is wonderful watching you work. If only your so-called friends had trusted you with the truth of their actions so long ago. Locus-Walker hasn't tried to deceive you with his actions in the present, though his actions in the past that led us to this point... he has been less than forthcoming about.\n\nIn all good conscience, I cannot continue hiding the truth from you or Alleria.", objectives = "Find Alleria before she confronts Locus-Walker.", completion = "This is just like the Harbinger to fulfill her oaths to the letter, but leave her allies devastated. If there was any other way to stop the All-Devouring from rising once more...\n\nWith my Reshii Ribbon, you are a step closer toward reaching Dimensius. But you will need at least twice as many to get a force large enough past his dread aura. Good luck, <name>. Watch the Harbinger's every move." }
WordHunterWoW_QuestEN[86947] = { title = "Tiny, Expensive, and Deadly", description = "", objectives = "Defeat Baxx the Purveyor in a Pet Battle." }
WordHunterWoW_QuestEN[86948] = { title = "Twilight Bonds", description = "", objectives = "" }
WordHunterWoW_QuestEN[86949] = { title = "Loyal Crewmates", description = "", objectives = "Defeat Prezly Wavecutter in a Pet Battle." }
WordHunterWoW_QuestEN[86951] = { title = "Ascended, Descending", description = "", objectives = "" }
WordHunterWoW_QuestEN[86952] = { title = "Approach the Croach", description = "", objectives = "Defeat Creech in a Pet Battle." }
WordHunterWoW_QuestEN[86956] = { title = "The Traveling Flowers", description = "Orweyna mentioned that there are rutaani who are visiting from other villages. This is an opportunity for us to get to know what they're like when they're not Light-crazed.\n\nI will stay here to speak with Meeka. You should speak with the visiting rutaani to determine whether the Lightbloom has reached their homes.", objectives = "Talk to the visiting rutaani merchants.", progress = "We must stop the spread of the Lightbloom! Determining its spread will help us fight it in the long run.", completion = "So there are no signs of Lightbloom yet in their villages? Meeka seems unchanged as well, and states that the rutaani never act in the manner of the Light-crazed.\n\nThis is both promising and frustrating.\n\nI am glad that it hasn't yet spread that far, but I suspect we shall find more soon." }
WordHunterWoW_QuestEN[86957] = { title = "Drakgor's Revenge", description = "", objectives = "" }
WordHunterWoW_QuestEN[86959] = { title = "Bloodeye Prisoners", description = "", objectives = "" }
WordHunterWoW_QuestEN[86960] = { title = "The Key to Good Health", description = "I'm supposed to be the assigned health advisor for this job but somehow I'm the one who ended up getting sick! I have antidotes in this chest but I lost the key and I suspect one of the local wildlife ate it in the aftermath of being attacked. Be a pal and see if you can find it?", objectives = "Find a key to open the chest and retrieve the antidote." }
WordHunterWoW_QuestEN[86961] = { title = "Diversified Investments", description = "<The letter is simply addressed to \"The {class} who took down Gallywix.\" It takes you a frustrating amount of time to rip open the multiple layers of duct tape sealing the envelope shut.>\n\nHey bud,\n\nYou've been gettin' a reputation for yourself. Not afraid to roll up your sleeves and get down to business. Certain people really value that kind of thing.\n\nLet's talk shop. Meet me in my warehouse and maybe we can agree on a business partnership.", objectives = "Find your prospective \"business partner\" and speak to them.", completion = "Lookin' forward to doin' business with ya." }
WordHunterWoW_QuestEN[86962] = { title = "Blood in the Wound", description = "", objectives = "Return the Antidote" }
WordHunterWoW_QuestEN[86973] = { title = "Halting Harm in Har'mara", description = "Lightbloom-infected rutaani are attacking the village! Rizam and Teetem both succumbed to the infection. It looks like Eonka hasn't been affected, but we must handle the others.\n\nI will stay here and keep an eye on her. I need you to do what you can to protect Har'mara. Take out Rizam and Teetem as well.", objectives = "Slay 8 Lightbloom rutaani.", completion = "Tough, but needed work. May this slow the spread until we can find a way to stop it entirely." }
