WordHunterWoW_QuestEN[86997] = { title = "Spellbook Scuffle", description = "You there!\n\nI've heard whispers of your so-called \"heroics,\" but I'm convinced they must be false. For if they were true, it would mean you would have achieved more than I, Tytalor Goldenblade--the finest, smartest, and most handsome mage at this academy.\n\nTherefore, I challenge you to prove your worth, if you are not a coward. The arcane tomes will make a fine warm-up for you... if you survive. Tear out their pages and prove you're not a complete fraud.", objectives = "Collect 9 Torn Spellbook Pages from Arcane Tomes in Sunstrider Isle.", progress = "Well? Are the pages in your possession, or will you admit your deception?", completion = "Shocking. Truly shocking. Perhaps there's some truth to you after all--but only perhaps." }
WordHunterWoW_QuestEN[86998] = { title = "Training Arc", description = "Hah! You actually managed to defeat the spell books? I suppose even a blind squirrel finds a nut once in a while.\n\nDon't get too proud of yourself though! My followers ahead won't be so easily dismantled by your flailing. When you inevitably fail, I'll be sure to remember this as the moment your arrogance got the better of you.", objectives = "Best 6 mages in Sunstrider Isle.", progress = "Ah! So you've come crawling back after failing to defeat even my least competent followers?", completion = "I must say, I underestimated you. It seems there's more to you than just flailing around." }
WordHunterWoW_QuestEN[87000] = { title = "No Wood Left Behind", description = "When we were attacked by the local fauna we had to leave behind much of the wood we already harvested. While we are waitin' for you to take care of our little animal problem, we could be turnin' those logs into planks to get a head start on our buildin' efforts. If you can bring me back any I'd sure appreciate it pal.", objectives = "Collect 8 wood logs." }
WordHunterWoW_QuestEN[87001] = { title = "Warrant: Shatterpulse", description = "The horrifying monstrosity known as  Shatterpulse lies hidden in a stasis cell at Shadowpoint. It is not kept as a prisoner, but as a weapon to be unleashed upon us when we are least prepared.\n\nCreate a key to open Shatterpulse's stasis cell revealing this threat to everyone.", objectives = "Collect a Calculation Container, Marking Matrix and some Void Fused Resin to create a key.", progress = "Combine the items to form the Stasis Cell Key.", completion = "You have created the Shatterpulse Cell key." }
WordHunterWoW_QuestEN[87002] = { title = "Academic Aspirations", description = "How charming. You've actually made it this far thinking you've proven something. Let me make it clear--nothing you've done compares to my prowess. You've struggled through the simplest of challenges, but now you'll face me. Meet me at the top of this tower and I'll show you exactly how far beneath me you really are.", objectives = "Defeat Tytalor Goldenblade in Sunstrider Isle.", completion = "You've defeated me today, but mark my words... I will rise again, and you'll regret crossing me. I am Tytalor Goldenblade, and this defeat is but temporary!" }
WordHunterWoW_QuestEN[87008] = { title = "Ad-Hoc Wedding Planner", description = "Eeey, now that was a wedding worth talkin' about!\n\nYou did okay. Everything went right and the only hitch was the one my little girl got. So we're good.\n\nI know the bride an' groom wanna say their thanks so go chat with them.", objectives = "Speak with Neenee and Vrizek.", progress = "Ain't it great to see those two crazy kids hitched?", completion = "You did right by my little princess." }
WordHunterWoW_QuestEN[87010] = { title = "Calculation Container", description = "A Calculation Container is no easy feat to construct.\n\nI have not made one recently, as thieves have stolen the data rods I need to complete the task. If you can recover the rods, I could create one.\n\nBe warned! \n\nThe rods are quite heavy and will take some effort to return them. I have been known to drop them quite easily.", objectives = "5 Weighty Variable Rod delivered to Engineer Om'loof", progress = "Have you found what we need?", completion = "Carrying those weighty rods is quite unpleasant. I am relieved that the task of transporting them fell upon you.\n\nThe effort was worth it though! I have constructed the item you desire." }
WordHunterWoW_QuestEN[87254] = { title = "Curse Cleanse", description = "Warlord Akutu could die at any moment, and you brought no pango liver? Bah!\n\nEach day I scream at Kulzi to tell me how to cure him. I say, \"you force me to use de forbidden liver ritual!\" But de loa says nothin'.\n\n<Loa Speaker Sij'ta's eyes seem angry but also afraid.>\n\nIf he won't tell us what is wrong, then we will have to use de pango liver ritual. It is rumored to be a potent but forbidden ritual.\n\nGet de largest pango liver you can find. There is no time to waste.", objectives = "Collect a Large Pango Liver and bring it to Warlord Akutu.", progress = "De liver ritual did nothin'?", completion = "Bah! Dat loa...\n\n<Loa Speaker Sij'ta spits on the ground.>\n\nEven the forbidden ritual fails to heal Akutu? What curse is this?" }
WordHunterWoW_QuestEN[87256] = { title = "Alternative Medicine", description = "I can't leave de warlord's side. I swore an oath to Zul'jin himself to save de Amani warlords at any cost. If I leave, he is sure to die. He is already cold as death! If he weren't movin' and talkin', I'd swear he was already dead.\n\nThere are things we can do without de loa's diagnosis. Bring me de bloodweed branches dat grow below de shrine. They're very important to de healin' rituals we can still do.\n\nGather me a heap of dem.", objectives = "Collect Bloodweed Branches from shrubs below the Shrine of Kulzi.", progress = "Dey must be pungent if dey gonna work.", completion = "With dis many, we can work our magic to heal de whole war party too!" }
WordHunterWoW_QuestEN[87267] = { title = "Demands Unmet", description = "Good, we have de branches. We will use them! Above us are de altars where we bring de injured to Kulzi for healin'...\n\n<Sij'ta looks very disoriented.>\n\nWait. I already did this. I brought Akutu up there, an' laid him upon one of de altars. Dat is where he held my hand, made me swear to...\n\nWhat? Why can't I remember?\n\nYou--you're here for a reason. Go get answers. If de loa appears, tell him he's gotta fix dis--or else!", objectives = "Confront Kulzi, the Loa of Medicine.", progress = "Kulzi cannot keep ignorin' us!", completion = "What is dis ya bring me?\n\nA broken staff?" }
WordHunterWoW_QuestEN[87268] = { title = "Required Repentance", description = "I remember dis staff. And I remember dat day.\n\nWe are... dead, then.\n\n<Sij'ta seems to take in the realization with a sort of relief.>\n\nAkutu was near death from a battle in de city. He had some serious wounds. Kulzi said he could not heal dem. Akutu would not accept dis. He wanted me to use de staff--a hexlord staff--on Kulzi to force him to heal.\n\nAnd then... I think I broke it.\n\nShow de other spirits here dis staff. Maybe we can piece together what happened from their memories.", objectives = "Use the staff to aid Forgetful Ghosts in remembering what happened at the Shrine of Kulzi.", progress = "Show dem de staff. See what dey remember.", completion = "I wish I knew why I broke de staff.\n\nI think it's time for de warlord to face his memories, just like we are.\n\nOtherwise, we gonna be trapped in dis curse forever. We gotta remember, even if we don't want to." }
WordHunterWoW_QuestEN[87284] = { title = "A Radiant Echo", description = "<Within your hand, you hold a small Azerite sphere. Its light is steady and bright, but the sound it emits is plaintive and longing. It tugs at you, ever so slightly.>", objectives = "Bring the Radiant Echo to a Worldsoul Memory, then release it.", completion = "<As you release the Radiant Echo, visions of the past materialize before your eyes. The Worldsoul herself is sharing her memories with you.>" }
WordHunterWoW_QuestEN[87285] = { title = "Marking Matrix", description = "A Marking Matrix must be attuned to the frequency of the void energies wielded by the Shadowguard. You must obtain samples of that energy.\n\nMy containment Trap is designed to capture Shadowguard and allow you to extract the void markings tied to their corrupted energies.\n\nWith those markings I can create a matrix to help attune your creation to work on void powered constructs.", objectives = "8 Void Markings extracted from Shadowguard enemies.", progress = "Have you finished the work?", completion = "Don't tell me what that matrix is going to help make, but I hope that it's quite an exciting creation!" }
WordHunterWoW_QuestEN[87289] = { title = "Barreling Down", description = "If it's ale ye be looking for, we've plenty to sample! Or at least we would if the dracthyr folk would hurry up and bring the rest of the barrels down here.\n\nSome o' the dracthyr folk have come to celebrate here with us and decided to help transport the ale. Rolling barrels? That's no way to treat a good brew!\n\nMind lending a hand to bring those barrels over to Kharanos? And try not to break 'em!", objectives = "Deliver barrels to Kharanos.", progress = "Careful with the barrels! Ye shouldn't jostle a good ale.", completion = "Glad to see that delivery in one piece!" }
WordHunterWoW_QuestEN[87290] = { title = "The Oasis", description = "Hello again, {name}. \n\nVe'nari asked me to find you. She asked that you meet her in the Oasis.\n\nI shall join you shortly. I have some errands to run here first.", objectives = "Travel to the Oasis in K'aresh.", completion = "Ve'nari did not tell me she was hiring offworlders. Good help is so hard to find. I suppose you will have to do." }
WordHunterWoW_QuestEN[87291] = { title = "Salad Bar", description = "Hemet, Om'talad, and I have been working together to see what we can do to help the lapbugs. It seems their original food source didn't make it through the collapse of K'aresh!\n\nDo you think you might be able to gather some prickleblooms and lustrous conkers, and put together a little platter for them?", objectives = "Collect 7 Chopped Oasis Plant cuttings and then place 3 Plant Platters.", progress = "Have you fed the lapbugs?", completion = "That worked wonderfully! You have quite the eye for building an attractive bit of charcuterie." }
WordHunterWoW_QuestEN[87292] = { title = "Rooting for Trouble", description = "Our bees have been marvelous at cultivating the local flora. Some of the plants have seen almost explosive growth.\n\nHowever, the lapbugs have become entangled in their roots. I've been untangling them all morning. Would you lend a hand?", objectives = "Detangle 10 Stuck Lapbugs.", progress = "Have you gotten those lapbugs untangled?", completion = "Finally! Let's hope the little lapbugs stay out of trouble from now on." }
WordHunterWoW_QuestEN[87293] = { title = "Shameless Hawking", description = "Lapbugs were once a highly sought after pet here on K'aresh. \n\nI suspect we could use them to attract interested parties in Tazavesh, increasing both support and donations for the Oasis.\n\nI would like you to test this theory.", objectives = "Gather support for the Oasis in Tazavesh.", progress = "Yes? I am busy.", completion = "It seems the lapbugs are just as popular now as they were long ago. Excellent." }
WordHunterWoW_QuestEN[87294] = { title = "A Truth Universally Acknowledged", description = "I have an idea, {name}. Everyone seems to love the lapbugs, so I have enlarged them, given them hats, and placed them in picturesque locations. Take this camera and take some photos with the lapbugs. \n\nIf I am correct, this will go a long way toward increasing support for our efforts.", objectives = "Take a S.E.L.F.I.E. with various lapbugs that are wearing hats.", progress = "Have you gotten those photos? Do make sure your charming face is in them as well.", completion = "These are excellent. Your photography skills are to be commended. I particularly enjoy this one with Sir Cuteington. \n\nThank you." }
WordHunterWoW_QuestEN[87297] = { title = "Cashing the Check", description = "We got one more thing to set straight.\n\nCome on. Grimla's waitin' for us back in the hotel lobby.", objectives = "Speak to Grimla Fizzlecrank in the Incontinental Hotel.", progress = "Heya, boss.", completion = "We've shown everyone that Undermine ain't never bendin' the knee to no one. And if they try to force us, they better be ready for a hell of a fight.\n\nThe future ain't gonna be perfect--but if it's ours to mess up, that's good enough for me." }
WordHunterWoW_QuestEN[87298] = { title = "Void Fused Resin", description = "Void-Fused Resin isn't my usual craft, but there is a way I could make it for you.\n\nVoid energies continue to seep through the cracks in our shields contaminating the plants in the domes. If we eliminate the contaminated plants, they may provide the ingredients needed to create the resin.\n\nDestroy Void-Tainted Growths and bring me any Void Granules you find.", objectives = "35 Void Granules collected.", progress = "Hurry, you need to finish this task!", completion = "I am afraid the contamination will return soon enough, but this effort should slow its progression for a few days!\n\nOh, look at what I created from your efforts!" }
WordHunterWoW_QuestEN[87299] = { title = "How Old Are These Things?", description = "Marran tried to declare herself the new ruler of Stromgarde. While some in the army are complicit in her coup, there are still a lot of us who are loyal to Lord Danath Trollbane.\n\nBut when we broke ranks, Marran was ready for us. She has an army of soldiers I've never seen before. They call themselves the Red Dawn, but I think they're just the bandits wearing uniforms they took from our supplies!\n\nHelp us take out her goons and collect any evidence that shows what they really are!", objectives = "Collect 20 Articles of Proof from Red Dawn troops within Stromgarde.", progress = "Some of this stuff must be at least twenty years old...", completion = "I knew it! Her army is made up of members of the Defias, Scarlet Crusade, and Syndicate. In other words--bandits, zealots, and traitors!\n\nThis evidence should help convince others that Marran is not to be trusted!" }
WordHunterWoW_QuestEN[87301] = { title = "Untethered Battery", description = "Untethered batteries are difficult to create, as they require elusive energies that leak from void storage cells into Untethered Space.\n\nHowever, I know of an individual capable of harvesting this energy. If they can extract and store the energy and return it to me, we will have the necessary components to construct a battery.\n\nSpeak to Myi Koo and collect the energy, we can then create a battery.", objectives = "Meet with Myi Koo, enter untethered space and collect 10 Untethered Energy Samples.", progress = "Have you collected the required energy.", completion = "Myi Koo is fully charged with Untethered Energy.  More than enough to build a battery." }
WordHunterWoW_QuestEN[87302] = { title = "Rare Rivals", description = "", objectives = "" }
WordHunterWoW_QuestEN[87303] = { title = "Clean the Sidestreets", description = "", objectives = "" }
WordHunterWoW_QuestEN[87304] = { title = "Time to Vacate", description = "", objectives = "" }
WordHunterWoW_QuestEN[87305] = { title = "Desire to D.R.I.V.E.", description = "", objectives = "" }
WordHunterWoW_QuestEN[87306] = { title = "Kaja Cruising", description = "", objectives = "" }
WordHunterWoW_QuestEN[87307] = { title = "Garbage Day", description = "", objectives = "" }
WordHunterWoW_QuestEN[87308] = { title = "Twilight's Dawn", description = "The remnants of the Twilight's Hammer are reforming under a new banner, crawling from their holes to pledge allegiance to the Twilight's Blade and their new mistress: Xal'atath.\n\nWe cannot allow this to occur.\n\nStamp them out. The only mercy those who tamper with the Void deserve is a swift death.\n\n<Rommath looks pointedly at Magister Umbric as he says this.>", objectives = "Complete world quests or defeat Twilight's Blade rares in the Twilight Highlands.", progress = "There is much to do. Do not dawdle.", completion = "They deserved no less." }
WordHunterWoW_QuestEN[87317] = { title = "Denial Denied", description = "So, I broke de staff. And everybody died.\n\nMaybe dis is my mistake. Sometimes it's too hard to say we made a mistake. And den we made even more mistakes. We in this deep, now.\n\nWhile you were talkin' to the others, I tried to get through to Akutu that we're dead. But he's not listenin'. All he does is blame others. Maybe I deserve it.\n\nShow Warlord Akutu de staff. Den take him to Kulzi. We need to try to talk to de loa.\n\nDe pieces of dis puzzle are fallin' into place.", objectives = "Help Warlord Akutu face the truth and speak to Kulzi.", progress = "Why aren't ya helpin me?!", completion = "What is dis nonsense? The loa speaker gets to move on?\n\nDis is all his fault!" }
WordHunterWoW_QuestEN[87321] = { title = "Things Left Undone", description = "Hey pal, I can't thank you enough for what you've done for me... and for Undermine.\n\n<Marin glances over at Sprinkle before looking back at you.>\n\nI know you've been busy since Renzik and Gazlowe brought you here, and you keep doing what we've asked of you. But there's one more thing that needs doing.\n\nMeet up with Gazlowe at the hotel. I'm sure he'd appreciate you being there to help.", objectives = "Meet with Monte Gazlowe in the Incontinental Hotel in Undermine.", completion = "Thanks for coming, champ.\n\nThere's one more thing we got to do to set Undermine right." }
WordHunterWoW_QuestEN[87324] = { title = "Pile of Voidbane Gems", description = "Voidbane Gems are dangerous business! \n\nThe Shadowguard hide the gems in Untethered Space.  You need to go in and find them. Be warned though, others may be looking for those gems as well!\n\nI marked the location of  the stashes for you, but there's other gems laying around too. Grab what you can, and you'll have yourself a nice big pile of gems when you're done.", objectives = "20 Voidbane Gems collected.", progress = "Hurry, grab those gems before someone else does.", completion = "I knew you could do this. After my finders fee, you still have a nice pile of gems." }
WordHunterWoW_QuestEN[87325] = { title = "Test Endeavor - Gather", description = "", objectives = "" }
WordHunterWoW_QuestEN[87326] = { title = "deprecates", description = "", objectives = "" }
WordHunterWoW_QuestEN[87327] = { title = "A Challenger's Resilience", description = "Wow {name}, you've taken on some unbelievably scary dungeons AND lived to tell me about it!\n \nCome speak with me and I'll see about making your most challenging Keystones more Resilient.", objectives = "Meet with Lindormi to learn about Resilient Keystones.", progress = "You have achieved much. Your deeds are Legendary.", completion = "Since Xal'atath's sudden yet inevitable betrayals aren't a problem for you, I'll make sure to only give you really Resilient keystones from now on.\n \nIt's OK to ask me for an easier one, though. Everyone needs a break sometimes." }
WordHunterWoW_QuestEN[87328] = { title = "Truly Horrific to Behold", description = "{name}, we have much to discuss. The new threat of the Void is one that puts us all at risk. But this is not our first time. There are clues in our past encounters. \n\nSo is the case for the Black Blood. In the past, N'Zoth used it to induce visions. \n\nPerhaps we can figure out how to counter its effects by returning to these moments. \n\nCome, help me set up the portal.", objectives = "Speak with Soridormi to assist with setting up the portal.", progress = "Are you ready to revisit these Horrific Visions?", completion = "Excellent! There is no time to lose." }
WordHunterWoW_QuestEN[87329] = { title = "Into the Darkest Memories", description = "Are you prepared? \n\nThe path through the timeways has been opened to where we last entered the visions. \n\nExpect your sanity to be tested. You probably will not last long on this first attempt. \n\nThe portal is ready for you, {name}. Journey forth.", objectives = "Interact with the Portal to Horrific Visions to rediscover the horrors of the Black Blood.", progress = "We must build on our past knowledge. Did you find something new?", completion = "It's alright, <name>. You are back. You've done well. Remember, this was just a memory of a vision. \n\nWhile we will keep you safe from the past, the danger we are all in from the Void is still very real in the present." }
WordHunterWoW_QuestEN[87332] = { title = "A Collection of Variables", description = "My assistant Augermu has been monitoring you and the timeways while you were in the past. He has a way for you to replicate gaining some of the boons adventurers used the first time they faced these visions.  \n\nGive him some of the displaced corrupted mementos you gleaned from your experience for further analysis.", objectives = "Speak to Augermu to ask about what you can do with the Displaced Corrupted Mementos.", completion = "Hello there, <class>. So you're our latest test subject--I mean, the one to revisit the visions of the past? \n\nI hear you have some displaced corrupted mementos from your last trip. \n\nPerfect! I'll show you what they can do." }
WordHunterWoW_QuestEN[87335] = { title = "Echoing Lessons", description = "We can use your displaced corrupted mementos to create Echoes of N'Zoth. \n\nI don't want to bore you with the details unless you want to hear. \n\nNo? Oh well. \n\n<Augermu appears slightly disappointed.> \n\nThe more echoes you have, the closer we can get you to a version of yourself that's more prepared for the visions. \n\nSo, let's get started.", objectives = "Work with Augermu to create an Echo of N'Zoth and insert it into the Hourglass of Horrific Visions.", progress = "Were you able to slot in the first Echo of N'Zoth?", completion = "The more echoes you make, the more mementos it'll take. \n\nIf you ever want to know how much you need for the next one, talk to me. I'll figure it out. \n\nThose visions are so creepy--but together I know we'll succeed, <class>. The Void stands no chance against us." }
WordHunterWoW_QuestEN[87336] = { title = "Remembering Again and Again", description = "Now that we have the hourglass calibrated to you, you can re-enter Horrific Visions whenever you like. No need for keys when traveling back in time!\n\nThat said, we do face one limitation. The hourglass is still fragile, and I must harden it week to week to support additional Echoes of N'Zoth. Who knew that memories of an Old God were so dangerous...?\n\nWell, you should report back to Soridormi and get back to it!", objectives = "Report back to Soridormi.", completion = "As Augermu told you--with the help of the hourglass, you can now enter the Horrific Visions as much as you like. \n\nOne more thing--we have identified some key memories within each of the visions. Through them, you will find additional boons specific to that vision that allow you to remain longer and explore more. \n\nI will add descriptions in the vision's Heart Chamber to help you find or unlock these boons." }
WordHunterWoW_QuestEN[87337] = { title = "Custodian Duties", description = "Ve'nari is very busy. While both her and Om'talad are away, I will give you your orders.\n\nWe have many creatures here in the Oasis. They make messes. Go clean them up.", objectives = "Clean up the Oasis in K'aresh.", progress = "I apologize for that.", completion = "I apologize for the task my custodian gave you. Good help is difficult to find." }
WordHunterWoW_QuestEN[87338] = { title = "Day One Orientation", description = "We've taken some of the native species we saved out of stasis. We will need to recreate their habitats.\n\nThere are two primary species here, as well as this console to monitor species in the Oasis. I recommend acquainting yourself with these creatures before we begin.", objectives = "Introduce yourself to the animals of the Oasis, and check their status on the console in the Oasis.", progress = "Have you familiarized yourself with the animals?", completion = "You are unharmed. Excellent. This means we may proceed faster." }
WordHunterWoW_QuestEN[87339] = { title = "Ongoing Activities", description = "While you will be on assignments that befit your skill set, there are also additional tasks that need to be done in the Oasis on a regular basis.\n\nWhile these are typically done by the custodians, if you are in the area I would not say no to your assistance with them. Now, and in the future.", objectives = "Perform various activities in the Oasis in K'aresh.", progress = "Have you been hard at work?", completion = "Should you wish to help out the custodians, there is always data to be collected, plants to be watered, and soil to flatten." }
WordHunterWoW_QuestEN[87340] = { title = "Junk Mail", description = "One final item before we begin--a special task suited to your unique capabilities. \n\nNo, not killing. Flying. The Oasis requires donations. Donations come from advertising. \n\nTake these stacks of fliers and distribute them around Tazavesh.", objectives = "Fly through the rings above Tazavesh to distribute fliers.", progress = "Have you distributed the fliers?", completion = "I have received several requests to donate already. Excellent work." }
WordHunterWoW_QuestEN[87341] = { title = "Barreling Down", description = "If it's ale you're looking for, we've got plenty to sample! Or at least we would if the Dracthyr folk would hurry up and bring the rest of the barrels down here.\n\nSome of the Dracthyr have come to celebrate here with us and decided to help transport the ale. Rolling barrels? That's no way to treat a good brew!\n\nMind lending a hand to bring those barrels over to Razor Hill? And try not to break them.", objectives = "Deliver barrels to Razor Hill.", progress = "Careful with the barrels! You shouldn't jostle a good ale.", completion = "Glad to see that delivery in one piece!" }
WordHunterWoW_QuestEN[87342] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in the Isle of Dorn.", completion = "Honor the Isle of Dorn flame." }
WordHunterWoW_QuestEN[87343] = { title = "Warrant: Hollowbane", description = "Shadowguard forces in Shadow Point have rallied around an enigmatic champion know as Hollowbane.\n\nThough the Hollowbane's existence is unconfirmed, we have located a travel portal supposedly used by the champion.\n\nUnlock the portal and expose Hollowbane so they may be confronted and eliminated.", objectives = "Combine an Umbral Facade, Energy Encapsulation and a Bag of Veilshards to create a portal key." }
WordHunterWoW_QuestEN[87344] = { title = "A Key Threat", description = "Tazavesh is a city rife with turmoil, beset by countless dangers. We could always use your help.\n\nCheck our warrant board, and see if you have what it takes to eliminate our most wanted threats.", objectives = "Complete a warrant and eliminate the threat to our city.", progress = "Have you completed a warrant.", completion = "Fine work, be sure to check the warrant board for additional threats as they arise." }
WordHunterWoW_QuestEN[87345] = { title = "Warrant: Xy'vox the Twisted", description = "Xy'vox the Twisted the former constable of Tazavesh, hailed from a powerful cartel family.\n\nUnknown to most, the family's power was obtained from illegal crimes, all conveniently overlooked by Xy'vox.\n\nWhen the truth came out, Xy'vox went into hiding. I believe the constable never left town, instead hides here in plain sight, continuing criminal activities.\n\nCreate a Refuge Dampener to reveal Xy'vox to all of Tazavesh.", objectives = "Collect a Tazavesh Facade, Ethereal Seal and a Zo'kita Fruit." }
WordHunterWoW_QuestEN[87347] = { title = "Bubbling Brews", description = "Drat! I might've made a mistake asking the dracthyr to help with these deliveries. They've been rolling barrels of brews and crashing 'em all over the place! Well, we shouldn't let the brew go to waste if we can help it!\n\nTake a barrel an' take to the skies! Try to collect and save as much of the brew as you can by collecting the bubbles.", objectives = "Collect brew bubbles in Dun Morogh.", progress = "Have ye filled up the barrel?", completion = "Thank ye kindly for the help. Now if I can just convince the dracthyr to simply fly the barrels here instead of rolling 'em..." }
WordHunterWoW_QuestEN[87349] = { title = "Bubbling Brews", description = "I might've made a mistake asking the dracthyr to help with these deliveries. They've been rolling barrels of brews and crashing them all over the place! Well, we shouldn't let the brew go to waste if we can help it!\n\nTake a barrel and take to the skies! Try to collect and save as much of the brew as you can by collecting the bubbles.", objectives = "Collect brew bubbles in Durotar.", progress = "Have you filled up the barrel?", completion = "Thank you for the help. Now if I can just convince the dracthyr to simply fly the barrels here instead of rolling them..." }
WordHunterWoW_QuestEN[87350] = { title = "Abundance: Loaknit Den", description = "", objectives = "" }
WordHunterWoW_QuestEN[87354] = { title = "Reshanor, the Untethered", description = "", objectives = "" }
WordHunterWoW_QuestEN[87355] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in Hallowfall", completion = "Honor the Hallowfall flame." }
WordHunterWoW_QuestEN[87356] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in Azj-Kahet", completion = "Honor the Azj-Kahet flame." }
WordHunterWoW_QuestEN[87357] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in the Ringing Deeps", completion = "Honor the Ringing Deeps flame." }
WordHunterWoW_QuestEN[87358] = { title = "Umbral Facade", description = "The trick to creating a perfect Facade is to scan live Shadowguard with a nifty little device I will provide you. This device will allow you copy the very unique essence that is the core of their being, and store it for our use.\n\nYou can locate shadowguard in both regular and untethered space. Regardless of how you find them, they won't take kindly to your presence, and they certainly won't want to be scanned.", objectives = "18 Shadowguard Essence scanned", progress = "Did you finish those scans?", completion = "Very well done! It's not often I see someone return with a full scanner." }
WordHunterWoW_QuestEN[87363] = { title = "Tazavesh Facade", description = "To create the perfect Tazavesh facade, you must scan live Shadowguard around Tazavesh with a device I will provide you.\n\nThis device will mark the targets, allowing you to copy the unique essence that is the core of their being and store it for our use.\n\nThis is dangerous business, as you will have to approach them directly and see if they're willing to be scanned!", objectives = "15 Shadowguard Essence scanned.", progress = "Did you finish those scans?", completion = "The criminal elements in Tazavesh don't like being scanned. It's not often I see someone return with a full scanner." }
WordHunterWoW_QuestEN[87374] = { title = "C.H.E.T.T.ing In", description = "<You notice your bags feeling slightly heavier just as you catch a glimpse of a shadow moving away from you.\n\nA quick search uncovers a card you don't recognize.\n\nOne side has, simply, \"C.H.E.T.T.!\". The other is a condensed map of The Undermine with directions to The Incontinental's second floor.>", objectives = "Speak to C.H.E.T.T. on the second floor of The Incontinental to learn about C.H.E.T.T. Lists.", completion = "<Unsure whether you now know more or less about this mysterious machine, you continue your adventures with a new opportunity at hand.>" }
WordHunterWoW_QuestEN[87376] = { title = "Ethereal Seal", description = "An Ethereal Seal grants unrestricted access and control over Ethereal assets without raising suspicion.\n\nAcquiring an authentic seal can be quite difficult. It is far easier to forge one using discarded cyphers instead.\n\nIf you're not afraid to get your hands dirty, you can find discarded writs in the trash piles outside of town. Bring those to me, and I can create a seal for you.", objectives = "Collect 12 Discarded Shadow Writs.", progress = "Did your find the Shadow Seals?", completion = "Oh, these are nice. A seal will be easy to create." }
WordHunterWoW_QuestEN[87380] = { title = "Zo'kita Fruit", description = "You can have the fruit, but only if you do me a favor first.\n\nSomething is watching us. You can't see it, but the smell of the fruit draws it to us. Hidden monsters lurking just beyond our sight.\n\nGain access to the Untethered Space, hunt these creatures down, and bring me their hides.  I want proof that these creatures actually exist!", objectives = "8 Untethered Hide collected", progress = "Did you see them? Did you cut them to pieces?", completion = "I knew they existed, and these fabulous hides to show for it! Take this fruit as I promised." }
WordHunterWoW_QuestEN[87388] = { title = "A Bigger Beast", description = "Return to Umbric? But we're on the brink of deeper understandings!\n\nHypothesis: there exists an apex predator amongst these creatures that might hold immense power! And this predator's relationship with the Void could further our own understanding of the infinite darkness.\n\nEradicate some of the smaller creatures and see if such a beast answers the call of violence!", objectives = "Slay 8 Vicious Karions in the Bladeburrows.", progress = "There is a connection between these beasts and the Void... not so unlike the ren'dorei.", completion = "There may be a time and place for caution, but now is not that time.\n\nI hunger for results!" }
WordHunterWoW_QuestEN[87391] = { title = "Sampling the Local Fare", description = "This place is a food chain of ferocity and far too many teeth.\n\nOur studies grow more dangerous by the minute, but if Matrean insists on staying, we may as well assist him.\n\nWe're studying a link between the nature of these creatures and the Void's accumulation here. \n\nDispatch some of the beasts below and bring samples of their tissue back to me. We can study them to learn more of their connection with the Void.", objectives = "Collect 30 Exotic Tissue Samples from creatures in the Bladeburrows.", progress = "Can there even BE a ruler of such a chaotic animal kingdom?", completion = "He ATE the samples?\n\nI'm afraid the Void's grip on Matrean is growing firm." }
WordHunterWoW_QuestEN[87392] = { title = "Cargo Conspiracy", description = "The Sunwell's radiance may shine, but its Light has not purged the filth that festers within this city. Smugglers scuttle through the streets like vermin, preying upon the desperate and enriching the spineless.\n\nYet, there are whispers of something fouler still--trade in wares so vile that even the Venture Company would recoil. I require someone to spy on each shipping company and find out which cloaks a smuggling ring.\n\nWill you stand with me, or will you turn away as the rot spreads?", objectives = "Investigate Shipping Companies in Fairbreeze Village.", progress = "So, what did our fine dockworkers have to say?", completion = "Ah, a note on \"special cargo.\" How delightfully subtle--about as discreet as a goblin's pyrotechnics.\n\nIt seems the Tideborne are entangled in this mess, and we have little choice but to wade in after them. If that means diving into the depths, so be it." }
WordHunterWoW_QuestEN[87393] = { title = "Warranted Search", description = "Tideborne Freight, is it? A name far too polished, like an ornate blade designed to distract from the blood it has shed. Smuggling through the port... but I suspect this venture involves something far more perilous than we think.\n\nWe must act with haste before they set sail and vanish into the mists. Keep your weapons honed and your senses sharper. Make them understand that crossing me was a grave miscalculation.", objectives = "\"Interrogate\" 12 Tideborne Freight sailors in Sunsail Anchorage.", progress = "Back already? Let's hear it. What did you uncover about the Tideborne? And don't leave out any details", completion = "But of course, they would prefer to keep prying eyes at bay.\n\nThey are guarding something. Now, we must uncover precisely what it is." }
WordHunterWoW_QuestEN[87394] = { title = "Supplier Surveillance", description = "This note all but drips with guilt, but mere words alone will not bring down Tideborne Freight. I require undeniable proof--evidence so damning that not even their well-bribed magistrates can turn a blind eye. That is where you come in.\n\nTake this arcane recorder and make your way to the docks. Document their shipments, their crew--anything that reeks of smuggling.\n\nA single image can speak volumes, and I intend to make every word count.", objectives = "Record evidence in Sunsail Anchorage.", progress = "You're back, and with the recordings, I hope.", completion = "There it is--caught in the act.\n\nDisposing of cargo into the ocean? Clearly they are erasing evidence, which can only mean one thing: we are closing in on something significant." }
WordHunterWoW_QuestEN[87395] = { title = "Below the Brine", description = "Discarding crates into the ocean? How utterly desperate.\n\nWhatever they seek to conceal must be damning--sufficient enough to unravel their entire operation, should we recover it.\n\nTake a deep breath and retrieve it before the current sweeps it away. Every thread we pull unravels their scheme further. Soon there will be nothing left but the ruin of their own making.", objectives = "Recover 12 Submerged Cargo Items in Sunsail Anchorage.", progress = "So what did our friends at Tideborne Freight so desperately want to hide? Their scuttling cannot conceal their true intentions forever.", completion = "Unstable arcana and naga? This is hardly just smuggling--it's a disaster waiting to unfold.\n\nThe Tideborne are dabbling in matters better left untouched. It seems it is now our responsibility to see it resolved before it becomes an issue." }
WordHunterWoW_QuestEN[87396] = { title = "Dead to Rights", description = "Tideborne's decision to discard crates into the ocean was no mere error. It was a calculated delivery.\n\nPursue them, and ensure the naga are reminded of the grave consequences they face when they dare to cross us.", objectives = "Defeat 10 Tideborne naga in Sunset Strand.", progress = "Get after them!", completion = "Well done. The naga may have been handled, but our work is far from complete.\n\nTideborne Freight continues to pull the strings, and it is time we sever their control." }
WordHunterWoW_QuestEN[87397] = { title = "Cargo Collateral", description = "If the naga manage to siphon the remaining arcane energy from those unstable arcana, they will gain the very power they seek.\n\nDestroy, incinerate, shatter them--do whatever is necessary. Ensure not a single shard remains for the naga or Tideborne to exploit. I do not wish to see even the faintest trace of arcane energy linger.", objectives = "Destroy 5 Smuggled Crates in Sunset Strand.", progress = "I trust you gave that cargo a proper send-off.", completion = "You did what was required. If the cargo is gone, that is a victory--but our work is far from over.\n\nThe Tideborne must still answer for their actions." }
WordHunterWoW_QuestEN[87398] = { title = "Smuggler Showdown", description = "The naga acted out of desperation. Tideborne's crew, however, is driven by arrogance. They sit smugly aboard their ship, convinced of their invulnerability and counting their ill-gotten wealth. It is time we put an end to that.\n\nCaptain Bloodwake shall be made to answer for every crate, every transaction, and every transgression. Are you prepared to extract the truth?", objectives = "Defeat Captain Dorynth Bloodwake in Sunsail Anchorage.", completion = "Good work. I am sure there will be more figures like him in the future, but at least for today, this port is safe thanks to you.\n\nI hope I can count on you again in the future, partner." }
WordHunterWoW_QuestEN[87399] = { title = "Facing the Sun", description = "This sanctum was studying the Lightbloom well before the incident at Fairbreeze. We had no reason to be concerned over their research up until that point.\n\nHowever, the last message we attempted to send never received a reply. And this doesn't look good now that we're here.\n\nWe need to clear out some of the wildlife first, though. We cannot risk any contamination.", objectives = "Kill 8 encroaching wildlife.", progress = "How goes the hunt?", completion = "It's an unfortunate task, but the creatures did not belong here. They would have put any new researchers at risk.\n\nNow to the actual problem." }
WordHunterWoW_QuestEN[87400] = { title = "Scattered in Sunbeams", description = "We've given the garden tenders some space to continue their work unimpeded. Hopefully they can keep this place pristine until Silvermoon has the chance to fix it up.\n\nBut now we need to figure out where the missing scholars are. They were studying mana influence on plants in the gardens toward the back. Perhaps we'll find a sign of them there.", objectives = "Find signs of what happened to the Sanctum's researchers.", completion = "I'll make sure this gets to a captain. And stored properly to avoid any spread." }
WordHunterWoW_QuestEN[87401] = { title = "Gardener Mishap", description = "The sanctum door seems to be locked. Probably from the inside.\n\nI believe an arcane construct is used for heavy lifting and general upkeep alongside the treants. The core of it should override the lock on the door and work as a master key. I doubt it will just let us take it, so be careful.", objectives = "Find a magical construct and retrieve its core.", progress = "Yes?", completion = "Perfect. This should get us inside the main building." }
WordHunterWoW_QuestEN[87402] = { title = "The Light Provides", description = "We need to get into the Sanctum. Now.\n\nBurn away the roots on that door! And be prepared--nothing good can be behind it.", objectives = "Open the door to the Sanctum of the Sun and deal with what lies beyond.", progress = "We cannot wait.", completion = "What was beyond those doors was a horror. To use the Light in such a manner...\n\nThank you. We will have this place scoured with flames before it is used again." }
WordHunterWoW_QuestEN[87404] = { title = "Energy Encapsulation", description = "You need an Energy Encapsulation? You must be planning to activate a portal or teleporter with it!\n\nI can construct what you require with ease, provided you supply the necessary energy.\n\nVisit the Harvesters nearby.  They let us collect what we need, as long as we help keep the wyrms off the harvesters.", objectives = "10 Energy collected from Power Harvesters and Crackling Wyrms.", progress = "Do you have the required energy?", completion = "A simple task, yet one I find most satisfying. After all, energy is the fundamental driver of all our work here." }
WordHunterWoW_QuestEN[87405] = { title = "Warrant: Grubber", description = "A massive worm has been spotted lurking in the Scrapdrift Sands east of town. The locals have nicknamed it Grubber.\n\nTragically, we lost deputy Zo'wie when he went out to investigate.  The creature pulled him under the sand.\n\nDevise a method to lure the worm into revealing itself, so it may be eliminated once and for all.", objectives = "Collect a Basket of Zo'kita Fruit, a Dozen Veilshards and some Flavorful Scraps." }
WordHunterWoW_QuestEN[87406] = { title = "Inoperative Mega-Mecha Gorilla", description = "<Despite your best efforts, the machine remains silent.\n\nMaybe a local expert could get it working.>", objectives = "Take the Inoperative Mega-Mecha Gorilla to Ditty Fuzeboy for repairs.\n\nProvided item:", completion = "A Gorillion unit! Where'd you get one of those?\n\nInoperative? Probably just some loose wiring.\n\nGive it a good shake... flip this switch... and it's good as new!" }
WordHunterWoW_QuestEN[87408] = { title = "Being Spiritual", description = "We have perfected creating existing creatures, but I would like to go one step further. I would like to try this process with a creature that did not survive the Devouring. \n\nThis world once had a creature called a k'arroc. Locate its essence and gather it for me.", objectives = "Collect 15 Flyer Essence in Untethered Space on K'aresh.", progress = "Have you gathered the essences I needed?", completion = "If this works, it will be the greatest thing I have ever achieved--retrieving a species from extinction." }
WordHunterWoW_QuestEN[87409] = { title = "From Death, Life", description = "We have only to let the machine do its work now. \n\nI will let you do the honors. If it fails, I will place the blame on you...\n\n... I jest, my friend. Mostly.", objectives = "Help Ve'nari use her machine to create life in the Oasis.", completion = "A success... Do you understand what this means, <name>? We are no longer limited to the creatures we took with us. So long as we can find their untethered counterparts, we can remake any of K'aresh's creatures. They will live again!" }
WordHunterWoW_QuestEN[87410] = { title = "Percussive Negotiation", description = "The k'arrocs are big and they're going to need tae stretch their wings sooner or later. Let's plan for it, eh? \n\nThe Shadowguard have all sorts of void shielding going on. I bet you could get parts from them using your usual method of negotiatin' with enemies. Take the parts to Ve'nari when you're done.", objectives = "Collect 12 Void Shielding Parts in the Umbral Garrison.", progress = "Did you get the parts?", completion = "How clever of Hemet. An animal-portable void shield is an excellent idea." }
WordHunterWoW_QuestEN[87411] = { title = "Making Stuff to Look Tough", description = "I suppose we can construct the void shield Hemet imagined, but these parts are not ideal. Meet me outside the Oasis to the east and we shall see if we can craft a workable solution.", objectives = "Assist Ve'nari in crafting a Void Shield outside the Oasis.", progress = "Come now. Let us begin building.", completion = "Despite my reservations, it seems we have a serviceable portable void shield. Excellent work." }
WordHunterWoW_QuestEN[87412] = { title = "K'arrocing Photos", description = "We must keep our documentation updated. That means I require your services once more. \n\nTake this camera and gather more photos of the k'arrocs. You'll find them on the rocks around the area.", objectives = "Document 7 Domineering K'arrocs.", progress = "Have you taken the photos I requested?", completion = "These are exquisite, and will do quite nicely for our research. Thank you." }
WordHunterWoW_QuestEN[87413] = { title = "Bird Bath", description = "{name}--just the person I needed! The k'arrocs are gettin' so dirty that it's covering up their natural smell. There's not enough water here for them to bathe!\n\nTake this anima vacuum. It'll take that dirt straight off 'em, but you're gonna have to stick to the ones on the ground. Try looking on top of the rocks to the north!", objectives = "Wash 7 Domineering K'arrocs.", progress = "Have you cleaned up those dirty birdies?", completion = "Ah, I can already smell the change on the wind. Thanks so much!" }
WordHunterWoW_QuestEN[87414] = { title = "Medical Maneuvers", description = "It would be good to get a solid medical checkup on the k'arrocs. \n\nWould you shrink them down and bring them to me?", objectives = "Shrink and collect 8 Domineering K'arrocs.", progress = "Have you gathered the k'arrocs I asked for?", completion = "Ah, these will do nicely. My thanks." }
WordHunterWoW_QuestEN[87415] = { title = "The Skies of K'aresh", description = "The shielding device you helped with has been tested. It is ready for its first flight, if you will forgive the turn of phrase.\n\nSpeak with Om'torid. They have a course picked out for you and the k'arroc to soar along.", objectives = "Test out the shield device by taking a k'arroc for a flight outside of the Oasis.", progress = "How did the shield hold up?", completion = "How did it feel to be the first person to fly on the back of a k'arroc in a millennia?" }
WordHunterWoW_QuestEN[87417] = { title = "Worldsoul: Dungeons", description = "The enemies of Khaz Algar rise up, unified in the suffering they inflict on those who do not believe in their causes.\n\n<Faerin pauses, then takes a quick glance at the table in front of her before returning her gaze to you.>\n\nShow these people the light, {name}. If they cannot see the error of their ways, please show them a merciful conclusion to their beliefs.", objectives = "Complete any Seasonal Dungeon at Normal difficulty or higher.", progress = "How goes the mission?", completion = "Thank you for bringing all people of Khaz Algar a glimmer of hope." }
WordHunterWoW_QuestEN[87419] = { title = "Worldsoul: Delves", description = "These lands house many deep crevices, leaving shadows where our enemies believe they are safe. Explore these hidden places and leave our enemies no sanctuary.", objectives = "Complete a War Within Delve at any difficulty.", completion = "There are fewer shadows in the world thanks to your efforts." }
WordHunterWoW_QuestEN[87420] = { title = "Basket of Zo'kita Fruit", description = "You need more Zo'kita Fruit than I'd ever dare to keep around here! \n\nJust one Zo'kita fruit is enough to drive my brother out of the market, and you're asking for a whole basket? \n\nBold move, my friend!\n\nVisit Eco-dome: Primus, I secretly grow them there, hidden out of sight. Use my picking gear to locate them and take as many as you need.", objectives = "Collect 8 Freshly Picked Zo'kita Fruit.", progress = "Did you get enough?", completion = "So many Zo'kita Fruit! Quickly, throw them in a basket and leave before the smell sends our customers running for their lives!" }
WordHunterWoW_QuestEN[87422] = { title = "Worldsoul: Undermine World Quests", description = "Undermine may be a place I do not understand, but they too are in need of aid. Our conflicts inflame their situation, it would do good to help them move forward.\n\nGo there and help them. See what you can do to bring these... cartels closer together, and to us.", objectives = "Complete World Quests in Undermine.", completion = "You made some extraordinary efforts on some... unique requests. Your service to Undermine is appreciated by all." }
WordHunterWoW_QuestEN[87423] = { title = "Worldsoul: Undermine Explorer", description = "Undermine is held together by an intricate design of innovation, hard work, allegiance, and it seems like the sheer will of the goblins. Rather than cower in their sunless cave, the goblins have built a city that thrives on motion and activity. We can learn much from that.\n\nAfter not seeing new faces for years, they bring a new light to our lands. Go help them in whatever ways seem fitting.", objectives = "Complete various activities in Undermine.", completion = "When Beledar darkened, what would they have built if they were in our place? \n\nYour efforts continue to be of great service." }
WordHunterWoW_QuestEN[87424] = { title = "Worldsoul: World Bosses", description = "Hallowfall is not the only land beset by enemies. \n\nGreat monsters threaten our allies. Wherever the shadows of our war have fallen, savage beasts and cunning fiends rise up. They murder Arathi, earthen, and the others who stand with us. Innocent farmers to great warriors. \n\nI know the Sacred Flame burns in you. You are our best hope to hunt these great evils.", objectives = "Defeat all available World Bosses in The War Within.", progress = "I've seen monsters shifting in the distant darkness of Hallowfall. Things that haunt my nightmares.", completion = "How did you fare? Any new scars? Or new tales to tell?" }
WordHunterWoW_QuestEN[87425] = { title = "Large Sticky Voidmass", description = "Ah, yes, I've seen what you are describing!\n\nThe sap from the corrupted plants is tainted with void energy. Collect several samples of the sap as you can, and I will combine it to make a Large Sticky Mass.", objectives = "Collect 5 Corrupted Sap.", progress = "Have you found the sap?", completion = "Anything that eradicates the corrupted plants helps our efforts here." }
WordHunterWoW_QuestEN[87426] = { title = "Flavorful Scraps", description = "Plenty of profit to be made scavenging these sands, but watch out for the monster.\n\nIt's hungry, I've seen it drag scavengers under the sands!\n\nYou can trick it, I fed it once. Tossed it some scraps.\n\nYou need the tastiest garbage to lure it out. Collect what you can and I will help sort it to find the most flavorful scraps.", objectives = "Collect 24 Discarded Scraps", progress = "Did you find anything tasty?", completion = "I've picked out the most flavorful bits that'll catch the monsters attention!" }
WordHunterWoW_QuestEN[87455] = { title = "Trials and Tabulations", description = "In hindsight, we should have gone drinking in neutral territory.\n\nGidwin and I were here in Silvermoon on vacation when the Fourth War broke out. We escaped the city but left behind a... rather large bar tab.\n\nGidwin's run off to the place we were staying to find an expensive item we'd left behind, but he's late. Would you go find him while I keep this debt collector busy? He should have been back by now.", objectives = "Find Gidwin Goldbraids in Silvermoon.", completion = "<A muffled voice reaches you.>\n\nNo no, I've got it! Stand back!" }
WordHunterWoW_QuestEN[87456] = { title = "Souvenirs Scattered", description = "When Tarenar and I escaped the city before, we left some things behind.\n\nAn open bar tab, sure. But we'd also bought souvenirs for some of our friends.\n\nCould you look around for them? They're somewhere in this mess.", objectives = "Find the souvenirs in Silvermoon.", progress = "Have you found all the souvenirs? We got other things for the rest of our crew back in Suramar, but we didn't have time to mail these when we escaped.", completion = "These look to be in good shape considering how long we left them here.\n\n<Gidwin holds up the bag of herbs.>\n\nNot sure if Fiona's even still looking for these, but she'll appreciate the uh... very late gesture." }
WordHunterWoW_QuestEN[87457] = { title = "What We Do Best", description = "That spider! It blasted me right as I walked in the door. I've been gooped by one spider too many, what with all the nerubians we've been punching lately!\n\nI saw something around its neck out of the corner of my eye. It's an artifact we found while fighting the Legion. It ought to fetch a good price.\n\nYou just have to tear that spider's head off!", objectives = "Kill Squatter and collect the Antique Necklace in Silvermoon.", progress = "This necklace was in a camp we cleared of demons. Must've been for a ritual, but we stopped them from cursing it.", completion = "That's great, <name>. Thank you.\n\n\n\nDon't tell the elf I got cocooned, alright?" }
WordHunterWoW_QuestEN[87458] = { title = "Debts Paid", description = "That's everything, I think. Can't believe it's been so long since the Fourth War. We left in such a rush.\n\nLet's get that necklace to Tarenar. He's been waiting long enough.", objectives = "Return to Tarenar Sunstrike in Silvermoon.", completion = "Thank you for helping us wrap this up, <name>. The value of this necklace should easily cover our old bar tab.\n\n\n\nGiddy wasn't too much trouble, was he?" }
WordHunterWoW_QuestEN[87475] = { title = "Sureki Incursion: Hold the Wall", description = "Flames! Those chitinous vermin are relentless!\n\nWe've received reports from Auralia Steelstrike that a small force of nerubians are harassing the outer perimeter of the city.\n \nRegroup with our allies on the outskirts of Mereldar and join the fight!", objectives = "Assist the Flame's Radiance in pushing back the Sureki outside Mereldar.", progress = "We must hold the line against these Sureki. Push them back!", completion = "Excellent work, <name>. Our reinforcements will take it from here.\n\nMylton's reports indicated a much larger force to the west of the Veneration Grounds, so we must remain vigilant and hold these walls. \n\nSacred Flame guide your blade." }
WordHunterWoW_QuestEN[87476] = { title = "Midsummer", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[87477] = { title = "Sureki Incursion: Southern Swarm", description = "The Sureki aren't known to give up their assaults so easily.\n\nReports from our southern holdings have warned of a swarm stirring along the mountain range. \n\nI don't know whether they plan to hit Tenir's Ascent or Beledar's Bounty, but we cannot wait for them to make the first move.\n\nJoin our allies and intercept the swarm!", objectives = "Assist the Flame's Radiance in pushing back the Sureki swarm in southern Hallowfall.", progress = "The nerubians have brought every foul, multi-limbed horror from the depths in this swarm! \n\nWe cannot allow our holdings to fall!", completion = "Lady Faerin was right about you, <name>. We owe you our thanks.\n\nYou've bought Tenir's Ascent and Beledar's Bounty some much-needed time. \n\nWe will manage the rest from here." }
WordHunterWoW_QuestEN[87478] = { title = "[DNT] Repeatable - Camp 005", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[87479] = { title = "[DNT] Repeatable - Camp 006", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[87480] = { title = "Sureki Incursion: The Eastern Assault", description = "There's no time to rest, {name}!\n\nOur earthen allies in eastern Hallowfall have spotted a Sureki battalion preparing to attack Dunelle's Kindness--they must be targeting the Dawntower!\n\nFlame's Radiance reinforcements are securing the town and Lothar's Landing as we speak.\n\nHead east and lend what aid you can!", objectives = "Assist the Flame's Radiance and disrupt the Sureki's eastern assault.", progress = "We will hold this position. Go, help Dunelle's Kindness below!", completion = "The people of Dunelle's Kindness thank you, <name>.\n\nWe will continue to hold Lothar's Landing with our earthen allies and fortify the town below. \n\nMay the light of the Sacred Flame remain with you, friend." }
WordHunterWoW_QuestEN[87481] = { title = "[DNT] Repeatable - Camp 008", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[87482] = { title = "[DNT] Repeatable - Camp 009", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[87485] = { title = "[DNT] Repeatable - Camp 010", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[87496] = { title = "Benefit Packages", description = "Times are rough, so the cartels have been tryin' out this new business strategy called \"employee retention.\" Never heard of it before, but it sounds fancy.\n\nAnyway, I'm pretty sure it means givin' employees the privilege of buyin' stuff from the company stores after you work for 'em long enough.\n\nGo check out what the cartels got for sale. See if anything catches your eye before you start workin'.", objectives = "Visit each cartel's quartermaster in Undermine.", progress = "You can find the sellers at each cartel's headquarters.", completion = "They got some pretty nice selections, don't they?\n\nIf you ever need help findin' them again, lemme know." }
WordHunterWoW_QuestEN[87546] = { title = "Warrant: Purple Peat", description = "In restoring the eco domes, much of the contaminated plant life was removed, allowing the soil to heal. \n\nHowever, one corrupted lasher escaped our notice. Nicknamed \"Purple Peat\" by the dome technicians, it continues to spread its roots and seeds into Eco-Dome: Primus.\n\nThe plant hides safely in an old stasis cell outside the dome. Construct a device to remove the protective cell and expose the plant so it can be eliminated.", objectives = "Combine a Large Sticky Voidmass, Energy Encapsulation and a Untethered Battery create a create a key to unlock the stasis sphere." }
WordHunterWoW_QuestEN[87547] = { title = "What's Your Specialty?", description = "The Dragon Isles is a dangerous and uncharted place. We'll need to get you prepared.\n\nYou're strong enough now that you should choose a combat specialization.\n\nThis will unlock a new array of abilities for you to face the dangers within the Dragon Isles.\n\nGo ahead and choose your combat specialization.", objectives = "Choose your combat specialization.", progress = "Having trouble? You can find your combat specialization beside your spellbook.", completion = "Excellent choice! I'm looking forward to what you do next.\n\nTake this riding mount. It'll help you get around here faster." }
WordHunterWoW_QuestEN[87548] = { title = "A Dozen Veilshards", description = "Yes I know of Veilshards, a highly prized treasure, often the target of thieves! But rest assured, the upstanding citizen Om'sto, would not be involved in such crimes.\n\nTo find Veilshards you need only look to the rats of this city, they are the craftiest of thieves!\n\nFollow a Thieving Scurrier to its nest, and you're bound to uncover a gem among it's stolen hoard. Bring back what you find, and we'll bundle them into a neat dozen for you.", objectives = "Collect 12 Stolen Veilshards", progress = "Did follow the rats?", completion = "I see the city vermin were not a problem for you. This dozen will make an interesting shape. I will package them up for you!" }
WordHunterWoW_QuestEN[87550] = { title = "Week 2: We're Really Taking Off", description = "It's Dastardly Duos' second week! Twice the brutality, twice the fun! Win a match this week for even more rewards!", objectives = "Win a Dastardly Duos match, then speak with Vinnie Sweets.", progress = "Speak with Xyggie Marou and beat those Dastardly Duos!", completion = "I was right, right? The fans went wild! You're really earning a name for yourself!" }
WordHunterWoW_QuestEN[87551] = { title = "Week 3: Spread the Word", description = "Hey, you wanna help out the organization? you know, spread the word? Next time you're in a match, throw your Dastardly Banner down in the arena. Show support!\n\nBut be careful -- your opponents might take offense and come straight after you...", objectives = "Place your Dastardly Banner during a match, then win the match.", progress = "Don't forget to use your banner inside the area. Your opponents will hate it, but the fans will love it!", completion = "I like your style! Here's your prize, and a little something extra for advertising the show." }
WordHunterWoW_QuestEN[87552] = { title = "Week 4: They've Heard of You", description = "You're making a name for yourself, {race}. You keep the victories coming and I'll keep the tickets selling.", objectives = "Win a Dastardly Duos match, then speak with Vinnie Sweets.", completion = "You fight with style! You should practice your autograph -- I hear some of the viewers are forming a fan club around you." }
WordHunterWoW_QuestEN[87553] = { title = "Week 5: Another Amazing Week!", description = "<Vinnie is busy counting money>\n\nWhat? Oh, hey {name}. Here to fill more seats-- I mean... here for another match? Great!", objectives = "Win a Dastardly Duos match, then speak with Vinnie Sweets.", progress = "Speak with Xyggie Marou sign up for another match. Strike fear into your foes!", completion = "Loved the act, NHUVASARIM. Here's your prize purse.\n\nDid I see you drink a Can of Amps during the fight? Thanks! Way to get that product placement on camera!" }
WordHunterWoW_QuestEN[87554] = { title = "Week 6: It's the Finale!", description = "This is it, the end of the event. Let's go out with a roar!\n\nPut on one last good show and we can count our money together!", objectives = "Win a Dastardly Duos match, then speak with Vinnie Sweets.", completion = "Wow. Just...wow. I thought you were a goner for a second there, then I realized it was all an act for you. You get it.\n\nTake care of yourself, NHUVASARIM. And if you ever wanna stop saving the world, you'll have a bright future in showbiz." }
WordHunterWoW_QuestEN[87555] = { title = "Home Is Where the Hearth Is", description = "Before you head off, you'll want to get yourself a Hearthstone. \n\nThis little stone will return you to the inn where you last bound it to.\n\nIt's not much of an \"inn\", but the explorer's have a tent set up. \n\nTest out that new mount of yours and ride over to Happy Hal. He'll get you sorted out with a Hearthstone.", objectives = "Ride your mount, then speak with Happy Hal to get a Hearthstone bound to the Wild Coast.", progress = "Happy Hal nearby can get you set up with a Hearthstone.", completion = "If you ever find yourself lost, use your Hearthstone to get yourself back to where you should be." }
WordHunterWoW_QuestEN[87562] = { title = "Aiding the Dragon Isles", description = "It's time for us to part ways. I have pressing business further within the Dragon Isles in a place called the Azure Span.\n\nToddy Whiskers of the Dragonscale Expedition could use your help.\n\nSafe travels, {name}. I look forward to our next meeting!", objectives = "Meet Toddy Whiskers to begin your adventure in the Dragon Isles.", completion = "How are ya? We could use more hands to help us explore the Dragon Isles!" }
WordHunterWoW_QuestEN[87569] = { title = "Legally Mandated Break", description = "", objectives = "" }
WordHunterWoW_QuestEN[87581] = { title = "No More Walkin' Here", description = "We gotta do something about how long it's taking to get you around. Luckily, I know just the gal. Go meet Nanny Talullah at Shipping and Handling and see if she'll lend you some wheels.", objectives = "Meet Nanny Talullah on the third floor at Shipping and Handling.", completion = "You need a car? Of course we can get you a car! We have so many cars! Here, I even have some spare keys right here!" }
WordHunterWoW_QuestEN[87582] = { title = "Delves: Site of Madness", description = "Hey, pal. Some real weird stuff has been happening south of Gutterville.\n\nSome of my friends have gone missing, and their family's worried about them. How about you take that can-do attitude of yours down there and see if you can figure out what happened?\n\n<Paks scratches his chin before looking back at you.>\n\nI'm sure there will be some compensation to make it up to you too. Trust me.", objectives = "Complete the Excavation Site 9 delve on any difficulty.", progress = "Yo, did you figure out what happened down there?", completion = "Hey, I really appreciate you going down there and handling business.\n\nI lied about the friends thing, but at least you're getting paid, eh?" }
WordHunterWoW_QuestEN[87583] = { title = "Delves: The Sluice Contains the Juice", description = "Buddy, pal, {class}. Some Darkfuse have taken root down in the sewers here in Undermine. They're shaking down hard-working goblins for cash, stealing their lunches, and sometimes even destroying their flamingo lawn ornaments!\n\nThose Darkfuse suffer from a real lack of decorum, let me tell you.\n\nI know you'll do the right thing and help us out, especially after such a tearjerker of a story.", objectives = "Complete the Sidestreet Sluice delve on any difficulty.", completion = "Hey buddy, thanks for making sure that all flamingos around Undermine now feel safe out at night.\n\nYou're a real one." }
WordHunterWoW_QuestEN[87588] = { title = "Bash that Trash", description = "", objectives = "" }
WordHunterWoW_QuestEN[87597] = { title = "A Bag of Veilshards", description = "I myself could sell you Veilshards, but my own supply has been stolen. The vermin of this city will not hesitate to steal them when my back is turned.\n\nFollow any Thieving Scurrier to its nest, and you are sure to locate some stolen shards.\n\nTo assist you, I will provide a device capable of tracking the thieving vermin.  Recover enough Veilshards to satisfy both our needs.", objectives = "Collect 18 Om'sto's Veilshards", progress = "Did you locate the veilshards?", completion = "Ah, I knew you'd come through! The upstanding citizen Om'sto is starting to think you might be very good for business." }
WordHunterWoW_QuestEN[87672] = { title = "Void is in the Air", description = "We void elves all face the same risk... that should our resilience falter, madness awaits.\n\n<Kelia frowns in Matrean's direction.>\n\nThe caves below are steeped in Void's vile touch. Void Surges erupt from the earth, creating a miasma of filth that fills the nesting grounds.\n\n<She hands you a magical device.>\n\nTake this. It will capture the surges of dark energy bursting from the soil. We will study them safely back at the Ingress.", objectives = "Capture 3 Void Surges in the Bladeburrows caves.", progress = "The Voidstorm threatens our very existence. We cannot stay long.", completion = "<Kelia's brow furrows as she concentrates on the energy captured by the device.>\n\nThese readings are alarming. We should head back immediately." }
WordHunterWoW_QuestEN[87759] = { title = "Encapsulated Void", description = "", objectives = "" }
WordHunterWoW_QuestEN[88652] = { title = "Faceless Mask of the Nemesis", description = "There are those enemies that you will battle or come into conflict over and over. Thought defeated they return from the shadows to attack you again and again. This is is the heart of a true nemesis. And, these are the enemies that will live on forever no matter what you do.", objectives = "Return the Faceless Mask of the Nemesis to the altar within a Horrific Vision.", progress = "Place the Faceless Mask of the Nemesis on the altar.", completion = "Acknowledging your nemesis is the first step towards their final defeat. Yet, they would not be a nemesis if they did not find infinite ways to return to face you again and again." }
WordHunterWoW_QuestEN[88653] = { title = "Yolks on You", description = "Our research has proven fruitful. I can feel the promise of power beckoning. Do you hear it, {name}? The apex predator calls to us. The beast must be nearby.\n\nWe must gather tribute. Yes... we must offer it a gift of vitality! We must meet it bathed in the essence of the young...\n\nSome of the smaller creatures are nesting in the tunnels below. Break a few eggs and bathe in their juices. Then, perhaps, the beast will be drawn to the smell!", objectives = "Bathe yourself in bestial fluids by destroying 15 Blistercreep Eggs in the Bladeburrows caves.", progress = "So much flesh and bone and meat. How can we resist?", completion = "You've bathed in their essence and glow with promise, hero.\n\nWe, too, have tasted their power. It courses through us. Strengthens us." }
WordHunterWoW_QuestEN[88655] = { title = "Outbound for Outland", description = "Snakes! Why'd it have to be snakes?\n\nVe'nari says they used to have snake-like things on K'aresh before the Devouring. None of 'em survived. They still got worms, but that's nae what we're after.\n\nI know just the place--my ol' stomping grounds in Nagrand on Outland.\n\nLet's use this infernal contraption of a portal to get there.", objectives = "Regroup with Hemet Nesingwary at the Nesingwary Safari in Nagrand on Outland.", completion = "Glad to see ye didn't change your mind. Now let's get us some snakes." }
WordHunterWoW_QuestEN[88656] = { title = "Comfort Stones", description = "Right then. We're gonna need tae collect things tae make the snakes comfortable on K'aresh. Let's get 'em some bedding.\n\nSome of the most important things are rocks! Snakes can sun themselves atop a rock or hide under it.\n\nThose nearby earth elementals were always a pain in our side. See if you can get some rocks from 'em.", objectives = "Collect 20 Smooth Stones from Tortured Earth Spirits, Enraged Crushers, or Shattered Rumblers.", progress = "It's nice to be helpin' these critters rather than hunting 'em.\n\nThe angry elementals don't count!", completion = "Those'll do. Nice work." }
WordHunterWoW_QuestEN[88657] = { title = "Zangarmoss", description = "Next up, we'll be needin' some moss for their beds. Sorry to say, but we need to go into the slimy marsh for 'em.\n\nThe naga control that place. It grows on their mushroom trees. They're also fond o' munching on it or something foul.\n\nFastest way to Zangarmarsh is through the pass to the north. If it were me, I'd look around the Darkcrest Shore.", objectives = "Collect 15 Marsh Moss in Zangarmarsh.", progress = "How much you got? It's one o' the last things we need before we head back to K'aresh.", completion = "I'm glad ye made it back here in one piece, and none too soon. Me an ol' Fitz have been holding off these crazed talbuk attacks for what seems like ages." }
WordHunterWoW_QuestEN[88658] = { title = "Sneks and Things", description = "O' course, we also need some snakes. That's the whole point o' why we came out here in the first place.\n\nYou can find the small ones we want down in the Telaari Basin to the south. Just rustle their dens an' they'll come slitherin' out. That's where the plants they like grow.\n\nSpeaking of which, make sure to get some o' them fragrant plants while you're at it. Ye might not know this, but snakes have a keen sense o' smell.", objectives = "Collect 10 Nagrand Snakes and 20 Fragrant Dreaming Glory.", progress = "How many do you have? I canna tell. Your pack always looks so full.", completion = "We need to make sure the snakes are as comfortable as possible when we take 'em to K'aresh.\n\nBut, yikes. The smell o' those plants. Fragrant indeed!" }
WordHunterWoW_QuestEN[88659] = { title = "More Cozy Beds", description = "We need all sorts o' replacements for things--stones and moss for the beds, and more o' them stinky flowers.\n\nRemember, ye can get the stone from the earth elementals in Nagrand. The flowers are down in the Telaari Basin there in Nagrand as well. An' the moss is over at the Darkcrest Shore in Zangarmarsh.\n\nIt'll be a good excuse for me tae go see the gang again. Meet ye on the other side o' the portal.", objectives = "Collect 10 Fragrant Dreaming Glory, 10 Marsh Moss, and 10 Smooth Stones in Nagrand and Zangarmarsh on Outland.", progress = "Have ye got it all?", completion = "Thank ye, <name>. This'll all work nicely." }
WordHunterWoW_QuestEN[88660] = { title = "Snakes on a Plane", description = "Last, but certainly not least, we need to get those two snakes off o' me plane!\n\nI dunno how long snakes normally live, but it seems like those two have been there forever. And they always look at me funny if I come near.\n\nMaybe you could go get 'em?", objectives = "Gather the two snakes off of the crashed plane at the Nesingwary Safari.", progress = "You got 'em?", completion = "Great! I'll signal Ve'nari so she can send us one o' her gods-forsaken portals an' we'll be on our way." }
WordHunterWoW_QuestEN[88661] = { title = "To the Atrium", description = "We got what we're after. Time to head back.\n\nBefore we can introduce the snakes to the ecology in the Oasis, we need to test 'em out. There are a few o' these place they call eco-domes where that's done on K'aresh.\n\nVe'nari's portal will take us to one called the Atrium. I wish I could fly me plane there instead.", objectives = "Regroup with Hemet Nesingwary at the Atrium on K'aresh.", completion = "Now the real work begins.\n\nAn' if the snakes don't take to K'aresh, we'll make sure to get 'em back to Nagrand safe an' proper." }
WordHunterWoW_QuestEN[88662] = { title = "What's in a Name?", description = "Though they clearly don't like me, I think the two snakes from me crashed plane have taken a liking to you.\n\nYe want to name 'em?", objectives = "Name the female and male snake.", progress = "What have ye decided on?", completion = "Fine names, both o' 'em! Madame Noodles and Mister Snuggles--I love it!" }
WordHunterWoW_QuestEN[88663] = { title = "Scales and Measures", description = "Now to get some vital statistics. Ve'nari and her people have all sorts o' contraptions for doing things around here.\n\nThis li'l robot is gonna use the thing the snakes are on to take some measurements. Just speak with it when you're ready.\n\nI can get readings for the rest o' the snakes while you're off doing other things.", objectives = "Speak with the Data Collection Drone to complete a data analysis of the named snakes.", progress = "Let me know what that thing figures out an' we'll move on to other things. We gotta do some stuff before we can head back to the Oasis.", completion = "Wait... gravid? Madame Noodles is pregnant?\n\nWe're gonna have babies!" }
WordHunterWoW_QuestEN[88664] = { title = "Nagrandification", description = "Remember all those stinky plants ye gathered up in Nagrand? Would ye mind replanting 'em?\n\nWe don't have to plant 'em all right now. Just enough to test and ensure they'll take to the soil of K'aresh.\n\nWe'll be needin' a lot more plants than this eventually.", objectives = "Plant 6 Fragrant Dreaming Glory.", progress = "I'm gonna have to make certain to stay upwind o' those \"fragrant\" plants.", completion = "Yeah, I can still smell 'em from here. Sheesh!" }
WordHunterWoW_QuestEN[88665] = { title = "Follow Your Tongue", description = "Now it's time to move north into Eco-Dome: Primus. That's a mouthful.\n\nTake one o' the remaining stinky flowers an' lead the snakes there.", objectives = "Lead the Nagrand Snakes to Eco-Dome: Primus.", completion = "Now on to the next round o' testing." }
WordHunterWoW_QuestEN[88666] = { title = "Mossy Beds", description = "I've put together the rocks an' the moss that ye collected in Nagrand. Now it's time to see if the snakes like 'em.\n\nI spread 'em out around the eco-dome so you could test 'em out for differences.\n\nWhile you're doing that, I'll make preparations for getting 'em all to the Oasis.", objectives = "Test 8 Mossy Snake Beds.", completion = "Right then. We'll keep the beds they liked and maybe do somethin' else with the others.\n\nGreat work, <name>!" }
WordHunterWoW_QuestEN[88667] = { title = "Water Snakes", description = "Oh no! Some o' the snakes are having trouble adapting. They aren't drinkin' as much as they should an' are dehydrated.\n\nQuick, {name}. Take this waterin' can and give 'em a good dousing.", objectives = "Use Hemet's Waterin' Can to water 10 Parched Snakes.", completion = "Thank ye, <name>! I'd say we could do with a good shower. Do ye think they can make it rain in these eco-domes?" }
WordHunterWoW_QuestEN[88668] = { title = "Ophidian Portation", description = "Our tests are successful! Time to move to the Oasis.\n\nVe'nari gave me these \"portation\" devices to quickly get the snakes o'er there.\n\nWhy don't you take care o' Ember and Indigo, and I'll take care o' the rest? They've been giving me the side-eye ever since I moved 'em here.", objectives = "Use Ve'nari's Portation Tags on the two named snakes to transport them to the Oasis.", completion = "Now to make sure the snakes settle in as part o' the overall ecology." }
WordHunterWoW_QuestEN[88669] = { title = "Nesting Time", description = "We need to set up a nice home for these two, especially since Ember's expectin'.\n\nI took a look around an' spotted a shady place under a tree not far from here.\n\nThere's all sorts o' things to make 'em comfortable an' safe. Use Ve'nari's portation tags again to summon in everything ye need.", objectives = "Set up a home for the two named snakes.", progress = "How'd it go? Did they like their new place?", completion = "They liked it? That's great news!" }
WordHunterWoW_QuestEN[88670] = { title = "Soothing Serpents", description = "Most o' the snakes did not like Ve'nari's teleport. Others were cloned by Om'talad, an' they don't like that either. They're clearly agitated an' I'm afraid they're gonna hurt themselves.\n\nI've got this flute. Don't ask. I can't even play the darned thing.\n\nWould ye take it out there an' soothe the snakes with some calming melodies?", objectives = "Use Hemet's Soothin' Flute to soothe 15 Agitated Snakes.", progress = "I'm certain you're much better at playin' that thing than me.", completion = "We could hear ye from here. How many lessons have ye had?" }
WordHunterWoW_QuestEN[88671] = { title = "Eggstra Eggs", description = "I've been talkin' with the others about food for the snakes, an' we think we have a solution.\n\nThe k'arrocs have been prospering a wee bit too much for the ecology o' the Oasis. If ye get some o' their eggs, that should be enough for now so we can feed the snakes.", objectives = "Collect 6 K'arroc Eggs.", progress = "How goes the egg pilferin'?", completion = "How'd you carry 'em all? If I'd known, I would have given you some more o' them portation tag thingies." }
WordHunterWoW_QuestEN[88672] = { title = "Snakelets!", description = "Speaking o' eggs--I checked, an' Ember has laid her clutch. It's almost time to hatch us some babies!\n\nMeet me back at the nest an' we can welcome our first snakelets to K'aresh.", objectives = "Help with hatching the snakelets.", progress = "What an excitin' time.", completion = "All o' the snakes are fitting in better than we could possibly have imagined. This brings me so much hope for K'aresh.\n\nYe've done a great thing here, <name>!" }
WordHunterWoW_QuestEN[88679] = { title = "Encountering the Unexpected", description = "", objectives = "" }
WordHunterWoW_QuestEN[88696] = { title = "The Devouring Citadel", description = "I must return to Silvermoon, but Turalyon has commanded all able-bodied champions of the Light to meet him at the muster point outside the Voidspire.\n\nThe forces of the Devouring Host will fall, {class}.\n\nOne way, or the other.", objectives = "" }
WordHunterWoW_QuestEN[88697] = { title = "Clarity of Purpose", description = "The ethereals on the nearby plateau are forcing us to ground our heavier weapons. We'll need to neutralize their turrets before we can begin our assault on the Voidspire.\n\nSpeak to Umbric and he'll help you gain a tactical understanding of the battlefield.", objectives = "" }
WordHunterWoW_QuestEN[88698] = { title = "Master of Mayhem", description = "{name}, ethereals have been striking out from the Ethereum Overcroft, harassing our Vanguard forces where they find them. If you can bring the fight to them, it'll take the pressure off our muster.\n\nCan you do that for us?", objectives = "" }
WordHunterWoW_QuestEN[88699] = { title = "Powerless", description = "Their very life force is being siphoned to power the ethereals' guns, {name}! This cannot be allowed to continue.\n\nHead into the Ethereum Overcroft and free my fellow void elves from the ethereals' clutches. With their freedom, the turrets will have no power, and Turalyon will be able to launch his warframes.", objectives = "Free the captured void elves to silence the Overcroft's turrets." }
WordHunterWoW_QuestEN[88700] = { title = "Two Tons of Metal and Holy Fire", description = "Finally, the might of our warframes can be brought to bear.\n\nWith the Overcroft's air batteries silenced, our powerful warframes will be able to perform strafing runs along the spire ramparts, softening the opposition to our siege.\n\nIf you'd like, you may have the honor of piloting one of these warframes for the glory of the Light!", objectives = "" }
WordHunterWoW_QuestEN[88701] = { title = "The Memory Remains", description = "Our Vanguard forces have been harrying the Devouring Host, probing for weaknesses and gathering intelligence.\n\nUnfortunately, nearly all of them have succumbed to the Host. We are too late to help those who have fallen, but perhaps we can gather something to remember them by.\n\nWill you do this, {name}? Recover mementos of the fallen so they can be returned to those they fought to protect.", objectives = "Recover Mementos from fallen Vanguard Scouts." }
WordHunterWoW_QuestEN[88702] = { title = "Aegis of the Redeemer", description = "We're more than just an army, {name}, even if my father doesn't see that.\n\nWe're a fellowship, joined by a desire to protect those that matter to us, and those that don't have a protector of their own.\n\nAnd now, that protection extends to those wounded on the battlefield.", objectives = "" }
WordHunterWoW_QuestEN[88703] = { title = "The Night Before", description = "Vicious voidbeasts have been snatching our officers, {name}. I've been told that you saw one from afar, through Umbric's void scryer.\n\nThose beasts are steeped in void energy, using their instinctual mastery of teleportation to strike at our most vulnerable before melting back into the shadows.\n\nAlleria has gone after them, and sent a request for another pair of eyes. You can find her at a campsite at the mouth of the gorge to the east. I'll mark it on your map.", objectives = "" }
WordHunterWoW_QuestEN[88704] = { title = "The Patient Hunter", description = "These void beasts are elusive, able to open temporary void portals that they can use to move short distances instantaneously.\n\nThey may be beneath Turalyon's notice, but they're having devastating effects on the Vanguard's morale.\n\nBetween the two of us, I'm confident we can outmaneuver them.", objectives = "" }
WordHunterWoW_QuestEN[88705] = { title = "Killing Blow", description = "I heard about these beasts, but I thought it was a rumor. Void creatures appearing out of void portals, kidnapping and eating our officers... sounds like a load of bunk. I never thought it'd happen to me.\n\nThere was a big one that got me, but he ran off. Please, let's get out of here before it comes back!", objectives = "Escort Nadia safely from the cave." }
WordHunterWoW_QuestEN[88706] = { title = "Nothing Stands Forever", description = "With the Patriarch defeated, these cunning creatures should no longer pose a serious threat.\n\nReturn to Turalyon and report on our success. I will join you all shortly.", objectives = "" }
WordHunterWoW_QuestEN[88708] = { title = "Violent Conclusions", description = "Our research here is complete.\n\nConclusion: the Void is attracted to this realm due to its violent nature! The Voidstorm is a melting pot of torment and savagery. The Void was drawn to this aura of endless suffering.\n\nThis place is a dire threat to the ren'dorei. However, our mission here is important. Let us take our findings back to the others.\n\nCan you help me snap Matrean out of it?", objectives = "Convince Matrean to return to the Ingress.", progress = "We're too late, <name>. Matrean's mind is lost... and we are now duty-bound. \n\nI've known this day might come... the day my partner falls prey to the Void's corrution.\n\nPlease... can you do this for me? Find and slay the nightmare that Matrean has become.", completion = "In all our time together, I never expected Matrean would fall prey to the Void. I failed him.\n\nBut I will not fail our people again.\n\nWe should take great care in the Voidstorm and stay only as long as we must." }
WordHunterWoW_QuestEN[88709] = { title = "The Voidspire", description = "At long last, we will ride to glory and dispense justice upon this vile creature who would levy the very Void itself against us. \n\nToday is the day Xal'atath's forces will face our judgement.\n\nNow is the hour we strike back!\n\nCome, let us make an end of this enemy.", objectives = "Assault the Voidspire." }
WordHunterWoW_QuestEN[88710] = { title = "March on Quel'Danas", description = "Champion... friend... this is it. \n\nWe must wrest the Darkwell from L'ura, or fall to the Void. We do not have the forces available for a second chance. \n\nStrike hard, and strike true. Watch your allies' flanks, and we will see this day won.", objectives = "March on Quel'Danas." }
WordHunterWoW_QuestEN[88711] = { title = "Radiant Incursion: Toxins and Pheromones", description = "Our allies in Azj-Kahet have identified a strategic location to strike at the Sureki.\n\nAccording to reports, our enemies are gathering toxins to fuel their war machines.\n \nLet's take this opportunity to cut off their supplies, and perhaps better our own understanding of their alchemy.", objectives = "Aid the Flame's Radiance in disrupting the Sureki forces in the Untamed Valley.", progress = "Nerubian toxins are volatile, even for our most skill healers and medics.", completion = "Whatever it is the Sureki are gathering, we must assume it's not good.\n\nPerhaps our Sacredites can manufacture some antidotes with the samples you found.\n\nYour help is always appreciated, my friend. The Flame's Radiance burns brighter because of you." }
WordHunterWoW_QuestEN[88719] = { title = "A Voice from the Light", description = "{name}, you have been chosen.\n\nXal'atath's army of the Void has descended upon the Sunwell. We have put our faith in the Light, and in turn, the Light has called upon the greatest champions of Azeroth.\n\nAnswer this summons and stand against the Devouring Host! The fate of Quel'Danas and the world rests in your hands.", objectives = "Accept the summons and travel to Quel'Danas to aid the Vanguard of the Light.", completion = "The Light has called you, <name>. Our hope rests in the champions of Azeroth and the Vanguard of the Light!" }
WordHunterWoW_QuestEN[88750] = { title = "Tracking Quest", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[88751] = { title = "Tracking Quest", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[88752] = { title = "Tracking Quest", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[88754] = { title = "Short-Supply", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[88755] = { title = "Scholarly Pursuits", description = "{name}... a favor.\n\nMy research partner Matrean and I are studying the local wildlife and their relationship to the Void.\n\nI've concluded my findings, but Matrean--reckless and obsessive as ever--insists there is more to discover.\n\nCan you help convince him to return here?", objectives = "Meet with Kelia and Matrean in the Bladeburrows.", completion = "The Void peers back, but I shall not avert my gaze." }
WordHunterWoW_QuestEN[88768] = { title = "Agents of Darkness", description = "When that shield goes down, Xal'atath's forces will be upon us in droves. If I'm going to detonate those manacells from afar, I'll need an opening. Thin the Devouring Host of their strongest, and the rest of Xal'atath's lackeys will be easier to fight off.\n\nWe will make sure the shield goes down in the meantime. Good luck, {name}.", objectives = "Slay Nexus-King Salhadaar's lieutenants within Nexus-Point Mid'Ar.", progress = "Have you taken them out?", completion = "I hope Xal'atath was watching. It'll be her turn soon." }
WordHunterWoW_QuestEN[88769] = { title = "The Battle of the Bridge", description = "Our elven allies have arrived. It is time to take the fight to the Darkwell.\n\nXal'atath's forces hold the bridge and recently pushed into the harbor to reinforce their position. We must retake the harbor, launch our naval forces, and use a combined assault to take the bridge.\n\nAre you ready, {name}?", objectives = "" }
WordHunterWoW_QuestEN[88771] = { title = "Loaknit Alphas!", description = "", objectives = "" }
WordHunterWoW_QuestEN[88772] = { title = "Mammoth Remnants!", description = "", objectives = "" }
WordHunterWoW_QuestEN[88774] = { title = "Out of Energy", description = "", objectives = "" }
WordHunterWoW_QuestEN[88803] = { title = "Timely Assistance", description = "Hello, Champion.\n\nI have found a way that I may further assist you in the visions. Should you require it, you can call upon my assistance using this hourglass.\n\nI will form a construct that will assist you in the vision.", objectives = "Interact with the hourglass and gain Soridormi's assistance.", progress = "I hope you find this useful.", completion = "You may call upon this aid for any vision." }
WordHunterWoW_QuestEN[88804] = { title = "Defeat the Mineraw!", description = "", objectives = "" }
WordHunterWoW_QuestEN[88805] = { title = "A Scarred Path Through Time", description = "Old enemies return and battle scars open once more.\n\nDefeat these foes and return with tales of glory.", objectives = "Complete 5 Timewalking dungeons.", completion = "What news from the war front?" }
WordHunterWoW_QuestEN[88808] = { title = "A Scarred Journey Through Time", description = "Azeroth calls out in need, champion. She bleeds still from wounds of war. Go forth among Zandalar and Kul Tiras to reveal those who would prolong her suffering.\n\nVanquish foes in her name and defend Azeroth.", objectives = "Complete 5 Timewalking dungeons.", completion = "I knew I could trust in you to complete such a feat." }
WordHunterWoW_QuestEN[88818] = { title = "Void Sweeper", description = "", objectives = "" }
WordHunterWoW_QuestEN[88870] = { title = "Honored with the Bilgewater Cartel", description = "You done good for the Bilgewater so far. Keep up the good work.\n\nTalk to Rocco Razzboom, he'll take care of ya.", objectives = "Speak with Rocco Razzboom at the Scrapshop.", completion = "Hey, this is for you." }
WordHunterWoW_QuestEN[88871] = { title = "Revered with the Bilgewater Cartel", description = "You done good for the Bilgewater so far. Keep up the good work.\n\nTalk to Rocco Razzboom, he'll take care of ya.", objectives = "Speak with Rocco Razzboom at the Scrapshop.", completion = "Hey, this is for you." }
WordHunterWoW_QuestEN[88872] = { title = "Exalted with the Bilgewater Cartel", description = "You done good for the Bilgewater. We appreciate it.\n\nTalk to Rocco Razzboom, he'll take care of ya.", objectives = "Speak with Rocco Razzboom at the Scrapshop.", completion = "Hey, this is for you." }
WordHunterWoW_QuestEN[88873] = { title = "Honored with the Steamwheedle Cartel", description = "The Steamwheedle Cartel wants to thank you for your assistance. \n\nObserve all safety protocols and see Lab Assistant Laszly for a reward.", objectives = "Speak with Lab Assistant Laszly at Steamwheedle Laboratories.", completion = "We got somethin' for ya." }
WordHunterWoW_QuestEN[88874] = { title = "Revered with the Steamwheedle Cartel", description = "The Steamwheedle Cartel wants to thank you for your assistance. \n\nObserve all safety protocols and see Lab Assistant Laszly for a reward.", objectives = "Speak with Lab Assistant Laszly at Steamwheedle Laboratories.", completion = "We got somethin' for ya." }
