WordHunterWoW_QuestEN[88876] = { title = "Honored with the Blackwater Cartel", description = "The Blackwater Cartel is sailing smooth with your help. \n\nBoatswain Hardee has readied yer cut o' the plunder... that is to say, a respectable reward for your work.", objectives = "Speak with Boatswain Hardee at the Port Authority.", completion = "Here's your cut, all above board." }
