WordHunterWoW_QuestEN[88879] = { title = "Honored with Venture Co.", description = "Venture Co. is ready to pay dividends for your assistance.\n\nSpeak to Shredz the Scrapper for your reward.", objectives = "Speak with Shredz the Scrapper at Venture Plaza.", completion = "You done good, pal. This is yours." }
