WordHunterWoW_QuestEN[88974] = { title = "Eco-Stability", description = "Speakin' o' eggs, I checked an' Ember has laid her clutch. It's almost time ta hatch some babies!\n\nMeet me back at tha nest an' we can welcome our first snakelets ta K'aresh.", objectives = "Help with hatching the snakelets.", completion = "The Oasis has surpassed my expectations, <name>, and I had very high expectations indeed. Your work has been invaluable.\n\nI never suspected when I met you in the Maw that we would eventually end up here. To be frank, I expected you to perish many times over by now. \n\nRegardless, I believe we have all the species we need for our little slice of K'aresh. \n\nNow we just need to work on stabilizing the eco-system and ensuring it thrives." }
WordHunterWoW_QuestEN[88975] = { title = "Spooked Slitherin' Snakes", description = "Somethin' has the snakes agitated again. Spooked even.\n\nHow would ye feel about taking me flute back out there and calming 'em down?", objectives = "Use Hemet's Soothin' Flute to soothe 15 Agitated Snakes.", progress = "Sweet music to me ears.", completion = "Thanks for taking care o' that and entertaining the whole o' the Oasis at the same time." }
WordHunterWoW_QuestEN[88976] = { title = "The Hope of K'aresh", description = "It is finished. By all measurements, the eco-system in the Oasis is fully stable. While there will always be things we can help with, it would survive if we left it alone. \n\nTake some time and speak with everyone. Congratulate them. Good work should be properly acknowledged.\n\nSpeak with me when you are done.", objectives = "Talk to your team in the Oasis.", completion = "The work we have done here can ensure that, with what happened at Eco-Dome: Adani, we can rebuild K'aresh. \n\nIt will take time. So very much time. But I suppose that is the advantage of being immortal yes? Even if it takes tens of thousands of years, my home will be rebuilt. \n\nHopefully, I will be around to see it happen. I have a stasis pod with your name on it, should you have need of it." }
WordHunterWoW_QuestEN[88977] = { title = "Reenact the Crime", description = "Ah, you there! You appear to have the wisdom to assist me, unlike a certain bow-wielding simpleton who thinks sniffing dirt will solve our problem.\n\nWe've accidentally misplaced a very important journal--the sort my mentor would transmogrify me to have lost!\n\nPlease use my arcane timepiece to summon echoes of the past and investigate these moments. That should allow us to find my journal properly, without indulging Vardis's primitive methods.", objectives = "Use the Arcane Timepiece to investigate 3 Frozen Moments in the West Sanctum.", progress = "Impossible. My magic has never failed me before... It seems we are at an impasse.\n\nTo be thwarted by something so simple, yet so insidiously effective... is infuriating.", completion = "Wonderful--more glowing projections and angry spirits, yet still no journal.\n\nStep aside. I'm ending this nonsense and tracking it properly." }
WordHunterWoW_QuestEN[88978] = { title = "Tracking the Trail", description = "While a certain wyrm-brained mage wastes time with his inept magic, we'll actually solve this case.\n\nThe local wildlife has likely eaten the journal. Time to gut them and see if we can recover it.\n\nIf the journal's inside, we'll find it... unlike someone who couldn't track his own insipid ego if it were carved into the ground.", objectives = "Gather 8 pieces of evidence in the West Sanctum.", progress = "What do you mean none of them had the journal? How is this even possible?\n\nIt defies logic! If the wildlife didn't take it, then where in the Twisting Nether could it have gone?", completion = "That fool... That absolute fool." }
WordHunterWoW_QuestEN[88979] = { title = "Caught Red-Handed", description = "A dog, of all creatures? This is the thief we've been chasing?\n\nAnd now we must save it from a lynx? Truly, this day has taken a most... irritating turn.\n\nNo matter, we shall retrieve the journal... though I do wonder if this canine truly understands the gravity of its actions.", objectives = "Defeat the Hot-Headed Lynx in the West Sanctum.", progress = "Did you manage to retrieve the journal?", completion = "A dog, a lynx, and now a ruined journal. Truly, I've seen lesser misfortunes in my day.\n\n<Meledor pinches the slobbery journal between his fingers.>\n\nIt seems the journal's fate was sealed long before we laid eyes on it. It is quite beyond saving. Once again, my faith in anything other than arcane precision has proven... misplaced." }
WordHunterWoW_QuestEN[88980] = { title = "Who You Gonna Call?", description = "We could do with more slateback essence. \n\nI imagine that the opportunity to keep the sand of K'aresh safe would be right up your alley, yes? \n\nJust bring me back what you find after you are done.", objectives = "Collect 10 Slateback Essence in Untethered Space on K'aresh.", progress = "You have the essence?", completion = "Excellent. We can continue to create more slatebacks now." }
WordHunterWoW_QuestEN[88981] = { title = "Nesting Upkeep", description = "It's time to refresh Ember, Indigo, an' the snakelet's nest. Gotta keep our K'areshi snakes comfy.\n\nDon't worry 'bout carrying anything down there. Just like last time, we'll use one o' Ve'nari's portation tags for that.", objectives = "Refresh the nest of the two named snakes and their snakelets.", progress = "Everything good with 'em? Aren't the snakelets just adorable?", completion = "Great! Glad they're all doin' well. Such a nice, happy family." }
WordHunterWoW_QuestEN[88982] = { title = "Prey Contract: Renegade Magister", description = "A RENEGADE MAGISTER has been spotted in Voidstorm!\n\nDifficulty: Normal\n\nAffixes: 0", objectives = "" }
WordHunterWoW_QuestEN[88985] = { title = "Recuperating Returns", description = "One of our lightwood loggin' outposts is late with their weapon shipments. Dey used to be punctual, but now we are lacking crucial supplies.\n\nGo check on de camp. Somethin' must be goin' on.", objectives = "Meet Woodcrafter Azai at Zeb'Alar Lumberyard.", completion = "Another stranger, hm?" }
WordHunterWoW_QuestEN[88986] = { title = "Blind the Bandits", description = "Dis elf showed up here seekin' revenge, thinkin' we were responsible for de death of his sister.\n\nBut instead of killin' him, I'm gonna set de boy straight.\n\nDe Amani got no business with some farm!\n\nHe don't understand de Twilight's Blade is attackin' on both sides of de Zul'Aman border!\n\nI don't blame de child. He don't know dat de Twilight's Blade can hide demselves with their void powers.\n\nTake some lightwood splinters. Throw 'em on de shrouded Twilight's Blade. Show him who de real enemy is!", objectives = "Kill 8 Twilight's Blade cultists.", completion = "De boy looks confused.\n\nGood. Maybe he's thinkin'." }
WordHunterWoW_QuestEN[88987] = { title = "Salvaged Sabotage", description = "Rakani overreacted when de boy came crashin' into camp, but we all have been on edge.\n\nDe Twilight's Blade had already snuck into our camp and sabotaged our work.\n\nIt has already been challengin' to keep up with de demand for weapons. And our people need de weapons to defend themselves!\n\nIf we can get de broken weapons back, we can maybe make up for what we lost.\n\nWhile you deal with dem, see if you can get any of our weapons back--whatever condition dey are in.", objectives = "Retrieve 6 Stolen Equipment.", progress = "De chaos de elf caused is nothin' next to what we're facin' every day.\n\nWe have to be extra cautious with de Twilight's Blade tryin' to sabotage our every move.", completion = "Thank you. These recovered supplies will help us return our operation to normal.\n\nDespite de elf still bein' around..." }
WordHunterWoW_QuestEN[88988] = { title = "The Artisan's Apprentice", description = "Looks like de boy has realized there is more in dis world than his family farm an' de big bad trolls of Zul'Aman.\n\nBut I'm not done with him yet. He gonna learn hard work too. De boy needs to make up for de disruption he caused and de work we lost.\n\nIt'll be a learnin' opportunity--for de both of you.\n\nYou are goin' to make somethin' for us.\n\nPay attention. One wrong move can destroy de lightwood. With de Twilight's Blade sabotagin' our equipment, our resources are too limited already.", objectives = "Follow Woodcrafter Azai's instructions to craft a Lightwood Javelin.", progress = "De lightwood is challengin' to work with, even for experienced woodcrafters.\n\nBe patient. Be precise. And do everything I say.", completion = "Hmm. Not bad. For a novice." }
WordHunterWoW_QuestEN[88989] = { title = "Another One Bites the Sawdust", description = "Dat boy is a fool.\n\nBut he's a courageous fool.\n\nIt's time to test dis weapon you crafted.\n\nHe'll be goin' after their commander. He's killed many of my crafters, but revenge is not worth his life or dat of anyone else.\n\nGo after him before he gets himself killed.\n\nI did not go through all dis trouble just for him to die now, eh?", objectives = "Kill Covert Commander Tofir and rescue Kellor Sunshimmer.", progress = "Dat commander killed some of our own.\n\nHis troops most likely killed de boy's sister.\n\nBut even though killin' him would make craftin' weapons and sendin' dem back to Amani'Zar easier, it's not worth dat boy's life.", completion = "You saved de boy's life. And maybe now he will think before he rushes off and makes a life-endin' decision.\n\nAnd eliminatin' de head of de sabotage ring will allow us de time to make all de weapons we need.\n\nThings tend to work out for de best, eh? Even for you.\n\nHere's a little somethin' de crew and I want you to have." }
WordHunterWoW_QuestEN[88992] = { title = "Envisioned Mastery", description = "", objectives = "" }
WordHunterWoW_QuestEN[88993] = { title = "Wey'nan's Ward", description = "To claim this relic, travel to the Vale of Secrets. Seek the Visionstone. Its surface bears sacred paintings, with a hand print aglow at the center.\n\nPress your hand upon it and let your spirit be known. Your body will falter into trance, and your soul will walk visions of the past.\n\nBe warned: these visions are no mere dreams, and the dangers within may strike true.\n\nReturn to me with the wisdom you uncover.", objectives = "Travel to the indicated shrine in Harandar to meditate and experience the history of Wey'nan's Ward.", progress = "Has your journey revealed the truth of Wey'nan's Ward? Share what you have uncovered.", completion = "An incredible tale, worthy of preservation. I will set it into paint, ensuring it lives forever within the echoes of our people. Accept this memento--a token of my gratitude for your efforts.\n\nFor now, I will continue to go through our archives, seeking relics that cry out for understanding.\n\nReturn to me when the world has whispered more secrets to you." }
WordHunterWoW_QuestEN[88994] = { title = "The Cauldron of Echoes", description = "For untold eons, the Cauldron of Echoes has rested in shadow, its purpose obscured by time.\n\nWhen I first walked the path of the Zur'ashar, my master spoke of its significance--a relic tied to the very origins of our kind. Yet its secrets eluded even them... a mystery left unanswered.\n\nNow, it calls to us once more.\n\nWill you uncover what has been forgotten? The truth waits within, and I would be forever grateful for your discovery.", objectives = "Travel to the Glade of Walking Memories in Harandar to learn the history of the Cauldron of Echoes.", progress = "Has your journey revealed the truth of the Cauldron of Echoes? Share what you have uncovered.", completion = "What a remarkable story!\n\nHow ironic that the tale of Sai'alyo, the first of the Zur'ashar, was lost to time. Your efforts bring us closer to understanding this vital piece of our history.\n\nPlease, accept this keepsake as a mark of my gratitude for your dedication.\n\nFor now, I will delve deeper into our archives, uncovering relics that still long for discovery.\n\nReturn when the whispers of the world guide you back to me." }
WordHunterWoW_QuestEN[88995] = { title = "Aln'hara's Bloom", description = "When I was young in the path of a Zur'ashar, I heard a tale of a gift from Aln'hara: \"A sign of the goddess, felt in the stillness.\"\n\nUnfortunately, all those who were there to experience the event eventually passed on before we learned the secrets of our special paint.\n\nWould you walk the memory that surrounds the bloom and find out if this theory is true?", objectives = "Travel to Veilroot Clearing and uncover the truth behind Aln'hara's Bloom.", progress = "Tell me what you witnessed, and we will ensure the memory is not lost again.", completion = "What a gentle truth you have uncovered! Aln'hara did not speak with thunder, nor return in form, but in patience, she revealed her presence.\n\nYou have given voice to the voiceless, and in doing so, restored a moment to our people.\n\nPlease, take this token as a symbol of your journey.\n\nAnd should the world grow quiet once more, return. I will be listening for the next whisper." }
WordHunterWoW_QuestEN[88996] = { title = "The Echoless Flame", description = "The Echoless Flame's fate is lost to time. Down through the ages, it was whispered that the lantern contained the power of Aln'hara herself. But now, it lies dormant--a shell without even a flicker left within.\n\nPerhaps you can uncover its secrets where others have failed?\n\nRetrace the steps of Obayo, the first of the Shul'ka, and bear witness to the glory of the relic and its true purpose.", objectives = "Travel to the Verdant Sepulcher in Harandar to learn the history of the Echoless Flame.", completion = "The flames were exhausted to keep that monstrosity from destroying us all?! I'm given to understand the creature is now known as Morta'ka the Sundered Echo. How fitting.\n\nThis is both a blessing and also most unfortunate. How different might the Rift of Aln be today if the flame still danced within the lantern?\n\nPlease return soon, <name>. You and I have more to uncover." }
WordHunterWoW_QuestEN[88997] = { title = "Russula's Outreach", description = "A weather-worn spear haft, laced with pale mushroom threads, rests in silent vigil. The elders name it Russula's Outreach, yet no tale agrees on what that outreach was, or whom it spared.\n\nWas this weapon raised in fury, or lowered in mercy?\n\nThe relic offers no answers here, only a lingering pull toward the old culling grounds.\n\nFollow that pull. Trace the footsteps lost to rot and rumor, and let the visions speak of what history forgot.", objectives = "Travel to the Verdant Sepulcher to learn the history of Russula's Outreach.", progress = "Has your journey revealed the secrets of Russula's Outreach?", completion = "Russula's plea, \"Do not kill them,\" echoes far louder now that we have seen the lengths he walked, and the wounds he bore, to keep Harandar from tearing itself apart. His act tempers our own culling creed with a needed measure of mercy.\n\nYour steps restored this forgotten balance, <name>. Take this keepsake with my gratitude, and return when the land calls again. There are surely more quiet truths waiting beneath the spores." }
WordHunterWoW_QuestEN[88998] = { title = "Root of the World", description = "The Root of the World is the first gift of the land to the haranir, or so it has been said. We have forgotten much about how the staff came to be in the possession of my people. But the root of the story, if you will permit, begins at a time not long after the haranir first came to Harandar.\n\nI trust that together, we can uncover its lost past.\n\nIt is known that Ruilla the Huntress was a pivotal figure in the events that led to the creation of the staff. Go and see history through her eyes.", objectives = "" }
WordHunterWoW_QuestEN[88999] = { title = "Sky's Hope", description = "Sky's Hope: the stone that legend says fell from the sky. Little is known about it besides it being considered a symbol of hope.\n\nBut why?\n\nFollowing in the path of our ancient ancestor, Awe'ohna, might shed some light on the matter.", objectives = "" }
WordHunterWoW_QuestEN[89012] = { title = "A Safe Path", description = "We must rescue the civilians and get them to the ships, yet the path to the docks is barred by a vile, hungering creature.\n\nIf we are to save my people, then we need to clear an evacuation path. We cannot leave them to fend for themselves.", objectives = "Eliminate Gloomstress.", progress = "Does the engulfing Void still bar the way?", completion = "Thank you, <name>. These rescue missions are rarely as straightforward as they seem. There is always one more threat that appears that you didn't account for." }
WordHunterWoW_QuestEN[89016] = { title = "Members Only", description = "What can I do you for?", objectives = "Welcome to the Club! Whether it's playing or slaying you're after, our loyalty program will outfit you with the finest perks the Gallagio has to offer." }
WordHunterWoW_QuestEN[89018] = { title = "Loyal Customer: Silver", description = "What can I do you for?", objectives = "You're movin' up in the world! Let's get you an upgrade." }
WordHunterWoW_QuestEN[89019] = { title = "Loyal Customer: Gold", description = "What can I do you for?", objectives = "You're movin' up in the world! Let's get you an upgrade." }
WordHunterWoW_QuestEN[89020] = { title = "Loyal Customer: Platinum", description = "What can I do you for?", objectives = "You're movin' up in the world! Let's get you an upgrade." }
WordHunterWoW_QuestEN[89021] = { title = "Loyal Customer: Black", description = "What can I do you for?", objectives = "You're movin' up in the world! Let's get you an upgrade." }
WordHunterWoW_QuestEN[89022] = { title = "Loyal Customer: Diamond", description = "What can I do you for?", objectives = "You're movin' up in the world! Let's get you an upgrade." }
WordHunterWoW_QuestEN[89023] = { title = "Loyal Customer: GOLDEN LEGENDARY!!!", description = "What can I do you for?", objectives = "That's the last one we got! You're on top of the world, sweetheart." }
WordHunterWoW_QuestEN[89024] = { title = "Time is Money!", description = "What can I do you for?", objectives = "Chase that paper!" }
WordHunterWoW_QuestEN[89025] = { title = "Time is Money!!", description = "What can I do you for?", objectives = "Chase that paper!" }
WordHunterWoW_QuestEN[89026] = { title = "Time is Money!!!", description = "What can I do you for?", objectives = "Chase that paper!" }
WordHunterWoW_QuestEN[89027] = { title = "Fast Food", description = "What can I do you for?", objectives = "You want that to go? Have it your way!" }
WordHunterWoW_QuestEN[89028] = { title = "Chip Service", description = "What can I do you for?", objectives = "Compliments of the house! Take this to the nice Hobgoblin just across the way and pick yourself up somethin' nice." }
WordHunterWoW_QuestEN[89029] = { title = "Chip Service", description = "What can I do you for?", objectives = "This is the last one I got! Sando'll make sure you're blinged out - but maaaaaybe you might find a few more around the casino..." }
WordHunterWoW_QuestEN[89032] = { title = "Renowned with The Singularity", description = "You continue to show us that you are an integral member of our community. \n\nTo honor that bond seek me out in Iskaara as I have prepared a pack of supplies to aid you.You will receive:", objectives = "Speak with Murik in Iskaara.You continue to show us that you are an integral member of our community. \n\nTo honor that bond seek me out in Iskaara as I have prepared a pack of supplies to aid you.You will receive:" }
WordHunterWoW_QuestEN[89034] = { title = "Burning Bitterblooms", description = "Lightbloom-infested rutaani are working to spread the contamination through the village. This plant showed significant signs of the disease.\n\nDestroy any of the plants they've come into contact with. We must contain this!", objectives = "Destroy 6 Lightbloom-Infected plants in Har'mara.", progress = "The Lightbloom cannot be allowed to spread. The harmony of Har'mara is delicately balanced. We must keep it intact.", completion = "Well done, <name>. May Har'mara return to the peaceful oasis it was when we arrived." }
WordHunterWoW_QuestEN[89035] = { title = "Renowned with the Hara'ti", description = "The Hara'ti are stronger for what you have done.\n\nGo to Naynar. She will see that your deeds are remembered, and present you trophies appropriate for all you have done.You will receive:", objectives = "Speak with Naynar in the Den.The Hara'ti are stronger for what you have done.\n\nGo to Naynar. She will see that your deeds are remembered, and present you trophies appropriate for all you have done.You will receive:" }
WordHunterWoW_QuestEN[89039] = { title = "Turbo-Boost: Powerhouse Challenges", description = "<Undermine has a problem. Here's what we need. An established group, or just a bunch a ya really, ready to help out our pals in Undermine. Help clear out the worst of the competition, and we'll make it worth your time.\n\nComplete the task, and collect a special reward from Consultant Wrexxle outside of the the Dornogal Treasury. Limited time offer. Some restrictions will apply.>", objectives = "Defeat any four bosses within The Liberation of Undermine raid on Looking For Raid difficulty or higher, or complete any four Mythic Dungeons.", progress = "Yous looks out for us, and we return the favor. Right?", completion = "Thanks, pal. Undermine is a mess right now. We'll take all the help we can get.\n\nAnd hey, a deal's a deal. Here's what we owe." }
WordHunterWoW_QuestEN[89056] = { title = "Ray-ket Ball, Redux", description = "Time again to test the reflexes of our newborn. \n\nPerhaps you could play more ray-ket ball?", objectives = "Catch a ball 10 times while playing with your Necroray Pup.", progress = "You are doing me a great service by exercising that pup.", completion = "Ah, yes. Excellent. That pup is coming along nicely." }
WordHunterWoW_QuestEN[89057] = { title = "Pee-Yew de Foxy", description = "{name}! Are you ready for a repeat adventure in olfactory excellence?\n\nI've whipped up another concoction for the thorntails. This one's definitely an improvement over the last batch.\n\nWould you be the best and go give it a try?", objectives = "Douse 8 Regal Thorntails in pheromones.", completion = "Just as I expected. Better than last time! Om'talad will be pleased to receive the data.\n\nI'll get to work on improvements to the formula right away." }
WordHunterWoW_QuestEN[89061] = { title = "Making a Deposit", description = "<After defeating the devourer invasion, you pulled this solid lump of anima from their leader's stomach. \n\nVe'nari may find this useful for powering the eco-domes.>", objectives = "Deliver the Crystallized Anima to Ve'nari in the Oasis.\n\nProvided item:", completion = "An impressive kill. An even more impressive trade.\n\nYou will be rewarded. I will not have myself in your debt." }
WordHunterWoW_QuestEN[89062] = { title = "Making a Deposit", description = "<After defeating the devourer invasion, you pulled this solid lump of anima from their leader's stomach. \n\nVe'nari may find this useful for powering the eco-domes.>", objectives = "Deliver the Crystallized Anima to Ve'nari in the Oasis.\n\nProvided item:", completion = "An impressive kill. An even more impressive trade.\n\nYou will be rewarded. I will not have myself in your debt." }
WordHunterWoW_QuestEN[89063] = { title = "Making a Deposit", description = "<After defeating the devourer invasion, you pulled this solid lump of anima from their leader's stomach. \n\nVe'nari may find this useful for powering the eco-domes.>", objectives = "Deliver the Crystallized Anima to Ve'nari in the Oasis.\n\nProvided item:", completion = "An impressive kill. An even more impressive trade.\n\nYou will be rewarded. I will not have myself in your debt." }
WordHunterWoW_QuestEN[89065] = { title = "Ray-cing for the Future", description = "Looks like we've got another feisty necroray on our hands! Want to tire it out?", objectives = "Challenge the Zooming Necroray to a race and reach the finish line.", progress = "Watch it out there. That one moves quick!", completion = "My old bones ache just looking at ye tearing around like that!" }
WordHunterWoW_QuestEN[89192] = { title = "A Hard Day's Work", description = "We are running low on void shields. Your assistance is required to make a new one. \n\nMeet me outside the dome to the east. We shall craft it together.", objectives = "Assist Ve'nari in crafting a void shield outside the Oasis.", progress = "Come now. Let us begin.", completion = "Your ability to throw me the correct items is very valuable. You would not believe how frequently people lack that skill." }
WordHunterWoW_QuestEN[89193] = { title = "Arator", description = "Archbishop Alonsus Faol has left a message asking to speak with you in regards to a project to help Arator and the Vanguard of Light.", objectives = "Speak with Alonsus Faol.", completion = "Thank you for coming, <name>. I need your help, as do many of our priests and paladins.\n\nOne paladin in particular." }
WordHunterWoW_QuestEN[89194] = { title = "Shake your Bee-hind", description = "{name}--just the {race} I wanted to see! I need you to go dance for m--I mean, bees. \n\nI shall just watch you leave now.", objectives = "Dance for the bees in the Oasis.", progress = "<Alaenra appears to be silently dancing to a beat only she can hear.>", completion = "The bees already know where the plants are these days, but it cannot hurt to remind them.\n\nAlso, I do like watching you dance." }
WordHunterWoW_QuestEN[89195] = { title = "Funny Buzzness", description = "I seem to bee running low on bee puns at the moment, but I do need more bees from Stormsong Valley. Would you bee a dear and collect them for me?", objectives = "Vacuum up 20 Honey Bees to K'aresh while in Rosaline's Apiary in Stormsong Valley on Azeroth.", progress = "<Alaenra appears to be making sucking noises while holding an imaginary vacuum.>", completion = "As always, your assistance is appreciated. What? I can't drop puns every time, you know." }
WordHunterWoW_QuestEN[89197] = { title = "Ray Ranching", description = "Ah, there you are. I need to perform medical checkups on the necrorays, and I could use some assistance in capturing them. Perhaps you could help?", objectives = "Lasso 6 Tranquil Necrorays and bring them to the Hitching Post by Om'talad.", progress = "Have you captured the necrorays I require?", completion = "Thank you. For one with less limbs, you are certainly more coordinated." }
WordHunterWoW_QuestEN[89198] = { title = "Dry Cleaning", description = "Aw heck! The k'arrocs are acting all feisty again. \n\nMind giving them a good clean so their natural aroma can rise to the top?", objectives = "Wash 10 Domineering K'arrocs.", completion = "Thanks, buddy! \n\nHave you considered getting into scents? Your aroma is real strong!" }
WordHunterWoW_QuestEN[89199] = { title = "A Small Task", description = "You will forgive the lack of pleasantries, as this situation requires prompt remediation.\n\nAll you need know is that I am Aradis, wardsmith of Silvermoon. We are an order of Magisters who maintain the city's defenses.\n\nI am recovering from a... minor battle injury, and require aid charging my wardbreaker staff. You will be compensated, and perhaps provided additional opportunities to aid me.\n\nI can furnish the details as you work, so long as you are not terribly slow.", objectives = "Collect the Depleted Wardbreaker, then charge it using 4 arcane reservoirs.", progress = "Do handle the wardbreaker carefully. I will not tolerate seeing it damaged.", completion = "Making yourself useful is a prized quality in Silvermoon. You are well on your way." }
WordHunterWoW_QuestEN[89200] = { title = "Unraveling Wards", description = "Dawnblaze is keeping the blackmail documents in her study. It is highly warded, naturally.\n\nThe wards themselves are pitifully made. However, she is supplying additional power to them using arcane conduits placed throughout the city. I found the first link in the chain and brought it here to study.\n\nIt is also warded, but weakly. I theorize that if the conduits are broken in sequence, then the shields on Dawnblaze's study will be vulnerable.\n\nSabotage them, then recover the documents. Understood?", objectives = "Use the charged Wardbreaker to destroy the shields guarding 5 Warded Conduits.", completion = "As expected, my theory has been proven correct.\n\nThe only task that remains is breaking the final ward and removing those documents from Dawnblaze's possession." }
WordHunterWoW_QuestEN[89201] = { title = "Outschemed", description = "The entrance to Dawnblaze's study is in the terrace just beneath us.\n\nSince my magic can project this close to her wards, that means the magic guarding this place has been weakened... as I predicted.\n\nBreak the larger ward sealing the entrance and find the documents she forged to slander me. I will expect your expedient return to my office thereafter.", objectives = "Use the Wardbreaker to enter Magister Dawnblaze's study, then find the Incriminating Documents.", progress = "I will be taking those documents back.", completion = "You ought to be more careful with the affairs in which you entangle yourself." }
WordHunterWoW_QuestEN[89202] = { title = "Stir the Nest", description = "Aradis told you the blackmail was false? Of course. He is vying for my position. These receipts would ruin him.\n\nHe is a warlock, and we have rules about fel magic. It is not banned, but it must be used discreetly. Aradis is not discreet. Magic misuse, unsanctioned demons, fel smuggling, bribery... His list of crimes is long.\n\nBut you need not take my word for it. Aradis has earned many enemies in the city. If you can find him in the Row, a man named Jaeth could tell you all about our dear warlock.", objectives = "Question 8 Row Rats about Jaeth's whereabouts.", completion = "Gonna assume you have a particular type of business if you're asking for me by name. So spit it out." }
WordHunterWoW_QuestEN[89203] = { title = "Mutual Benefit", description = "<Jaeth waves a hand to cut you off as you explain.>\n\nAll right, Dawnblaze sent you. That means there's a job. Not surprised she doesn't want to dirty her robes coming to the Row herself. The types who hire us never do.\n\nEveryone that high up in Silvermoon backstabs each other. When it's literal, they pay us to do it for them. They get whatever power they're chasing, and we get enough coin to live another week.\n\nWhose back is getting a knife this time?", objectives = "Show Jaeth the incriminating documents about Aradis.", progress = "Come on. Spit out the details.", completion = "He tried to take me last week too. I shanked him in the gut before he ran.\n\nI chased him, but his place down by the harbor was warded with fel magic. If Dawnblaze has a way inside, I'll happily finish him off." }
WordHunterWoW_QuestEN[89204] = { title = "Five Finger Discount", description = "Aradis gave you his wardbreaker? What an idiot. Those get sold on the black market as skeleton keys. Expensive, but you have to attune them to the magic you're breaking, which isn't easy.\n\nLooks like yours is empty. We can fix that. If we pocket a few magic valuables around the city, my buddy upstairs can disenchant them and get that wardbreaker juiced with fel magic.\n\nAradis won't have anywhere to hide then.", objectives = "Help Jaeth pocket magical items from shops in the Bazaar.", progress = "This is the easy part.", completion = "Nice and clean. I've been stealing to make ends meet since I was a kid, but I don't get a partner in crime very often." }
WordHunterWoW_QuestEN[89205] = { title = "Cutting a Key", description = "I told Zanien here the whole story. He's been training warlocks for a long time--and if anyone hates sloppy ones, it's him.\n\nHe's confident he can get the wardbreaker recharged. Follow his instructions and we should be good to head out afterward.", objectives = "Attune the Wardbreaker to fel magic.", progress = "That staff should be able to break this ward now.", completion = "I'll be surprised if Aradis isn't already holed up here. But if he isn't, I'm sure we'll see him soon.\n\nWards this fancy always have alarms woven into them." }
WordHunterWoW_QuestEN[89206] = { title = "Break and Enter", description = "Can you hear that? It sounds like it's coming from downstairs. Like someone's in pain.\n\nThe last kidnapping from the Row was pretty recent. This could be where he's been keeping the people he took.\n\nMy people. My friends.\n\nEven if Aradis doesn't show his face, we're not letting him keep them here. Bring this ward down. We're going in.", objectives = "Destroy the fel magic warding Aradis's private study.", progress = "We're getting them out of here.", completion = "<Jaeth feels Sarvi's neck for a pulse, then sighs angrily.>\n\nShe's already gone. I know her brother. I'll make sure she gets returned to him.\n\nBut first, we'll make Aradis bleed." }
WordHunterWoW_QuestEN[89207] = { title = "Rats Can Bite", description = "I know all of these people. They're workers, not fighters. Aradis went after the ones who couldn't fend him off. That's why he ran when he tried to take me and realized he picked the wrong target.\n\nAfter the trouble we've made, there's no way he doesn't know we're here.\n\nBe on guard. Once he shows his face, he's dead.", objectives = "Kill Magister Aradis.", completion = "The Row will always be in danger, so long as Silvermoon turns a blind eye to us.\n\nBut for now, we're a little safer. Good riddance." }
WordHunterWoW_QuestEN[89208] = { title = "What We're Owed", description = "Everyone out here should be fine. Sarvi... I'll get her back to the Row. If we leave her here, the guards will just have the body tossed.\n\nI hope they do the same to Aradis, but I'm sure they won't.\n\nCome on. Let's go talk to Dawnblaze and get our payment. I remember where her office is.", objectives = "Inform Magister Dawnblaze that the job was completed.", progress = "I see you recruited our dear assassin to the cause. Well done.", completion = "It was a pleasure working with you, <name>." }
WordHunterWoW_QuestEN[89209] = { title = "Bu-zzz", description = "These bees are absolute workhorses--workbees? They are worker bees so I suppose... ah, apologies for my distraction.\n\nSeveral of the bees have tired themselves out. Can you return them to the hive?", objectives = "Pickup 10 Overworked Honey Bees and return them to their hive.", progress = "Goodness! They're terribly busy, aren't they?", completion = "You've finished? Then buzz off!\n\nA pun! Merely a pun!" }
WordHunterWoW_QuestEN[89210] = { title = "Photography is the Bee's Knees", description = "All right, {name}. Take this camera and this film. You've done this before. It's time for documentation!\n\nI know you are practically buzzing to get out there, but it's time to bee focused.", objectives = "Document 15 Honey Bees and the Queen Bee.", progress = "Photographing bees is marvelous when someone else does it.", completion = "Simply bee-utiful. This photo is a keeper!" }
WordHunterWoW_QuestEN[89212] = { title = "Royal Photographer", description = "<Om'talad is intently taking several photos of himself.>\n\nAh! {name}! We need to update our documentation of the thorntails. \n\nThis camera I was... testing appears to be functioning correctly. Please go update our documentation.", objectives = "Document 10 Regal Thorntails.", progress = "<Om'talad appears to be engrossed in some data from the console and is actively avoiding your gaze.>", completion = "My thanks for the update. Perhaps we omit what happened earlier from any reports to Ve'nari?" }
WordHunterWoW_QuestEN[89213] = { title = "Flights of Fancy", description = "We are in need of new photos of the k'arrocs for our records. Please take some for us while you are out in the eco-dome.", objectives = "Document 7 Domineering K'arrocs.", completion = "Excellent. You show much talent for image capturing. Thank you." }
WordHunterWoW_QuestEN[89221] = { title = "Leafing Things on the Ground", description = "I woke up today and thought to myself, \"That platter of food {name} put out for the lapbugs was excellent. I suspect the lapbugs would like it if {name} did that again.\"\n\nWhy don't you make that happen, hmm?", objectives = "Collect 7 Chopped Oasis Plant cuttings and then place 3 Plant Platters.", progress = "Have you fed the lapbugs yet?", completion = "Thanks, <name>. You are a leaf saver." }
WordHunterWoW_QuestEN[89222] = { title = "Remnant of Azeroth", description = "Upon first glance it appears to be a crystallized shard of Azeroth's life blood. Peering into the shard reveals visions of war across familiar fronts, countless lives locked in battle. The sounds of thunderous storms and crashing waves begin to overwhelm you, before coming to an eerie halt.\n\nKul Tiras calls out to you.", objectives = "Bring the Remnant of Azeroth to Churbro in Boralus.", completion = "A remnant of Azeroth from a time of conflict and strife. Such a troubled artifact has no place in the timeways, thank you for returning it." }
WordHunterWoW_QuestEN[89223] = { title = "Remnant of Azeroth", description = "Upon first glance it appears to be a crystallized shard of Azeroth's life blood. Peering into the shard reveals visions of war across familiar fronts, countless lives locked in battle. The sounds of thunderous storms and crashing waves begin to overwhelm you, before coming to an eerie halt.\n\nZandalar calls out to you.", objectives = "Bring the Remnant of Azeroth to Churbro in Dazar'alor.", completion = "A remnant of Azeroth from a time of conflict and strife. Such a troubled artifact has no place in the timeways, thank you for returning it." }
WordHunterWoW_QuestEN[89230] = { title = "A Lover Not a Fighter", description = "De elders are plannin' a festival to give thanks to de loa. I wanna ask Namaji to accompany me but....\n\nIt is tradition that a suitor give a gift that proves their prowess as a warrior. But I am a poor fighter and de others laugh at me because of it.\n\n<Kagara hangs his head dejectedly.>\n\nPerhaps you can help me? I know Namaji has always wanted a threshadon tooth necklace. De gnarldin make dem, but only de strongest have one.\n\nCould you find one for me and deliver it to her on my behalf?", objectives = "Collect a Threshadon Tooth Necklace from the gnarldin at Akil'zon's Reach.", progress = "Did you need somethin'?", completion = "Dis is from Kagara? I've always wanted one of these!\n\nI'd be happy to go to de festival wit' him. I'll finish my work here first and den go tell him myself.\n\nThank you for deliverin' dis!" }
WordHunterWoW_QuestEN[89231] = { title = "A Fighter Not a Lover", description = "You goin' to de loa festival? Young trolls like me are expected to ask someone dey like to go wit' dem. And to give a gift to show their worthiness.\n\nI wanna go wit' Namaji. I'm a great fighter, but I'm sure there are many other warriors dat wanna go wit' her!\n\nThey'll gift her trophies and spoils. But I'll be different.\n\nI think she'd like a headdress, but I have no idea how to make one. Could you make a feathered headdress for me and give it to her?\n\nYou can find feathers at Akil'zon's Reach.", objectives = "Collect 8 Eagle Feathers from Akil'zon's Reach and make an Amani Headdress.", progress = "Another gift?", completion = "A lovely headdress! From Zak'kash? Oh...\n\n<Namaji looks troubled.>\n\nBoth Zak'kash and Kagara want me to go wit' dem to de festival. What should I do?" }
WordHunterWoW_QuestEN[89233] = { title = "Love Triangle", description = "It seems we have a problem: Kagara and Zak'kash both wanna go wit' me to de festival! Which one do I choose?\n\nI like both of dem well enough. Please {name}, you need to help me! What do you think?", objectives = "Help Namaji decide who to go to the festival with.", progress = "Dey are both good choices...", completion = "Thank ya for helpin' me. Kagara, Zak'kash... I hope we can all still be friends after dis.\n\n<Namaji furrows her brow but then smiles.>\n\nI best go tell my festival partner of my decision den! Thank you again." }
WordHunterWoW_QuestEN[89238] = { title = "Follow-up Appointment", description = "There is much medical data to be gleaned in the evaluation of the k'arrocs.\n\nPlease take the condenser disc to shrink them and then pick the little ones up for easy transport.", objectives = "Shrink and collect 8 Domineering K'arrocs.", completion = "Thank you again. These k'arrocs will do quite nicely." }
WordHunterWoW_QuestEN[89240] = { title = "Dream-Dream-Dream-Dream-Dreameringeding!", description = "We need to check how the thorntails are progressing. Would you be so kind as to gather more blood samples?\n\nAs before, use the darts to put them to sleep and then retrieve the dart with the blood on it.", objectives = "Collect 5 Blood Samples from Regal Thorntails.", completion = "Excellent work. I shall proceed with the examination of these samples immediately." }
WordHunterWoW_QuestEN[89241] = { title = "Up and Up", description = "", objectives = "" }
WordHunterWoW_QuestEN[89242] = { title = "I Want a Golden Ooze!", description = "It seems our custodians have been lax in their duties once again.\n\nTake the vacuum device. Clean up the lumps. I will cut you a percentage of the returns.", objectives = "Clean 25 Congealed Lumps in the Oasis.", progress = "How go your efforts?", completion = "You never disappoint, <name>. Mostly. As promised, here is your cut." }
WordHunterWoW_QuestEN[89249] = { title = "Overwhelmed", description = "We were too late. All of the strength between us wasn't enough.\n\n<Arator looks over his shoulder, wary. Then, he crouches and places his hand on Alleria's shoulder. She responds only with a ragged exhale.>\n\nLet's fall back. The ren'dorei have been exploring the wilds while we've been following Lothraxion. We might be able to find their encampment nearby.", objectives = "Reconvene with Arator at Locus Point.", completion = "Even the power of a naaru wasn't enough..." }
WordHunterWoW_QuestEN[89250] = { title = "Burning Rubber", description = "<Few things are as exhilarating as unbridled speed, and few things are as respected as the G-99 Breakneck in Nanny Talullah's garage.\n\nMobber will certainly know how to tune your ride with the new part.>", objectives = "Speak with Mobber to tune your G-99 Breakneck.", completion = "You ready to tune that ride of yours?" }
WordHunterWoW_QuestEN[89251] = { title = "Running Hot!", description = "What can I do you for?", objectives = "Paula said you were on a real hot streak - why don't we turn up the heat?" }
WordHunterWoW_QuestEN[89252] = { title = "Need a Jump?", description = "What can I do you for?", objectives = "It's gruesome work out there on the floor, so your friends outside sent you a pick-me-up! Literally." }
WordHunterWoW_QuestEN[89254] = { title = "Shutterbug", description = "The pictures with the lapbugs were a smash hit. We need more of them for marketing.\n\nSorry, {name}. In this case, the lapbugs with hats are more in-demand than you. Do not be sad though. At least you're getting paid while also getting your face out there, yes?\n\nNow, get clicking.", objectives = "Take a S.E.L.F.I.E. with various lapbugs that are wearing hats.", progress = "Consider making the shots more interesting with your own wardrobe changes.", completion = "Excellent. I shall send these out immediately.\n\nDo not stray too far, <name>. We will need your keen eye again soon enough." }
WordHunterWoW_QuestEN[89263] = { title = "Your Cut of the Spoils", description = "You {name}? Got something for you.", objectives = "You <name>? Got something for you." }
WordHunterWoW_QuestEN[89267] = { title = "Mysterious Entity", description = "", objectives = "" }
WordHunterWoW_QuestEN[89268] = { title = "Lost Legends", description = "Among these walls lie relics, silent and forgotten, their stories obscured by time.\n\nThe path to reclaiming our past is clear: take a relic to the sacred shrines and step into the echoes of its history. The visions will guide you, letting you walk the tale firsthand and breathe life into memory once more.\n\nIf you would lend your spirit to this cause, choose a relic to reawaken its story.", objectives = "Select a relic to pursue.", completion = "So be it. Your path is set. This relic's truth awaits you." }
WordHunterWoW_QuestEN[89271] = { title = "My Son", description = "One moment, {name}. I have a personal matter. I would like you to find my son, Arator. He is a member of the Silver Hand, an accomplished paladin. \n\nI know he must have been called. His faith is strong. The Light would want him here fighting against Xal'atath.", objectives = "Find Arator and bring him to Turalyon at Light's Spire.", progress = "Have you found my son?", completion = "You found him? Thank the Light!\n\nWe can't afford distractions. I need Arator here with the assembled forces, fully focused on the assault against Xal'atath." }
WordHunterWoW_QuestEN[89274] = { title = "The Ugly Mirror", description = "", objectives = "" }
WordHunterWoW_QuestEN[89276] = { title = "Light Snacks", description = "Classics are classic for a reason, darling. One simply cannot host a worthwhile soiree without a fine selection of mana for one's guests to indulge in.\n\nThe Magisters could bring some, but mana is best when freshly siphoned. The mana wyrms in southern Eversong have a decadent brightness to them that I find particularly lovely.\n\nBe a dear and gather some for us.", objectives = "Siphon magical energy from 6 Scintillant Wyrms in the Tranquil Repose.", progress = "Time is of the essence, dear.", completion = "Ah, this shall do very nicely." }
WordHunterWoW_QuestEN[89277] = { title = "Illuminate the Space", description = "I share our dear Saltheril's love for vintage fixtures, but the lighting enchantment he is using is far too common for such an auspicious occasion.\n\nMy Magisters can create a far more stunning enchantment. Simply gather some fibers from the Lightbloom for me and I can have them broken down into spell reagents.\n\nThe effect will be marvelous.", objectives = "" }
WordHunterWoW_QuestEN[89278] = { title = "Minding Our Duty", description = "While the court does demand our consideration, we cannot forget duties. Our guests will enjoy themselves more freely if they are assured of the solidity of Eversong's defenses.\n\nThe Magisters are tasked with maintaining the runestone wards throughout Eversong. Please survey them for us and let us know if any wards need our attention.", objectives = "Inspect the integrity of 4 Runestone wards around Eversong Woods.", completion = "My dear, you are delightfully meticulous. I will assure the court that they need fear nothing." }
WordHunterWoW_QuestEN[89285] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
WordHunterWoW_QuestEN[89286] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
WordHunterWoW_QuestEN[89287] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
WordHunterWoW_QuestEN[89288] = { title = "Phase Diving: Riftbreaker Tza'akir", description = "", objectives = "" }
WordHunterWoW_QuestEN[89289] = { title = "Favor of the Court", description = "Ah, {name}, my favorite {class}! I am delighted to see you in attendance once more.\n\nYou have quite the natural talent for these sorts of affairs. The nobles are pleased with your presence and your favor has been swaying their coffers.\n\nLet us not stop a good thing, shall we? Help me choose an ally of our representatives to invite to the Haven this week. I'm ever curious to see the drama you will stir up.\n\nAs my personal guest of honor, your favor will be seen as an extension of my favor.", objectives = "Choose an ally of the Magisters, Blood Knights, Farstriders, or Shades of the Row to invite to Saltheril's Soiree this week.\n\nYour choice will determine which faction will offer \"Fortify the Runestones\" to your Warband this week.", completion = "Excellent choice.\n\nI will have my valet send for them at once." }
WordHunterWoW_QuestEN[89291] = { title = "Phase Diving: Oath-Breaker Desamirah", description = "", objectives = "" }
WordHunterWoW_QuestEN[89293] = { title = "Special Assignment: Overshadowed", description = "", objectives = "" }
WordHunterWoW_QuestEN[89294] = { title = "Special Assignment: Aligned Views", description = "", objectives = "" }
WordHunterWoW_QuestEN[89295] = { title = "The Flame Burns Eternal", description = "These Sureki sure are a persistent bunch! We need to match their persistence with our blades.\n\nCan we count on your continued support in the battles ahead?", objectives = "Complete the Nightfall scenario.", progress = "Ready yourself soldier, the battle is still to come.", completion = "You've bought us a moment of peace.\n\nRest well, but always keep your blade sharp." }
WordHunterWoW_QuestEN[89297] = { title = "Not as Cute When They Are Bigger and Angrier", description = "It seems there are some who are looking to adopt lapbugs. Adoptions mean more revenue.\n\nUltimately, this benefits the Oasis. Please acquire more essence for me.", objectives = "Collect 10 Lapbug Essence in Untethered Space on K'aresh.", progress = "Have you performed the task?", completion = "Very good, <name>. Your efforts are as appreciated and necessary as ever." }
WordHunterWoW_QuestEN[89307] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
