WordHunterWoW_QuestEN[89317] = { title = "Children's Week in Dornogal", description = "Oh, hello! You must be {name}. I can't thank you enough for stopping by to help with these little ones. \n\nSince we earthen don't have children of our own, I thought it would be fun to help some of our allies out for the week, but it turns out children are quite... energetic. I also don't have a good grasp of what children find \"fun\" yet.  \n\nIf you could take the kobold youngling with you that would be helpful. They seem to have somewhere they want to visit.  \n\nTake this whistle to call them to you.", objectives = "Speak to the orphan, Skibbles.", completion = "<Skibbles looks at you in awe, then seems to realize she's staring.>\n\nWow, you bigger and taller than kobold friends. Hello Big-Tall, my name Skibbles!\n\nMe hear you are very brave, Big-Tall. Skibbles want to be just like you! Talk-Rock say you here to help Skibbles.\n\n<Skibbles lets out a comically large gasp, her eyes going wide as if she suddenly remembered something.>\n\nYou here to take Skibbles on an adventure?? Me always want to go on adventure! Dis gonna be best day ever!" }
WordHunterWoW_QuestEN[89318] = { title = "Bold for a Kobold", description = "Big-Tall! Nice Talk-Rock tell Skibbles that she get to do whatever she want today! \n\nWell, me have big dream. One so big, me get in trouble for it. A lot. \n\n<Skibbles takes a deep breath.> \n\nMe want to be brave candle knight, like shiny humans with floaty boats! \n\nA-and me hear there is crystal that's brighter than any candle! \n\n<Skibbles pauses, seemingly anticipating rejection.> \n\nWould...would you take Skibbles to see candle knights with big kitties?", objectives = "Take Skibbles to Mereldar.", progress = "Oh, hello <name>. I've had a wonderful time chatting with the orphanage patron here. After watching the children play, I am starting to see why my previous activities weren't as exciting for the younglings I am watching. \n\nThey do not seem as interested in city tours but instead have an incredible capacity to pretend! Fascinating. \n\nOh, I almost forgot--did you get a chance to take Skibbles to see the Lamplighters?", completion = "My goodness! I have never seen Skibbles this excited! It sounds like she made quite the impression with the Lamplighters. \n\nSpeaking of children, I was watching the other Arathi children play and noticed that Destien seems more interested in his book than joining in.  \n\nPerhaps you could talk to him? Surely there is something he would rather do than stay here." }
WordHunterWoW_QuestEN[89319] = { title = "The Wondrous Weave", description = "<Destien looks at his feet as you approach.>\n\nH-hello! I'm Destien. Earthen Matron Ullna told me about you, and said you are an adventurer! You must have seen all kinds of spooky and awesome things, right?\n\nT-there is one thing I would like to do, but I'm worried it will scare people.\n\n<Destien looks around nervously and lowers his voice.>\n\n I've heard there are good nerubians and that you've met them! I've always wanted to talk to one but they scare me.\n\nWould you come with me to meet them?", objectives = "Take Destien to the Weaver's Lair to meet the Widow.", progress = "My goodness! The nerubians certainly have an interesting society. The younglings seem to be very different than the Arathi children, even though they're similar in their desire to play and get into trouble. \n\n<Ullna smiles fondly.>", completion = "My, look at Destien!  \n\nI don't think he's ever talked so much before. The nerubians must have left a strong positive impression on him indeed.  \n\nI can't wait to hear what he's learned by spending some time with you today. Who knows? Perhaps this is a small start to a better understanding between the two races. \n\nOh! The nerubian youngling, Threadis, has been eagerly awaiting you. They don't speak yet, which is common for young nerubians, but they can still communicate using other methods." }
WordHunterWoW_QuestEN[89320] = { title = "The Eager Engineer", description = "<Threadis looks up at you nervously. \n\nThey hold up what appears to be a drawing of a goblin rocket, similar to the rocket drill going to Undermine. \n\nPerhaps they would like to ride the rocket drill to Undermine located in the Ringing Deeps?>", objectives = "Take Threadis to visit the rocket drill in the Ringing Deeps.", progress = "My, this place is certainly different! It's almost the complete opposite of the Weaver's Lair. Not to mention all the colors... and smells. \n\nIt has been fun to watch the goblin children at play, though. They have more in common with the Arathi, kobold, and nerubian children than I would have imagined!  \n\nThey're certainly a handful...", completion = "Would you look at Threadis! I know they are very proud of that little bot they built, so I'm glad they were able to bring it to a place where their talents are appreciated. \n\nI'll stay here and see if I can have a chat with Professor Neltik. Why don't you take Kitzy? We'll meet you in Dornogal when you're finished!" }
WordHunterWoW_QuestEN[89321] = { title = "Recreation for Rooks", description = "Hey! You're {name}, ain't ya? My name's Kitzy! Man am I sure glad to see you. \n\nLook, I really wanna go back up to the surface to the stone city. The air is so clean and the sun is so bright!\n\nI also saw a giant blue bird fly overhead, except it had lots of legs! Ullna said it was called a...ruk? Rock? Somethin' like that.\n\nAnyway, I wanna see one! I ain't never seen anything so pretty before. Do you think I can pet one?\n\n<Kitzy gasps, her eyes shining in excitement.>\n\nDo you think I could RIDE one?", objectives = "Take Kitzy to Dornogal to see the Stormrooks.", progress = "<Ullna notices you approach and beams excitedly.> \n\n<name>, look at all of these people! They're here asking about the children we've been watching. I can't believe it. This is so exciting! \n\nLet me know when Kitzy's ready to return. We have much to discuss.", completion = "Kitzy did what? My goodness, I would have never thought to do something like that. Children are truly astounding. The bounds of their playfulness and creativity seem limitless.  \n\nThis has been such an eye-opening journey. I think I understand children a bit better through speaking to the other caretakers and especially through all you've done. \n\nI can hardly believe it, <name>. All of these people are here on behalf of Skibbles, Destien, Threadis, and now Kitzy." }
WordHunterWoW_QuestEN[89322] = { title = "A Brighter Tomorrow", description = "{name}, look at this! All of these people are here to discuss the children's futures. \n\nThey expressed a desire to speak with you as well.", objectives = "Speak to the recently arrived benefactors.", progress = "Have you had a chance to speak with the benefactors?", completion = "<name>, I can't thank you enough. All of these children look like they have bright futures ahead of them, and you played no small part in that. \n\nThanks to you, I also feel as if I understand children a bit better. They are truly wonderful, even if they are a handful at times. \n\n \n\nI know you are very busy, but I do hope we will see you next year!" }
WordHunterWoW_QuestEN[89323] = { title = "Wasted Lands", description = "Illidan taught us that if we are to fight threats that acknowledge no limits, we must be willing to do the same. With his rage he tamed the power of the fel, and so will I, with the void.\n\nA fragment from this world, touched by the All-Devouring, is held deep in the heart of North Sufaad. With the void essence Leona collected, and this fragment as a vessel, I will yoke the power of the void to my will.\n\nCombining the strength of the illidari and the secrets of the ren'dorei will make me unstoppable.", objectives = "Travel to North Sufaad.", progress = "Travel to the location of the shard in North Sufaad.", completion = "Its power begs to be released. Can't you hear it?" }
WordHunterWoW_QuestEN[89324] = { title = "A Piece of Something Greater", description = "Seek out the Relictors. They comb through these wastes like carrion feeders, sifting through proof of their people's weakness in a misguided attempt to find strength.\n\n<Adarus spits contemptuously onto the sand.>\n\nThe only object of real value is here in front of us, and they keep it contained out of fear. I will not make that mistake.\n\nGo, find these Relictors, unburden them of their keys, and return.", objectives = "Retrieve the three keys.", progress = "You've proved yourself useful so far, <class>. Continue to do so.", completion = "Retain the fragment for now.\n\nI will need it soon." }
WordHunterWoW_QuestEN[89325] = { title = "The Void Confluence", description = "At last, {name}. With the promise of this fragment's power, and my mastery over the illidari ways, I will be ready to fight the shadowguard and any other threats the void throws at us.\n\nLeona spoke of a cave near Shan'dorah where the void energies suffusing K'aresh converge.\n\nMeet us there, and play a part in my ascension.", objectives = "Meet Adarus and Leona at the ritual site inside the cave at the Fracture of Laacuna.", completion = "We're nearly prepared. Although I can't help but wonder if Adarus' reach exceeds his grasp." }
WordHunterWoW_QuestEN[89326] = { title = "Distilled Darkness", description = "Adarus is preparing his mind and body for the ritual.\n\nOur task is to place the fragment at two points within this cavern, which will both align the crystal to the void energy in the area and attract any void entities that reside nearby.\n\nDefeat those entities and their essence will be absorbed into the fragment, empowering it further.", objectives = "Align the shard of K'aresh with the void energy in the cave.", progress = "Move quickly, <name>. Time is of the essence.", completion = "Well done. I'll take it from here." }
WordHunterWoW_QuestEN[89327] = { title = "Chaos", description = "This is it, {name}. Place the K'areshi fragment above Adarus, and I will channel the void lure containing Ramon'ta's void essence into the shard.\n\nAdarus is powerful and determined, but we're attempting something both experimental and dangerous.\n\nI'll ask you to be vigilant.", objectives = "Assist Adarus and Leona with the ritual.", progress = "When you're ready, <name>.", completion = "I didn't have the time or focus to pick a destination for that portal, <name>. He could be anywhere." }
WordHunterWoW_QuestEN[89331] = { title = "Flame Fortification", description = "Sureki forces are gathering all over Hallowfall and Azj-Kahet--but we're certain they're just distractions. We think the main attack will come from the west.\n\nWhen the time comes we'll need all the help we can get to push them back and defend Mereldar.\n\nCan Flame's Radiance count on your support?", objectives = "Complete the Nightfall scenario.", progress = "Be ready, the Sureki could attack at any moment!", completion = "I knew we could count on you!" }
WordHunterWoW_QuestEN[89332] = { title = "Boot Camp", description = "The Sureki gather across Hallowfall and Azj-Kahet while we prepare for their attack on Mereldar. They want to split our forces, but we cannot ignore their activities elsewhere.\n\nThe Flame's Radiance forces are defending against their incursions in Hallowfall while we run incursions of our own into Azj-Kahet.\n\nRendezvous with the Flame's Radiance in the field and assist their efforts.", objectives = "Complete a Radiant Incursion or Sureki Incursion.", completion = "Thank the Sacred Flame for your assistance. The war continues but at least the battle is won." }
WordHunterWoW_QuestEN[89334] = { title = "Ahead of the Issue", description = "I do not know de loa Akil'zon, but she cannot be happy with de gnarldin defilin' de hash'ey shrines and makin' meals of her eagle kin.\n\nWe gotta let dem know dis is a sacred place and dat we will not take kindly to their presence here.\n\nI may not know Akil'zon, but I know de giants. All dey understand is strength--de language of Zul'Aman.\n\nOur strongest message we can send is to take de heads of their fiercest warriors.", objectives = "Collect the heads of Brulagh the Crusher, Cragward Gaahl, and Pulverizer Helthra.", progress = "Take their heads. How painful de method is between you and whatever force you worship.", completion = "<Zul'jarra takes one of the heads by the hair and admires your handiwork.>\n\nNow we're talking their language. Now dey know dat de Amani are stronger! \n\nSome may linger, but when we defeat de Twilight's Blade, we will come back for dem.\n\nKeep de heads. I have an idea how dey might be useful later." }
WordHunterWoW_QuestEN[89338] = { title = "Gathering Plowshares", description = "{name}, now that Hammerfall can expect peace with Stromgarde, there's a lot more use in being able to farm and craft than in fighting. \n\nSo, we've been gathering old weapons from past skirmishes to make into tools for the people of Hammerfall.\n\nWould you and Arator be willing to give me a hand?", objectives = "Gather 4 Fallen Longswords and 4 Forgotten Skullcleavers.", progress = "The weapons we gather will help reforge Hammerfall's future, <name>.", completion = "Excellent work, <name>. We'll get these reforged into tools, and distribute them to the people." }
WordHunterWoW_QuestEN[89343] = { title = "The Untethered Void", description = "The Reshii Wraps that the Harbinger gave you allow you to briefly transform into energy and fall into Untethered Space. This is a nightmare for all ethereals--a natural result of losing our wraps and radiating away our energy. \n\nWe can control the process by properly attuning with the Phase Conduit, letting us visit this sub-realm and return intact. That is the theory. We have tested it with K'areshi Phase Divers, but not with one of your kind.\n\nAre you willing to risk the journey to Untethered Space?", objectives = "Interact with the Phase Conduit while wearing the Reshii Wraps.", progress = "Untethered Space is beautiful to visit, but dangerous for those that are trapped there.", completion = "You learn quickly. Good. Untethered Space devours the foolish and unwise." }
WordHunterWoW_QuestEN[89344] = { title = "What Doesn't See You", description = "Untethered Space is an arcane phenomenon twisted by creatures of the Void that feed on its energy. Should we ethereals damage our wraps or the brokers their suits, our energy cannot remain intact for long. Then, we fall into this layer of reality, possibly never to return.\n\nThe upside of this nightmare is that all the energy that falls out of phase is valuable. Use the Phase Conduit to enter Untethered Space, and fight the observers that scavenge phase energy there.", objectives = "Kill Untethered Observers and collect phase energy in Untethered Space on Overlook Zo'Shuul.", progress = "Fascinating, isn't it?", completion = "Thank you, <name>. These predators from the Void ambush us and consume the very energy we use to power the eco-domes." }
WordHunterWoW_QuestEN[89345] = { title = "The Untethered Horror", description = "Void predators that have recently invaded Untethered Space are a mere annoyance compared to the ancient creatures that traveled here long ago. These primal predators feed on the energies of the remnants of old K'aresh, as well as the unfortunate K'areshi who have fallen into this state of being.\n\nThere is one such creature we call Netherdeath that haunts this rock. We have only been able to drive it away. Perhaps you have the skill to end its reign of terror?", objectives = "Slay Netherdeath in Untethered Space.", progress = "Have you rid Untethered Space of this predator?", completion = "Netherdeath is no more. Our exploration of Untethered Space can proceed. I knew you were the right person to help us in our endeavors, <name>.\n\nWe would be honored if you would continue to work with us in our exploration." }
WordHunterWoW_QuestEN[89346] = { title = "Your Cut of the Spoils", description = "You $p? Got something for you.You will receive:", objectives = "You $p? Got something for you.You will receive:" }
WordHunterWoW_QuestEN[89347] = { title = "Overcoming the Unknown: Rage-Riddled Drifter", description = "", objectives = "" }
WordHunterWoW_QuestEN[89348] = { title = "Let There Bee Love", description = "All right. I'll get these bees over to the Oasis and meet you there.", objectives = "Meet Botanist Alaenra at the Oasis.", completion = "Let's starting helping the bees get acclimated!" }
WordHunterWoW_QuestEN[89349] = { title = "Flame's Radiance Stipend", description = "", objectives = "Your exemplary service hasn't gone unnoticed, <name>. I hope this reward serves you well." }
WordHunterWoW_QuestEN[89351] = { title = "Liberation of Undermine: Splitting Pairs", description = "If you're gonna take out the Big G, you're gonna have to bust a few heads - on the very same Ogre, as a matter of fact.\n\nMug'Zee's army of goons litter the Gallagio's shadiest back rooms. If you can secure the Tower of Spades, I'll drop you and your friends off there any time you like.", objectives = "Defeat Mug'Zee, Heads of Security within Liberation of Undermine on Normal difficulty.", progress = "Thanks for your business!", completion = "Nice fightin', <name>--now let's see about that rocket ride, eh?" }
WordHunterWoW_QuestEN[89352] = { title = "Liberation of Undermine: Splitting Pairs", description = "If you're gonna take out the Big G, you're gonna have to bust a few heads - on the very same Ogre, as a matter of fact.\n\nMug'Zee's army of goons litter the Gallagio's shadiest back rooms. If you can secure the Tower of Spades, I'll drop you and your friends off there any time you like.", objectives = "Defeat Mug'Zee, Heads of Security within Liberation of Undermine on Heroic difficulty.", progress = "Thanks for your business!", completion = "Nice fightin', <name>--now let's see about that rocket ride, eh?" }
WordHunterWoW_QuestEN[89353] = { title = "Liberation of Undermine: Splitting Pairs", description = "If you're gonna take out the Big G, you're gonna have to bust a few heads - on the very same Ogre, as a matter of fact.\n\nMug'Zee's army of goons litter the Gallagio's shadiest back rooms. If you can secure the Tower of Spades, I'll drop you and your friends off there any time you like.", objectives = "Defeat Mug'Zee, Heads of Security within Liberation of Undermine on Mythic difficulty.", completion = "Nice fightin', <name>--now let's see about that rocket ride, eh?" }
WordHunterWoW_QuestEN[89354] = { title = "Preparing for Battle", description = "Void creatures have been multiplying throughout Slayer's Rise. Go help clear some out and return to me for a prize. \n\nThere are turrets that are normally used in battle that can be used to make this task easier for you.", objectives = "Kill 20 Void Creatures in Slayer's Rise.", completion = "Well done. As promised, here is your reward." }
WordHunterWoW_QuestEN[89377] = { title = "Undercover Hunt", description = "", objectives = "" }
WordHunterWoW_QuestEN[89380] = { title = "Another World", description = "I represent a group within the Trust tasked with a dangerous but vital job--Phase Diving. I was at Overlook Zo'Shuul when the Harbinger transformed you into energy. It is similar to that, but more profitable.\n\nThe Trust embarks on Phase Dives to help replenish our energy reserves. On K'aresh, energy is power--and now we must compete with the Shadowguard. We desperately need the help of someone like you.\n\nMeet me at Overlook Zo'Shuul if you are interested. We will, of course, compensate you.", objectives = "Find Shad'anis at Overlook Zo'Shuul on K'aresh.", completion = "Thank you for accepting our offer, <name>. This is dangerous work that will push you beyond the limits of our reality. But with risk we find profit, and with profit we can change the world." }
WordHunterWoW_QuestEN[89383] = { title = "One Adventurous Hatchling", description = "One of my hatchlings was frightened off when that giant construct marched past the ranch. He bolted right through the fence and into the woods before I could stop him!\n\nHe's small, fast, and probably hiding somewhere nearby. Please find him before something else does, and return him to me.", objectives = "Find the missing Hawkstrider Fledgling at Stillwhisper Pond.", completion = "Well done, <name>. I'll have that fence reinforced so he can't run off again." }
WordHunterWoW_QuestEN[89384] = { title = "A Hungry Flock", description = "Some think that raising hawkstriders is an easy task, but it most certainly is not. Hawkstrider appetites tend to be notoriously fussy!\n\nMore often than not they'll turn their beaks up at anything I offer. But this time of year? Frog legs. They love the slimy little things. They can't get enough of them!\n\nThere's a pond just down the hill just swarming with the leggy little morsels. Could you gather some for me, please?", objectives = "Gather frog legs from the Gloombelly Toads at Stillwhisper Pond.", progress = "Have you found any frogs? The hawkstriders are hungry!", completion = "I've been told frog legs taste like a curious blend of fish and poultry. I... think I will leave that fine dining experience to the hawkstriders, however. Thank you for your help!" }
WordHunterWoW_QuestEN[89385] = { title = "First Step Into Parenthood", description = "", objectives = "Not everyone would go to such lengths for these creatures.\n\nI'd like to give you something special, as thanks for your help. I think you have more than proven you can be entrusted with this.\n\nA hawkstrider egg. Not yet hatched, but there is a little one in there--wiggling, curious, and eager to meet the one who will raise it with love. Take care of it, and it will take good care of you in return." }
WordHunterWoW_QuestEN[89386] = { title = "A Roost-ed Development", description = "A comfortable hawkstrider is a happy hawkstrider. We don't expect them to stand all day. They need someplace cozy to roost!\n\nThere's a plant called golden sunleaf that sprouts just beyond the ridge. It makes the softest bedding--the hawkstriders love it. Could you gather some for me?", objectives = "Collect Golden Sunleaf at Stillwhisper Pond.", progress = "Did you find the golden sunleaf?", completion = "Oh, they'll have many a happy night's sleep on this! You have my thanks." }
WordHunterWoW_QuestEN[89388] = { title = "Voidstorm", description = "Magister Umbric has a plan to infiltrate the Voidstorm and take the fight to the Devouring Host directly.\n\nThis will be no easy task, and he is assembling a small but powerful team to strike at the enemy's heart.", objectives = "Speak with Magister Umbric in the Sanctum of Light in Silvermoon.", completion = "I hope you are ready for a challenge. This will not be easy." }
WordHunterWoW_QuestEN[89390] = { title = "Flame's Radiance Stipend", description = "", objectives = "Your service has not gone unnoticed, <name>. I hope this reward serves you well." }
