WordHunterWoW_QuestEN[89402] = { title = "Harandar", description = "With the Devouring Host occupying much of our attention and time, we leave our backs exposed to other threats that wait in the wings. This Lightbloom that has afflicted Eversong grows worse by the day. If it gets out of control, then we might find ourselves fighting a two-front conflict--or worse, having our home consumed completely while we busy ourselves with the Void.\n\nThe strange woman who you found poking about the Lightbloom... You seem to be familiar with her. Seek her out. She may have answers.", objectives = "Speak with Orweyna in Fairbreeze Village.", completion = "It is good to see you again, friend.\n\nWould that we were meeting under less fraught circumstances." }
WordHunterWoW_QuestEN[89403] = { title = "11.2.5 Delves - Mid-Season Refresh - Player Choice Affix - TEST - ZGS", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[89404] = { title = "Time Crisis", description = "You don't remember me?\n\nHmmm, shifting through time can sometimes have that side-effect.\n\nGood thing I love introductions.\n\nLet me catch you up to speed on what we're doing here.", objectives = "Talk to Moratari and then find Khadgar.", progress = "Khadgar needs your help.", completion = "<name>! You surely are a welcome sight to see on this dark day. Our teleportation spell went awry and now the Legion is invading Dalaran." }
WordHunterWoW_QuestEN[89405] = { title = "Mean Streets of Dalaran", description = "The rest of the Council and I are currently barricaded in the Chamber of the Guardian working on a solution.\n\nIn the meantime, we could use your help by taking some of the Legion's attention off us so we have time to think.\n\nOnce you've bought us enough time to properly assess the situation, join me in the Chamber of the Guardian so we can turn this situation around and put the Legion on the defensive.", objectives = "Purge demons from Dalaran.", progress = "Dalaran could use a few less demons.", completion = "Well met, <name>, and splendid work. You took the pressure off us just long enough to get a handle on this whole debacle." }
WordHunterWoW_QuestEN[89406] = { title = "Seal and Protect", description = "The citizens of Dalaran have sequestered themselves behind magical barriers that will keep the Legion at bay, for now. However, the power of the barriers is not infinite.\n\nTake my Reinforcing Ring and reinforce the barriers in order to keep our people safe. That will free me up to investigate the source of this Legion invasion.\n\nOnce you're done, keep culling the Legion's numbers. I'll contact you once I've discovered more.", objectives = "Reinforce 5 magical barriers.", progress = "Reinforcing the magical barriers should hold the Legion at bay until Khadgar can get this situation sorted out.", completion = "I think this is magnificent!\n\nYou're the perfect control group to test our theories on the importance of artifacts in the grand scheme of the flow of timelines." }
WordHunterWoW_QuestEN[89407] = { title = "Thrift", description = "If we're going to help Khadgar, Dalaran, and our experiment, we're going to need to get you an artifact.\n\nLuckily I have a plan to accomplish just this.\n\nDalaran is currently loaded with all manner of temporally important items--so called epoch objects. We'll gather up a few that won't be missed, blame their disappearance on the Legion, and then use them to get you that artifact.\n\nHere, I've made a shopping list.", objectives = "Recover the Dusty Stone Tablet, Bent and Battered Blade, and the Curious Curio for Momentus.", progress = "These objects are loaded with epoch significance.", completion = "A fine collection of epoch objects." }
WordHunterWoW_QuestEN[89408] = { title = "Threadbare", description = "To get you an artifact we'll need some temporal energy.\n\nNormally we use infinite cloaks woven from temporal threads, but those threads are frayed in this timeline. So instead I need you to gather those frayed temporal threads from around Dalaran.\n\nYou can find them popping into and out of existence here and there. They look like radiant golden orbs of power, you can't miss them.\n\nOnce you have enough of them bring them back to me.", objectives = "Collect Frayed Temporal Threads from the streets of Dalaran.", progress = "With this source of power Momentus should have what he needs to help you get an artifact.", completion = "These threads contain traces of potential epoch energy. To access their power we'll need to infuse them into a stabilizing material, such as infinite bronze, in order to anchor them in place.\n\nThey'll lose some of their potency, but at least they will be sufficient for our needs." }
WordHunterWoW_QuestEN[89409] = { title = "Infinite Bronze", description = "Now that we have the stabilizing materials and the frayed threads we can get to work.\n\nI am, however, forbidden from directly interacting with this timeline. So, you'll need to be my hands. Not to worry, nothing forbids me from giving you some guidance.\n\nHead next door to the forge inside Tanks for Everything and we'll get to work.", objectives = "Forgeinfinite bronze.", progress = "Infinite bronze, a material loaded with potential.", completion = "Now that you have infinite bronze we can get you an artifact in order to properly carry out our tests.\n\nThen you'll have no problem living up to your own legend, <name>." }
WordHunterWoW_QuestEN[89411] = { title = "Scavenger Hunting", description = "Momentus may be expert what makes things, but Erus be expert what break things!\n\n<Erus energetically punches his fist into his palm to accentuate the word \"break\".>\n\nGo. Kill demons. Take their armor scraps. Then we get to scrapping!\n\nI love scrapping.", objectives = "Loot Legion Armor Scraps from the demons around Dalaran.", progress = "One demon's trash is an infinite dragon's bronze.", completion = "Good. Good. You do well. Artifact grows stronger. Almost as strong as Erus.\n\n<Erus laughs at his own boast.>" }
WordHunterWoW_QuestEN[89412] = { title = "Get Plenty of Exorcise", description = "Khadgar is close to divining the source of the Legion presence here, but there is no guarantee that he will if the Legion's plans proceed unchallenged. The fate of Dalaran is not yet decided. All he needs is a little more time.\n\nYou can buy him that time by halting the Legion's efforts here in the city.\n\nSeek out Legion Portals and seal them. That should slow the arrival of more demons entering the city.", objectives = "Seal Legion Portals around Dalaran.", completion = "I can sense the power emanating from your artifact from here. Good.\n\nI've also noted that it hasn't fractured under the power load yet. Also good.\n\nLet me just make a note of that for Moratari's records. Very good." }
WordHunterWoW_QuestEN[89413] = { title = "Obliterate, Then Iterate", description = "Artifact is not what catches eye of Erus. No. You have demon armor scraps.\n\nNow, you might think to yourself, 'but Erus, demon armor scraps are junk', and you might be right. But Erus sees demon scraps and he does not see junk, he sees bronze. Bronze hidden in the junk.\n\nListen closely, Erus will teach you how to use the Unraveling Sands. You put junk in sands, sands unravels it, and then you get bronze from the ashes.\n\nTry using the Unraveling Sands and then toss in the Legion armor scraps.", objectives = "Use the Unraveling Sands ability to summon the Unraveling Sands, then place the Legion Armor Scraps in the sands to scrap it into Bronze.", progress = "Happy scrapping!", completion = "Bronze can be spent at the infinite bazaar on many pretty things.\n\nWhenever you find junk, just summon the Unraveling Sands.\n\nJunk goes in, pretty Bronze comes out.\n\nIs convenient, yes?" }
WordHunterWoW_QuestEN[89414] = { title = "Not A Memento Too Soon", description = "Everything is unfolding splendidly, {name}. With your artifact in hand, you should have no issues assisting Khadgar in driving the Legion fully from Dalaran.\n\nAccording to Moratari's calculations, he should have discovered the source of the Legion invasion. Return to the Chamber of the Guardian when you are ready and learn what he has discovered.", objectives = "Talk to Khadgar in the Chamber of the Guardian.", completion = "It has been a hard day, <name>, but our resolve is soon to be rewarded.\n\nWith the Legion distracted by your timely heroics, I was able to stretch out my arcane power and divine the mastermind behind the Legion incursion into our beloved city." }
WordHunterWoW_QuestEN[89415] = { title = "Storm the Citadel", description = "Fel Lord Nezmet managed to slip through our teleportation spell and open cracks within our wards.\n\nLeft unopposed, Nezmet will widen those cracks until the wards fail and the full might of the Legion is brought down upon us.\n\nWe have a chance now, to finish him before he finishes us. Cut off their head and the rest of the Legion will wither and die.\n\nHead to the Violet Citadel with all haste. There is not a moment to lose.", objectives = "Kill Fel Lord Nezmet.", progress = "With Nezmet dead, Dalaran is saved.", completion = "We make a good team, <name>.\n\nThe Kirin Tor will handle the remaining Legion forces from here. For now my attention must turn to restoring the wards to their full strength." }
WordHunterWoW_QuestEN[89416] = { title = "Eternal Gratitude", description = "Well, look at you. Saving Dalaran. You're starting to resemble your legend already.\n\n<Moratari glances about to make sure you are indeed alone before continuing.>\n\nWe have somewhere to be and people to meet.\n\nI'm opening a portal to the Infinite Bazaar.\n\n<Moratari considers the name for a moment.>\n\nIt's a place where we're safe to congregate out in the open without interfering with the timeline. Just step through when you're ready.", objectives = "Step through the portal and meet Eternus and the infinite dragonflight.", completion = "Moratari has kept me apprised of your endeavors in this timeline, <name>.\n\nKnow that I am pleased.\n\nDalaran will recover in time. Speaking of, I will accelerate the timeline until after the cleanup is complete." }
WordHunterWoW_QuestEN[89417] = { title = "Infinite Meetings", description = "There, Dalaran is back to how it should be.\n\nI'm sure you have many questions, {name}. Who are we? What are we doing here? Why are you here?\n\nThe simple answer is this: We are the Infinite, we are searching through time for answers to questions larger than any of us, and we need your help to do it.\n\nI think you will come to understand this answer more if you meet the rest of our flight. Moratari, if you would make the introductions?", objectives = "Tour the Infinite Bazaar.", progress = "As their name would suggest, the infinite dragonflight is certainly not lacking in numbers.", completion = "As you can see, <name>, there are many minds at work here in the infinite dragonflight. Minds that are all working to answer some pressing questions.\n\nWhat knowledge can we gain to prepare us for even greater threats?\n\nWould we have triumphed if things had been worse?\n\nWhat are the implications of Sargeras's sword being plunged into Azeroth, and was it the artifacts that saved Azeroth or something else?\n\nEr, I mean... Forget I said anything. What sword?" }
WordHunterWoW_QuestEN[89418] = { title = "A Fixed Point in Time", description = "By now, the Legion will have been fully purged from Dalaran and events will begin unfolding. Events that require your presence, {name}.\n\nMoratari will take you back to Krasus' Landing. There your legend will continue to grow.\n\nI see great potential in you, {name}. No matter which timeline you're from.", objectives = "Talk to Moratari and return to Krasus' Landing.", completion = "And here we are, back where it all started.\n\nIn a moment a messenger will come looking for you and your legend will begin to unfold.\n\n<Moratari smiles broadly at you, beaming with excitement.>\n\nAren't you excited? I know I am.\n\nOh, and if you need anything, just come by the Infinite Bazaar. We're always waiting.\n\nGood luck!" }
WordHunterWoW_QuestEN[89420] = { title = "Horrific Visions Revisited", description = "", objectives = "" }
WordHunterWoW_QuestEN[89440] = { title = "Protecting the Flank", description = "", objectives = "" }
WordHunterWoW_QuestEN[89441] = { title = "Clear the Decks", description = "", objectives = "" }
WordHunterWoW_QuestEN[89450] = { title = "Create a Neighborhood", description = "You know what they say: it takes a neighborhood!\n\nDo they not say that? Well, they should.\n\nGather signatures from like-minded settlers and found your own neighborhood!", objectives = "Gather charter signatures from players, then create your new neighborhood!\n\nUse the Neighborhood Charter quest item to open your charter.", completion = "Congratulations! Make the most of your new community." }
WordHunterWoW_QuestEN[89464] = { title = "Infinite Research: Combat Studies, Comprehensive", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a comprehensive study, so feel free to fight whatever you wish so that we can get a baseline understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "Kill 200 enemies.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, <name>. Moratari will be overjoyed to see these new data points." }
WordHunterWoW_QuestEN[89465] = { title = "Infinite Research: No Task Too Small", description = "Heroic deeds are a matter of perspective. What may seem trivial to a mighty hero such as you, could mean the world to another.\n\nSeek out those in need and aid them in whatever task they deem important. In doing so your legend will grow.", objectives = "Complete 6 quests.", completion = "Your name is on the minds of the people, and is shared around the fire. The greater your legend becomes, the more powerful your name will be. But does the power of one's name eclipse that of the artifact they wield? This is the burning question." }
WordHunterWoW_QuestEN[89466] = { title = "Infinite Research: Time to Raid, Light's Breach", description = "We require information about how multiple timerunners and their artifacts interact when faced with powerful opposition.\n\nSeek out others to help you conquer Light's Breach.", objectives = "Complete the Light's Breach wing of Antorus, the Burning Throne on any difficulty.", completion = "The sum strength of a group of timerunners armed with potent artifacts is greater than that of the individuals. Much greater than anticipated. Intriguing." }
WordHunterWoW_QuestEN[89467] = { title = "Infinite Research: Time to Raid, Forbidden Descent", description = "We require information about how multiple timerunners and their artifacts interact when faced with powerful opposition.\n\nSeek out others to help you conquer Forbidden Descent.", objectives = "Complete the Forbidden Descent wing of Antorus, the Burning Throne on any difficulty.", completion = "The sum strength of a group of timerunners armed with potent artifacts is greater than that of the individuals. Much greater than anticipated. Intriguing." }
WordHunterWoW_QuestEN[89468] = { title = "Infinite Research: Dungeoneers Wanted, Normal", description = "Despite all the power in your artifact, $p, remember that there is strength in numbers.\n\nGather a group of timerunners and seek out concentrations of power that if faced alone would overwhelm you. Then report back, if you survive.", objectives = "Complete any Normal dungeon using the Dungeon Finder.", progress = "Fear is expected, but results are necessary. Find a group and face the terror. If not for me, then do it for Moratari and the data points.", completion = "You have no idea how happy this will make Moratari." }
WordHunterWoW_QuestEN[89469] = { title = "Infinite Research: Dungeoneers Wanted, Heroic", description = "Some places are dangerous to go even in good company. You'll need great company to survive.\n\nGather a group of timerunners and seek out concentrations of power that if faced alone would overwhelm you. Then report back, if you survive.", objectives = "Complete any Heroic dungeon using the Dungeon Finder.", progress = "Fear is expected, but results are necessary. Find a group and face the terror. If not for me, then do it for Moratari and the data points.", completion = "You have no idea how happy this will make Moratari." }
WordHunterWoW_QuestEN[89476] = { title = "Infinite Research", description = "", objectives = "" }
WordHunterWoW_QuestEN[89490] = { title = "Warrant: Arcana-Monger So'zer", description = "Arcana-Monger So'zer is responsible for a spree of thefts throughout Tazavesh that have resulted in the loss of magic relics, wands, and several crates of highly toxic Zo'kita fruit.\n\nInformants suggest that So'zer may be compelled to reveal himself if presented with a highly prized arcane relic.\n\nCreate an item tempting enough to trick this criminal into revealing themselves.", objectives = "Combine an Arcane Runed Sigil with a Charged Crystal and a Smuggler's Mark to create an Arcane Lure to reveal So'zer." }
WordHunterWoW_QuestEN[89492] = { title = "Worldsoul: Dastardly Duos in the Dome!", description = "That's right, the Dastardly Duos are here!\n\nShow your support! Talk to Xyggie Marou in Dornogal and sign up to fight a Dastardly Duos match.\n\nFrom there, wait until you're called and away you go! Show them what you got, hero!", objectives = "Beat the Dastardly Duos, then speak with Vinnie Sweets.", completion = "And that is how it's done! You put on a good show, friend.\n\nFeel free to sign up as much as you want, because you're good business!" }
WordHunterWoW_QuestEN[89493] = { title = "Welcome to the Field", description = "", objectives = "Welcome, cadet! Glad to have you here. \n\nNo time like the present to get in there. Fight the Sureki with everything you've got--we're counting on you." }
WordHunterWoW_QuestEN[89494] = { title = "A Frocking Good Job", description = "", objectives = "<name>! Glad you could make it. I wanted to formally congratulate you on your new position within our ranks.\n\nYou've more than earned this, demonstrating courage and traits that show great promise as you continue serving Flame's Radiance.\n\nOn that note, please accept and don this tabard in your future endeavors. We look forward to seeing you on the battlefield." }
WordHunterWoW_QuestEN[89496] = { title = "Defender of the Sacred Flame", description = "", objectives = "You've certainly proven yourself in our fight against the Sureki, <name>.\n\nYour courage and willingness to defend the Sacred Flame is remarkable, and your martial prowess has helped turn the tide of battle more times than I've been able to count.\n\nFor that, I award you this tabard. Please accept it as an emblem and acknowledgement of your undying persistence." }
WordHunterWoW_QuestEN[89501] = { title = "Charged Crystal", description = "An arcane charged crystal is not an item you will find in K'aresh, but there is a way we can make one!\n\nA small helper I know can help you harvest and store arcane energy. If you return that energy and an uncharged crystal to me, we can make a charged crystal.\n\nGain Myi Koo's assistance, then travel through the ethereal portal to the Azure Vaults. Collect the energy and crystal.", objectives = "Meet with Myi Koo, enter the Archival Assault delve, and collect 6 Arcane Energy Samples and an Uncharged Crystal.", progress = "Have you collected the crystal and the required energy?", completion = "Myi Koo is fully charged with arcane energy. More than enough to charge a crystal." }
WordHunterWoW_QuestEN[89502] = { title = "Worldsoul: Nightfall", description = "The remaining Sureki are rampaging around Hallowfall and Azj-Kahet, but we believe they are gathering forces west of the Veneration Grounds so that they can strike Mereldar directly!\n\nPlease join Flame's Radiance in their defense and put down this Sureki threat!", objectives = "Complete the Nightfall scenario." }
WordHunterWoW_QuestEN[89503] = { title = "Somber Siblings", description = "Iz'ken left us many years ago, {name}. Preparin' may be tense, but at least we won't have to do it alone.\n\nFirst, we need to collect de spores of de weepin' mushrooms. You can get dem from the mushrooms, or de boars.\n\nI'll be usin' dem to create incense for de ritual.\n\nBe careful, {name}--de boars might be unhappy when we take their food.", objectives = "Collect 30 Weeping Spores from Weeping Caps or boars in the Solemn Valley.", progress = "They're called weepin' spores, because when dey burn dey make your eyes water.\n\nDe spores give our warriors a good excuse if dey are too cowardly to admit their feelings at de pyre.", completion = "I asked for you help without tellin' you about how my mother treated my brother and me. I don't speak much about my family. I learned not to.\n\nI still don't understand why she was the way she was. Maybe somethin' happened to her. Somethin' that'd cause all dat pain... Maybe pain and chaos were all she knew herself.\n\nBut in de tribe, she inspired many--at least she can remain a mother to dem." }
WordHunterWoW_QuestEN[89505] = { title = "Smuggler's Mark", description = "An upstanding citizen such as Om'sto, would not have such an illegal item like a Smuggler's Mark.\n\nIf I did acquire one...I would be inclined to give it to someone that I owe a debt to. \n\nIf you did me a favor, and then I would be in your debt.\n\nTravel to North Sufaad, and fill my pack with items I lost there. You do this, and I may have what you need.", objectives = "Find enough lost items in North Sufaad to fill Om'sto's pack.", progress = "Have you recovered all my items?", completion = "As I promised I will settle this debt with the mark you require. When placed on an item the mark indicates to others that the transaction is approved by cartel officials." }
WordHunterWoW_QuestEN[89506] = { title = "Strong Ties", description = "Next we need to collect sinew from giants. De sinew makes sure de bonfire is not gonna fall apart, and de act of risking ya life against a powerful foe honors de fallen.\n\nI am a tested warrior, so do not worry for me. But please make sure Iz'ken does not come to harm from de giants.", objectives = "Collect 3 Resilient Sinew from mountain giants in the Solemn Valley.", progress = "De sinew of mountain giants is a strong buildin' material.\n\nBut we only use it for dis one purpose, because it's dangerous to get and there are not enough giants.", completion = "At first when Iz'ken left us, I thought mother didn't care. Even at her deathbed she never once mentioned him.\n\nBut she felt guilty when he left. Her tantrums toward me carried de shame, I think.\n\nI wish she could have admitted it, but I knew that would neva' happen.\n\nOur tribe sees mother as unstoppable... fearless.\n\nBut sometimes it's what's inside dat's hardest to face." }
WordHunterWoW_QuestEN[89507] = { title = "Abundant Offerings", description = "We have been called on yet again by de Loa of Abundance!\n\nSeek, harvest, and provide offerings at any of the abundance sites in Eversong, Zul'Aman, Harandar, or Voidstorm.\n\nI will provide you with the appropriate glory when the Harvest Lord has been satisfied.", objectives = "Earn 20,000 points in Abundance harvests.", completion = "Excellent work.\n\nYou are quickly becoming a model acolyte for He Who Guides Harvests." }
WordHunterWoW_QuestEN[89513] = { title = "Kindling Aplenty", description = "Next, we need to collect de logs for our bonfire. Kan'sha, de large tree at de end of de valley, was infected with poison from a stray arrow long ago.\n\nShe's quite tough. To survive, she sheds her branches regularly.\n\nIn a way, Kan'sha has become a regular part of our rituals. Her strong wood burns warm and hot--like Amani blood.\n\nIt is perfect for bonfires.", objectives = "Collect 4 Fallen Branches around Kan'sha in the Solemn Valley.", progress = "Do not worry for Kan'sha. She has outlived generations of trolls, and de druids say she'll survive many more.", completion = "Kan'sha's been a long-time friend, and I spend many of my nights restin' here under her pines when I can't go home.\n\nOur tribe warns folks to be watchin' for her falling branches, but dey never hit me. Not one scar or bruise came from her." }
WordHunterWoW_QuestEN[89514] = { title = "Worldsoul: Horrific Visions Revisited", description = "This Black Blood that has corrupted the nerubians is nasty stough. \n\nI hear that it is not the first time that the Old Gods have used this blood.\n\nA new visitor to Dorgogal, Soridormi of the Bronze Dragons, has found a way for you to revisit this past event.\n\nSeek her out to relive these Horrific Visions and learn what you can. \n\nKeep your eyes open {name}. Any info you can learn will surely aid us today.", objectives = "Defeat 5 bosses inside Horrific Visions Revisited.", completion = "I am glad you made it back safe. I know if we keep looking we will find a key to ending the void's corruption." }
WordHunterWoW_QuestEN[89515] = { title = "Renowned with Flame's Radiance", description = "You continue to inspire us on the battlefield, <name>. Your heroic deeds have kept our people safe during these trying times, and we cannot thank you enough.", objectives = "Speak with Lars Bronsmaelt in Morgaen's Tears.", completion = "I hope you continue to take pride in your service, as well as this small token of our appreciation." }
WordHunterWoW_QuestEN[89516] = { title = "Infinite Research: Assault on Violet Hold, Normal", description = "A team of timerunners, armed with potent artifacts, can overcome many threats.\n\nLet us see whether you can handle this incarnation of Assault on Violet Hold.", objectives = "Complete Assault on Violet Hold on Normal difficulty or higher.", progress = "Well, you aren't dead. That's a good sign.", completion = "Very good results. Exceeds expectations." }
