WordHunterWoW_QuestEN[89540] = { title = "Infinite Research: Timeworn Keystone Dungeon", description = "We have taken the liberty of temporally locking certain locations in order to conduct more refined and varied experiments within.\n\nWe call them Timeworn Keystone Dungeons.\n\nIf you are ready, then simply seek one of them out. I would be pleased to include you in these experiments.", objectives = "Complete a Timeworn Keystone Dungeon.", completion = "That was quite the experiment. I admit, I was not sure what to expect, but it was not that." }
