WordHunterWoW_QuestEN[89559] = { title = "Reasonless Worship", description = "Ahead is an old shrine. Nobody knows anymore what we worshipped there or why, but it was a place my mother loved.\n\nIt would honor her if we put a stone from it on de pyre with her.", objectives = "Collect a Weathered Shrine Piece.", progress = "We both know dat de shrine is a place dat pleased our mother.\n\nI can't say she knew dat much about us.", completion = "The others in de tribe still revere mother and mourn her death.\n\nBut since she died, I've mostly just been missin' Iz'ken.\n\nShe drove my brother away.\n\nBut... her death has brought him back. At least for dis ritual." }
